window.__DAILY_CHUNKS__[1] = [{"week":1,"level":"A1","theme":"语音入门：字母、音符与拼读规律","days":[{"day":1,"theme":"发音 · 字母与音符","type":"listen","steps":[{"type":"listen","title":"26 个字母的法语读音","body":"法语字母的名字和英语不同：<span class=\"fr\" data-fr=\"g\">g</span> 读 /ʒe/、<span class=\"fr\" data-fr=\"j\">j</span> 读 /ʒi/、<span class=\"fr\" data-fr=\"r\">r</span> 读 /ɛʁ/、<span class=\"fr\" data-fr=\"y\">y</span> 读 /i ɡʁɛk/。先完整听一遍字母表，再分 a–m、n–z 两组跟读。读到 <span class=\"fr\" data-fr=\"bonjour\">bonjour</span>（你好）时注意第一个音节的元音，别按英语的习惯读。","src":"phonetics.html#alphabet","hint":"跟读三遍，边读边写字母","quiz":[{"id":"q-list-a1-5001","level":"A1","skill":"listening","prompt":"字母 b 的法语读法是？","options":["/be/","/bi/","/bɛ/"],"answer":"/be/","explain":"法语字母 b 读 /be/；/bi/ 是英语的读法，/bɛ/ 不对应任何字母名。","source":"语音 · 字母表"},{"ref":"bank:listening:A1:听力"}]},{"type":"speak","title":"四种音符：é è ê ç 各管什么","body":"四种音符各司其职：é 是闭口音（café），è 与 ê 是开口音（mère、être），ç 只在 a / o / u 前表示 /s/（français）。音符不是装饰，它同时决定读音和拼写。跟读 <span class=\"fr\" data-fr=\"café\">café</span>、<span class=\"fr\" data-fr=\"mère\">mère</span>、<span class=\"fr\" data-fr=\"français\">français</span> 各三遍。","src":"phonetics.html#alphabet","hint":"每个音对比读三遍","quiz":[{"id":"q-speak-a1-5001","level":"A1","skill":"speaking","prompt":"「你好」在法语里怎么说？","options":["bonjour","bonsoir","bonne nuit"],"answer":"bonjour","explain":"bonjour 用于白天问候；bonsoir 用于傍晚之后；bonne nuit 是睡前道别。","source":"词汇 · 问候语"},{"ref":"bank:speaking:A1:口语"}]},{"type":"listen","title":"字母听写与默写","body":"把字母表按四行一组默写，边写边读名字；再听写 10 个字母组合（如 <span class=\"fr\" data-fr=\"g\">g</span>, <span class=\"fr\" data-fr=\"j\">j</span>, <span class=\"fr\" data-fr=\"r\">r</span>）。出错集中在 g / j、e / i 这些相邻音上，说明听觉分辨还没建立，需要回到 <span class=\"fr\" data-fr=\"phonetics.html#alphabet\">phonetics.html#alphabet</span> 重听。","src":"phonetics.html#alphabet","hint":"听写 10 个字母组合","quiz":[{"ref":"bank:listening:A1:听力"}]},{"type":"read","title":"拼读规则：词末辅音与 CaReFuL","body":"词末辅音多数不发音，但 c、r、f、l 常常发音，记作 CaReFuL。<span class=\"fr\" data-fr=\"au revoir\">au revoir</span>（再见）的词末 r 就要读出来，而像 salut 那样词末的 t 则完全不发音——读音和拼写不一致，只能靠多听固化。","src":"phonetics.html#lecture","hint":"把 CaReFuL 写在便利贴上","quiz":[{"ref":"bank:reading:A1:阅读"}]},{"type":"speak","title":"自我介绍第一句","body":"用 <span class=\"fr\" data-fr=\"Bonjour, je m'appelle…\">Bonjour, je m'appelle…</span> 说出名字，再补一句 <span class=\"fr\" data-fr=\"Je suis chinois.\">Je suis chinois.</span>（女性用 chinoise）。这两句里 <span class=\"fr\" data-fr=\"bonjour\">bonjour</span> 和 <span class=\"fr\" data-fr=\"je\">je</span> 都要读干净，不要拖音，也不要在词末加英语式的儿化音。","src":"dialogue.html#d01","hint":"录音并回听，注意词末不拖音","quiz":[{"ref":"bank:speaking:A1:口语"}]}]},{"day":2,"theme":"发音 · 音素与联诵","type":"speak","steps":[{"type":"speak","title":"元音对立：tu / tout / tôt","body":"/y/ 与 /u/ 是两个不同的音：<span class=\"fr\" data-fr=\"tu\">tu</span> 与 <span class=\"fr\" data-fr=\"tout\">tout</span>、dessus 与 dessous。练法是先发 /i/，保持舌头位置把嘴唇圆起来，得到的就是 /y/。每天做 10 组对立练习，比单练一个音有效得多。","src":"phonetics.html#voyelles","hint":"每天 10 组对立练习","quiz":[{"id":"q-list-a1-5002","level":"A1","skill":"listening","prompt":"é 这个音符的作用是？","options":["表示闭口音 /e/","表示鼻化元音","表示字母 c 读 /s/"],"answer":"表示闭口音 /e/","explain":"é 标记闭口音 /e/，如 café；鼻化元音是元音字母加 n/m；ç 才表示 /s/。","source":"语音 · 音符"},{"ref":"bank:speaking:A1:口语"}]},{"type":"listen","title":"鼻化元音 on / an / in","body":"鼻化元音是「元音 + n/m」合成的一个音，词末的 n 不单独发音。<span class=\"fr\" data-fr=\"bonjour\">bonjour</span> 里是 /ɔ̃/，<span class=\"fr\" data-fr=\"français\">français</span> 里是 /ɑ̃/，<span class=\"fr\" data-fr=\"vin\">vin</span> 里是 /ɛ̃/。注意 bon 与 bonne：多写一个 n 并加上 e，鼻化就消失了。","src":"phonetics.html#nasales","hint":"bon 与 bonne 对照读","quiz":[{"id":"q-speak-a1-5002","level":"A1","skill":"speaking","prompt":"「谢谢」用法语说是？","options":["merci","pardon","au revoir"],"answer":"merci","explain":"merci 是谢谢；pardon 用于道歉或引起注意；au revoir 是再见。","source":"词汇 · 礼貌用语"},{"ref":"bank:listening:A1:听力"}]},{"type":"speak","title":"联诵三类规则","body":"联诵分三类：必须（les amis、vous avez）、可选（名词与形容词之间常可联可不联）、禁止（et 与后面、名词主语与动词之间）。对照读 <span class=\"fr\" data-fr=\"les amis\">les amis</span>、<span class=\"fr\" data-fr=\"vous avez\">vous avez</span>、<span class=\"fr\" data-fr=\"et il\">et il</span> 三组，感受 /z/ 与 /t/ 的出现位置。","src":"phonetics.html#liaison","hint":"三组对照各读 5 遍","quiz":[{"ref":"bank:speaking:A1:口语"}]},{"type":"listen","title":"数字 0–20 听写","body":"数字 0–20 最容易错的是 6（six）和 10（dix）的词末辅音，以及 17–19 的连写 dix-sept、dix-huit、dix-neuf。听写 20 组后对照，把错的数字当天重听 5 遍，直到不再需要思考。","src":"dialogue.html#d11","hint":"20 组听写，错的当天重听","quiz":[{"ref":"bank:listening:A1:听力"}]},{"type":"write","title":"抄写并标读音提示","body":"从本周词表挑 10 个词抄写，每词旁边写读法提示，例如 <span class=\"fr\" data-fr=\"bonjour\">bonjour</span>（你好）、<span class=\"fr\" data-fr=\"merci\">merci</span>（谢谢）、<span class=\"fr\" data-fr=\"s'il vous plaît\">s'il vous plaît</span>（请）。标不出读法的词说明你还没听清，回到 <span class=\"fr\" data-fr=\"phonetics.html#phonemes\">phonetics.html#phonemes</span> 查音素表对照。","src":"phonetics.html#phonemes","hint":"10 个词，一音一标记","quiz":[{"ref":"bank:writing:A1:写作"}]}]},{"day":3,"theme":"精听 · 对话页的 d01、d02 篇","type":"listen","steps":[{"type":"listen","title":"精听（第一遍）：抓主旨","body":"打开 对话页的 d01、d02 篇，盲听第一遍，不暂停、不看文本。只听一个问题：这段话在谈什么？用中文写一句概括，再写下 3 个听清的词。","src":"dialogue.html#d01","hint":"不暂停、不看文本","quiz":[{"id":"q-list-a1-5003","level":"A1","skill":"listening","prompt":"法语词末辅音中通常要发音的一组是？","options":["c, r, f, l","s, t, d, x","e, s, z"],"answer":"c, r, f, l","explain":"词末 c、r、f、l 常发音（记作 CaReFuL），s、t、d、x、z、e 通常不发音。","source":"语音 · 拼读规则"},{"ref":"bank:listening:A1:听力"}],"exam":"exam:listening:A2:车站广播"},{"type":"listen","title":"精听（第二遍）：听写关键句","body":"第二遍逐句暂停，听写 5 句含本周语法或新词的句子，写不出的地方标「?」。然后对照原文，把 ? 处按「词汇 / 联诵 / 语速」三类归档。本周的听力任务是：本周听力任务是字母表与数字 0–20：每天 15 分钟跟读，周末做到听到字母能写下来、听到数字能写对。","src":"dialogue.html#d01","hint":"逐句听写 5 句","quiz":[{"ref":"bank:listening:A1:听力"}]},{"type":"vocab","title":"听力词汇回收","body":"把听写中出现的生词与本周词表对照：<span class=\"fr\" data-fr=\"bonjour\">bonjour</span>（你好）、<span class=\"fr\" data-fr=\"merci\">merci</span>（谢谢）、<span class=\"fr\" data-fr=\"au revoir\">au revoir</span>（再见）。反复出现的词优先记，只出现一次又不影响理解的先放过，避免在细节里迷路。","src":"vocab.html#t1","hint":"生词与本周词表对照","quiz":[{"ref":"bank:vocab:A1:人与身份"}]},{"type":"speak","title":"影子跟读 3 遍","body":"同一段材料做影子跟读（shadowing）：滞后原音半句跟读，重点模仿语调、连读与联诵，不要逐字念。跟完录 45 秒复述，不回看原文，卡住就用 <span class=\"fr\" data-fr=\"c'est-à-dire\">c'est-à-dire</span> 争取时间。","src":"exams.html#oral","hint":"滞后半句跟读，录 45 秒复述","quiz":[{"ref":"bank:speaking:A1:口语"}]},{"type":"listen","title":"精听（第三遍）：闭合听力","body":"第三遍只听不看，听完用法语说出 3 个关键信息，再写一句「字母与音符 在这段里出现的位置」。仍听不懂的句子重复听 2 次，还不懂就记下来，第 7 天集中解决。","src":"dialogue.html#d01","hint":"只听不看，说出 3 个关键信息","quiz":[{"ref":"bank:listening:A1:听力"}]}]},{"day":4,"theme":"口语 · 字母、音符与拼读规律","type":"speak","steps":[{"type":"speak","title":"口语任务：本周主题陈述","body":"口语任务：把 bonjour / bonsoir / merci / au revoir / pardon 说得自然，再用两句介绍姓名与国籍。 开口前先想好「观点—理由—例子」三段，允许说得慢，但不许说到一半换主题。说完立刻自评一句：哪一段最流畅、哪一段最卡，卡住的地方就是下一次的训练重点。","src":"exams.html#oral","hint":"先说满 60 秒不停","quiz":[{"id":"q-speak-a1-5003","level":"A1","skill":"speaking","prompt":"自我介绍时「我叫……」应该说？","options":["Je m'appelle…","Je suis appelle…","Moi appeler…"],"answer":"Je m'appelle…","explain":"s'appeler 是代词式动词，je 对应 je m'appelle；appeler 不能脱离自反代词使用。","source":"词汇 · 自我介绍"},{"ref":"bank:speaking:A1:口语"}]},{"type":"speak","title":"结构与衔接：先列提纲再开口","body":"把答案录在手机里，先说满 60 秒不停。说到一半忘词就先换一种说法把意思顶过去，流利度优先于用词精确。录完不要马上回听，隔十分钟再听一遍，判断会更客观。","src":"exams.html#oral","hint":"三个关键词 + 三段衔接词","quiz":[{"ref":"bank:speaking:A1:口语"}]},{"type":"listen","title":"听范例找差距","body":"听一段同主题范例（对话页的 d01、d02 篇），把自己的录音和范例逐项对比：语速、停顿位置、连接词的使用、字母与音符 的正确形式。只记录 3 个今天就能改的点。","src":"dialogue.html#d01","hint":"只记 3 个可立刻改进的点","quiz":[{"ref":"bank:listening:A1:听力"}]},{"type":"vocab","title":"把新词用进嘴里","body":"把 <span class=\"fr\" data-fr=\"s'il vous plaît\">s'il vous plaît</span>（请）、<span class=\"fr\" data-fr=\"pardon\">pardon</span>（对不起；请问）、<span class=\"fr\" data-fr=\"monsieur\">monsieur</span>（先生）轮流塞进刚才的答案里，每个词至少用一次。说不顺就说明这个词还没真正归属你，回到 vocab.html#t1 再看一遍例句。","src":"vocab.html#t1","hint":"每个新词至少用一次","quiz":[{"ref":"bank:vocab:A1:人与身份"}]},{"type":"speak","title":"重录一遍并自评","body":"按前面记录的 3 个问题重录一次，目标是同样的内容用更少的停顿说完。回听时数一数填充词（euh、ben、voilà）出现几次，第 7 天把两次录音放在一起比较。","src":"exams.html#oral","hint":"数一数填充词次数","quiz":[{"ref":"bank:speaking:A1:口语"}]}]},{"day":5,"theme":"精读 · 字母、音符与拼读规律","type":"read","steps":[{"type":"read","title":"精读：本周阅读材料","body":"精读任务：读发音页第 1–4 节，掌握 26 个字母的法语读音与四种音符的功能。 读第一遍只抓主旨，第二遍才处理细节，遇到生词先猜再查。读完先用一句话写出全文主旨，再回头处理细节，避免一开始就陷进生词里。","src":"exams.html#lecture","hint":"第一遍抓主旨，第二遍抓细节","quiz":[{"id":"q-read-a1-5001","level":"A1","skill":"reading","prompt":"下列哪个词的词末辅音不发音？","options":["salut","sac","mer"],"answer":"salut","explain":"salut 词末的 t 不发音，读 /saly/；sac 的 c 与 mer 的 r 都属于要发音的 CaReFuL。","source":"语音 · 词末辅音"},{"ref":"bank:reading:A1:阅读"}]},{"type":"read","title":"长句解构：先找主干","body":"挑文中 3 个超过 20 词的长句，先划出主谓宾，再把从句、分词、介词短语逐层挂上去。看到「字母与音符」的结构就停下来确认触发条件。","src":"exams.html#lecture","hint":"拆 3 个长句，主干与修饰分栏","quiz":[{"ref":"bank:reading:A1:阅读"}]},{"type":"vocab","title":"阅读词汇：上下文猜词","body":"遇到生词先按词根、词尾和上下文猜一次再核对。本周词表里的 <span class=\"fr\" data-fr=\"bonjour\">bonjour</span>（你好）、<span class=\"fr\" data-fr=\"merci\">merci</span>（谢谢）如果以别的形式出现，把那一整句抄进卡片。","src":"vocab.html#t1","hint":"先猜再查，把整句抄下来","quiz":[{"ref":"bank:vocab:A1:人与身份"}]},{"type":"grammar","title":"语法在句子里的样子","body":"回到 phonetics.html#alphabet，对照文中出现的同类结构，确认书面语和口语的差别。摘抄 3 句可以直接套进写作的句子，标注它们的连接词和语式。","src":"phonetics.html#alphabet","hint":"摘 3 句能直接用的句子","quiz":[{"ref":"bank:grammar:A1:现在时"}]},{"type":"write","title":"100 词摘要","body":"不照抄原句，用 100 词概括文章并加一句自己的评价。写完统计三个数字：平均句长、连接词数量、「字母与音符」出现次数，看看自己的书面语是不是只会并列短句。","src":"exams.html#ecrit","hint":"改写不照抄，统计三个数字","quiz":[{"ref":"bank:writing:A1:写作"}]}]},{"day":6,"theme":"写作 · 字母、音符与拼读规律","type":"write","steps":[{"type":"write","title":"写作任务：本周产出","body":"写作任务：抄写 30 个高频词并为其中 10 个标读法提示，音符一个都不能漏。 先列提纲再动笔，写完整篇留 5 分钟只做一遍通读检查。动笔前先确认题目要求写几段、用什么语域，避免写到一半推翻结构。","src":"exams.html#ecrit","hint":"先列提纲，再限时成文","quiz":[{"id":"q-writ-a1-5001","level":"A1","skill":"writing","prompt":"抄写「请」这个词，正确写法是？","options":["s'il vous plaît","sil vous plait","s'il vous plait"],"answer":"s'il vous plaît","explain":"s'il 需要省音撇号，plaît 带长音符 î，两处都不能省写。","source":"词汇 · 礼貌用语"},{"ref":"bank:writing:A1:写作"}]},{"type":"write","title":"提纲与逻辑链","body":"先写中文要点，再逐条译成法语，但译完必须回头改：把中文语序的句子打散重写，让动词和它的补语各就各位。改完把最生硬的 3 句抄到一边，作为下一稿的重点对象。","src":"exams.html#ecrit","hint":"三段式提纲，每段一个论点","quiz":[{"ref":"bank:writing:A1:写作"}]},{"type":"grammar","title":"写前语法自查清单","body":"打开 phonetics.html#alphabet，把本周语法点做成 3 条自查项写在旁边，例如「触发词有没有用对」「变位与配合是否一致」。写完通读只检查这 3 条，其余问题留到第二稿再处理。","src":"phonetics.html#alphabet","hint":"三条自查项，只查这三条","quiz":[{"ref":"bank:grammar:A1:现在时"}]},{"type":"read","title":"对照范文找可替换表达","body":"读考试页的范文，列出 10 处「我只会用简单说法、范文用了更地道说法」的对照，抄进表达本。重点看范文怎么用「字母与音符」和连接词，对照表按「我的说法 / 范文说法 / 适用场景」三列记录。","src":"exams.html#redaction","hint":"抄 10 组对照表达","quiz":[{"ref":"bank:reading:A1:阅读"}]},{"type":"speak","title":"把写的文章讲出来","body":"脱稿把自己写的文章讲 2 分钟，允许简化但不许背稿。讲不顺的句子说明书面结构还没内化，回到文中改写一次，再讲一遍；同时把 <span class=\"fr\" data-fr=\"bonjour\">bonjour</span>（你好）用进口语版本。","src":"exams.html#oral","hint":"脱稿讲 2 分钟，不背稿","quiz":[{"ref":"bank:speaking:A1:口语"}]}]},{"day":7,"theme":"复盘 · 字母、音符与拼读规律","type":"review","steps":[{"type":"review","title":"本周回顾：语音入门：字母、音符与拼读规律","body":"这一周围绕「语音入门：字母、音符与拼读规律」展开：语法主线是 字母与音符，词汇主线是 人与身份。先用 3 句话口头复述本周学了什么，再打开日历页第 1 周清单逐条核对里程碑。","src":"calendar.html#wk-1","hint":"先口头复述，再核对里程碑","quiz":[{"ref":"bank:vocab:A1:人与身份"}]},{"type":"review","title":"语法复盘：字母与音符","body":"从 phonetics.html#alphabet 的规则与例句里各抽 3 条：默写规则、翻译例句再对照，最后写下 2 个自己最可能犯的错。凡是默写时卡住的地方，就是下一周要带着继续练的问题。","src":"phonetics.html#alphabet","hint":"默写规则与例句，各抽 3 条","quiz":[{"ref":"bank:grammar:A1:现在时"}]},{"type":"review","title":"词汇自测：人与身份","body":"遮住中文看 vocab.html#t1 的 6 个核心词：<span class=\"fr\" data-fr=\"bonjour\">bonjour</span> <span class=\"fr\" data-fr=\"merci\">merci</span> <span class=\"fr\" data-fr=\"au revoir\">au revoir</span> <span class=\"fr\" data-fr=\"s'il vous plaît\">s'il vous plaît</span> <span class=\"fr\" data-fr=\"pardon\">pardon</span> <span class=\"fr\" data-fr=\"monsieur\">monsieur</span>。能秒答的划掉，犹豫超过 3 秒的抄进错词本。本周目标是新词认词率不低于 85%。","src":"vocab.html#t1","hint":"遮中文秒答，犹豫即抄错词本","quiz":[{"id":"q-vocab-a1-5001","level":"A1","skill":"vocab","prompt":"「先生」用法语说是？","options":["monsieur","madame","mademoiselle"],"answer":"monsieur","explain":"monsieur 是先生（缩写 M.）；madame 是女士；mademoiselle 现已很少使用。","source":"词汇 · 称谓"},{"id":"q-vocab-a1-5002","level":"A1","skill":"vocab","prompt":"「再见」用法语说是？","options":["au revoir","bonjour","merci"],"answer":"au revoir","explain":"au revoir 是告别用语；bonjour 是问候；merci 是道谢。","source":"词汇 · 问候语"},{"ref":"bank:vocab:A1:人与身份"}]},{"type":"review","title":"综合题（一）：听读理解","body":"先做下面的听读综合题，不查词、不回看材料，限时 5 分钟。做完再回材料定位每道题的证据句，把「没找到证据就选」的题目标出来——那是失分的主要来源。","src":"dialogue.html#d01","hint":"限时 5 分钟，做完回材料找证据","quiz":[{"id":"q-list-a1-5004","level":"A1","skill":"listening","prompt":"听到 /ʒuʁ/ 时最可能是哪个词？","options":["jour","toujours","bonjour"],"answer":"jour","explain":"/ʒuʁ/ 只有一个音节；bonjour 开头是鼻化元音 /ɔ̃/；toujours 是 /tuʒuʁ/，以 /t/ 起头。","source":"语音 · 音素辨析"},{"id":"q-read-a1-5002","level":"A1","skill":"reading","prompt":"数字 17 的正确写法是？","options":["dix-sept","dix sept","disset"],"answer":"dix-sept","explain":"17 写作 dix-sept，中间必须有连字符；17–19 都是这种连写形式。","source":"词汇 · 数字"},{"ref":"bank:listening:A1:听力"}]},{"type":"review","title":"综合题（二）：语法与词汇","body":"这一组题检查 字母与音符 与本周词汇的调用能力。每道题都问自己：错误选项错在哪里？能说出错因才算真的会，说不出来就回到 phonetics.html#alphabet 再核对一次。","src":"phonetics.html#phonemes","hint":"每题都说出错项错在哪","quiz":[{"id":"q-gram-a1-5001","level":"A1","skill":"grammar","prompt":"法语字母 j 的读音是？","options":["/ʒi/","/dʒe/","/i/"],"answer":"/ʒi/","explain":"法语 j 读 /ʒi/；/dʒe/ 是英语读法；/i/ 是字母 i。","source":"语音 · 字母表"},{"id":"q-gram-a1-5002","level":"A1","skill":"grammar","prompt":"e 上加长音符 ê 表示什么音？","options":["开口音 /ɛ/","闭口音 /e/","鼻化元音"],"answer":"开口音 /ɛ/","explain":"ê 与 è 一样表示开口音 /ɛ/，如 être；é 才是闭口音 /e/。","source":"语音 · 音符"},{"ref":"bank:grammar:A1:现在时"}]},{"type":"review","title":"输出任务与自评表","body":"完成一段 90 秒口述或 120 词短文，内容必须同时用上本周的 2 个词和 1 个语法结构。按「任务完成 / 连贯 / 词汇 / 语法 / 拼写」五项各打 1–5 分，低于 3 分的写进下周补漏清单。","src":"exams.html#oral","hint":"五项各打 1–5 分","quiz":[{"ref":"bank:writing:A1:写作"}]}]}]},{"week":2,"level":"A1","theme":"音素系统：元音、鼻化元音与联诵","days":[{"day":1,"theme":"词汇 · 家庭与关系","type":"vocab","steps":[{"type":"vocab","title":"主题词汇域：家庭与关系","body":"家庭与关系（La famille et les relations）是这一周要反复见面的主题域。打开 vocab.html#t2，先看词表怎么分组，再把 <span class=\"fr\" data-fr=\"un ami\">un ami</span>（一个男性朋友）、<span class=\"fr\" data-fr=\"une amie\">une amie</span>（一个女性朋友）、<span class=\"fr\" data-fr=\"la famille\">la famille</span>（家庭）读三遍，然后遮住中文说意思。记不住的词单独建一张「顽固词表」。","src":"vocab.html#t2","hint":"先读后抄，每个词出声读三遍","quiz":[{"id":"q-vocab-a1-5003","level":"A1","skill":"vocab","prompt":"「家庭」用法语说是？","options":["la famille","la femme","la maison"],"answer":"la famille","explain":"la famille 是家庭；la femme 是妻子或女人；la maison 是房子。","source":"词汇 · 家庭"},{"ref":"bank:vocab:A1:家庭与关系"}]},{"type":"vocab","title":"搭配与辨析：le père / la mère","body":"<span class=\"fr\" data-fr=\"le père\">le père</span>（父亲）与 <span class=\"fr\" data-fr=\"la mère\">la mère</span>（母亲）是本组最容易混的两个词。为每个词写 2 个搭配（一个名词搭配、一个动词搭配），读出来判断哪个更自然，拿不准的留到第 7 天复盘。","src":"vocab.html#t2","hint":"两个词各写 2 个搭配","quiz":[{"id":"q-vocab-a1-5004","level":"A1","skill":"vocab","prompt":"« les enfants » 的意思是？","options":["孩子们","童年","学生们"],"answer":"孩子们","explain":"les enfants 是孩子的复数；l'enfance 才是童年；les élèves 是学生。","source":"词汇 · 家庭"},{"ref":"bank:vocab:A1:家庭与关系"}]},{"type":"listen","title":"听音辨词：家庭与关系","body":"打开 对话页的 d03、d07 篇，先盲听一遍，只做一件事：抓出含本周新词的句子并写下关键词。第二遍再对照法文原文，检查自己漏掉的是词还是联诵。像 <span class=\"fr\" data-fr=\"les enfants\">les enfants</span>（孩子们）这样的词如果没听出来，单独标出来。","src":"dialogue.html#d03","hint":"盲听一遍再对照原文","quiz":[{"ref":"bank:listening:A1:听力"}]},{"type":"speak","title":"口头造句：6 个新词进短句","body":"用今天抄的 6 个词各说一句，主语在 je / nous / on 之间换着用。参考例句 <span class=\"fr\" data-fr=\"C'est l'ami de mon père.\">C'est l'ami de mon père.</span>（这是我父亲的朋友。）。录 60 秒，回听时只挑两个问题：冠词有没有丢、动词有没有跟主语配合。","src":"exams.html#oral","hint":"录音 60 秒并回听","quiz":[{"ref":"bank:speaking:A1:口语"}]},{"type":"vocab","title":"日终自测：家庭与关系 认词","body":"遮住中文，只看法语说意思：<span class=\"fr\" data-fr=\"un ami\">un ami</span> <span class=\"fr\" data-fr=\"une amie\">une amie</span> <span class=\"fr\" data-fr=\"la famille\">la famille</span> <span class=\"fr\" data-fr=\"le père\">le père</span> <span class=\"fr\" data-fr=\"la mère\">la mère</span> <span class=\"fr\" data-fr=\"les enfants\">les enfants</span>。说不出来的词立刻回到 vocab.html#t2 重记一遍，并在卡片角上打一个星号，星号词明天先复习。","src":"vocab.html#t2","hint":"先遮中文，再遮法语，两个方向各过一遍","quiz":[{"ref":"bank:vocab:A1:家庭与关系"}]}]},{"day":2,"theme":"语法 · 联诵三类规则","type":"grammar","steps":[{"type":"grammar","title":"语法点：联诵三类规则","body":"【联诵三类规则】联诵是前一词词末原本不发音的辅音与后一词开头的元音连读，分必须、可选、禁止三类；省音是 le / la / je / de 在元音或哑音 h 前丢掉元音，写成 l' / j' / d'。这两条是口语里的「隐形语法」。 例句：<span class=\"fr\" data-fr=\"C'est l'ami de mon père.\">C'est l'ami de mon père.</span>（这是我父亲的朋友。）；<span class=\"fr\" data-fr=\"J'aime beaucoup ce film.\">J'aime beaucoup ce film.</span>（我很喜欢这部电影。）。对照 phonetics.html#liaison 的表格，把规则抄成自己的一句话。","src":"phonetics.html#liaison","hint":"先读规则再看例句","quiz":[{"id":"q-gram-a1-5003","level":"A1","skill":"grammar","prompt":"« les amis » 中 les 与 amis 之间要？","options":["必须联诵，读 /lezami/","禁止联诵","可联可不联"],"answer":"必须联诵，读 /lezami/","explain":"冠词 les 与元音开头的名词之间是必须联诵，s 读 /z/。","source":"语音 · 联诵"},{"ref":"bank:grammar:A1:现在时"}]},{"type":"grammar","title":"规则拆解与常见错误","body":"对着 phonetics.html#liaison 自查三件事：① 触发条件是什么；② 变位或配合落在哪个词尾；③ 有哪些例外要单独记。然后把 <span class=\"fr\" data-fr=\"C'est l'ami de mon père.\">C'est l'ami de mon père.</span>（这是我父亲的朋友。）拆到词，逐一说明每个成分为什么用这个形式。","src":"phonetics.html#liaison","hint":"合上书默写一遍规则","quiz":[{"id":"q-gram-a1-5004","level":"A1","skill":"grammar","prompt":"下列哪一项是省音？","options":["l'ami","le ami","les ami"],"answer":"l'ami","explain":"le 在元音开头的名词前丢掉 e 写成 l'，这就是省音；le ami 不是合法写法。","source":"语音 · 省音"},{"ref":"bank:grammar:A1:现在时"}]},{"type":"read","title":"在短文里找联诵三类规则","body":"在 phonetics.html#liaison 的例句和章末小测里挑 5 句，圈出所有属于「联诵三类规则」的成分。读的时候先判断结构再理解意思，不要一开始就在脑子里翻译成中文。","src":"phonetics.html#liaison","hint":"圈出全部相关成分","quiz":[{"ref":"bank:reading:A1:阅读"}]},{"type":"write","title":"限时仿写：8 句","body":"照 <span class=\"fr\" data-fr=\"C'est l'ami de mon père.\">C'est l'ami de mon père.</span>（这是我父亲的朋友。）的句型仿写 8 句，内容必须是你自己的真实信息。写完用三色笔检查：红色圈主语、蓝色圈动词、绿色圈配合成分，联诵三类规则 的结构至少出现两次。","src":"exams.html#ecrit","hint":"限时 12 分钟，写完自查","quiz":[{"ref":"bank:writing:A1:写作"}]},{"type":"grammar","title":"语法点巩固：连音与省音","body":"今天再回 phonetics.html#enchainement 看一遍 连音与省音，把两个语法点的差别写成一行对照（触发条件 / 形式 / 常见错误各一列）。写不出来就说明还停留在「读得懂」而不是「用得出」。","src":"phonetics.html#enchainement","hint":"把两个语法点写成对照表","quiz":[{"ref":"bank:grammar:A1:现在时"}]}]},{"day":3,"theme":"精听 · 对话页的 d03、d07 篇","type":"listen","steps":[{"type":"listen","title":"精听（第一遍）：抓主旨","body":"第一遍听的时候不要追求每个词都懂。对话页的 d03、d07 篇 的材料先听三分钟，抓住说话人、场景和态度，其余细节留到第二遍。听之前先用 10 秒预测这段话会出现哪些本周词汇，带着预测去听，抓取效率会明显提高。","src":"dialogue.html#d03","hint":"不暂停、不看文本","quiz":[{"id":"q-list-a1-5005","level":"A1","skill":"listening","prompt":"« vous avez » 的正确读法是？","options":["/vuzave/","/vuave/","/vusave/"],"answer":"/vuzave/","explain":"vous 与 avez 之间必须联诵，s 读 /z/，整体读作 /vuzave/。","source":"语音 · 联诵"},{"ref":"bank:listening:A1:听力"}],"exam":"exam:listening:A2:车站广播"},{"type":"listen","title":"精听（第二遍）：听写关键句","body":"第二遍逐句暂停，听写 5 句含本周语法或新词的句子，写不出的地方标「?」。然后对照原文，把 ? 处按「词汇 / 联诵 / 语速」三类归档。本周的听力任务是：用对话页前 4 篇 A1 对话做三遍精听，逐句标记哪里必须联诵、哪里禁止联诵。","src":"dialogue.html#d03","hint":"逐句听写 5 句","quiz":[{"ref":"bank:listening:A1:听力"}]},{"type":"vocab","title":"听力词汇回收","body":"把听写中出现的生词与本周词表对照：<span class=\"fr\" data-fr=\"un ami\">un ami</span>（一个男性朋友）、<span class=\"fr\" data-fr=\"une amie\">une amie</span>（一个女性朋友）、<span class=\"fr\" data-fr=\"la famille\">la famille</span>（家庭）。反复出现的词优先记，只出现一次又不影响理解的先放过，避免在细节里迷路。","src":"vocab.html#t2","hint":"生词与本周词表对照","quiz":[{"ref":"bank:vocab:A1:家庭与关系"}]},{"type":"speak","title":"影子跟读 3 遍","body":"同一段材料做影子跟读（shadowing）：滞后原音半句跟读，重点模仿语调、连读与联诵，不要逐字念。跟完录 45 秒复述，不回看原文，卡住就用 <span class=\"fr\" data-fr=\"c'est-à-dire\">c'est-à-dire</span> 争取时间。","src":"exams.html#oral","hint":"滞后半句跟读，录 45 秒复述","quiz":[{"ref":"bank:speaking:A1:口语"}]},{"type":"listen","title":"精听（第三遍）：闭合听力","body":"第三遍只听不看，听完用法语说出 3 个关键信息，再写一句「联诵三类规则 在这段里出现的位置」。仍听不懂的句子重复听 2 次，还不懂就记下来，第 7 天集中解决。","src":"dialogue.html#d03","hint":"只听不看，说出 3 个关键信息","quiz":[{"ref":"bank:listening:A1:听力"}]}]},{"day":4,"theme":"口语 · 元音、鼻化元音与联诵","type":"speak","steps":[{"type":"speak","title":"口语任务：本周主题陈述","body":"口语任务：影子跟读 4 篇对话各 3 遍，重点模仿语调与联诵，再把听到的联诵点复述出来。 开口前先想好「观点—理由—例子」三段，允许说得慢，但不许说到一半换主题。说完立刻自评一句：哪一段最流畅、哪一段最卡，卡住的地方就是下一次的训练重点。","src":"exams.html#oral","hint":"先说满 60 秒不停","quiz":[{"id":"q-speak-a1-5004","level":"A1","skill":"speaking","prompt":"« tu » 与 « tout » 的区别在于？","options":["元音 /y/ 与 /u/","元音 /i/ 与 /e/","辅音 /t/ 的清浊"],"answer":"元音 /y/ 与 /u/","explain":"tu 的元音是 /y/（舌尖抵下齿、嘴唇收圆），tout 是 /u/（舌位靠后）。","source":"语音 · 元音对立"},{"ref":"bank:speaking:A1:口语"}]},{"type":"speak","title":"结构与衔接：先列提纲再开口","body":"用 30 秒写 3 个关键词当提纲，再用 <span class=\"fr\" data-fr=\"d'abord\">d'abord</span> / <span class=\"fr\" data-fr=\"ensuite\">ensuite</span> / <span class=\"fr\" data-fr=\"enfin\">enfin</span> 把三段串起来。卡壳时用 <span class=\"fr\" data-fr=\"c'est-à-dire\">c'est-à-dire</span> 或 <span class=\"fr\" data-fr=\"disons que…\">disons que…</span> 争取时间，不要用中文思考再翻译。","src":"exams.html#oral","hint":"三个关键词 + 三段衔接词","quiz":[{"ref":"bank:speaking:A1:口语"}]},{"type":"listen","title":"听范例找差距","body":"听一段同主题范例（对话页的 d03、d07 篇），把自己的录音和范例逐项对比：语速、停顿位置、连接词的使用、联诵三类规则 的正确形式。只记录 3 个今天就能改的点。","src":"dialogue.html#d03","hint":"只记 3 个可立刻改进的点","quiz":[{"ref":"bank:listening:A1:听力"}]},{"type":"vocab","title":"把新词用进嘴里","body":"把 <span class=\"fr\" data-fr=\"le père\">le père</span>（父亲）、<span class=\"fr\" data-fr=\"la mère\">la mère</span>（母亲）、<span class=\"fr\" data-fr=\"les enfants\">les enfants</span>（孩子们）轮流塞进刚才的答案里，每个词至少用一次。说不顺就说明这个词还没真正归属你，回到 vocab.html#t2 再看一遍例句。","src":"vocab.html#t2","hint":"每个新词至少用一次","quiz":[{"ref":"bank:vocab:A1:家庭与关系"}]},{"type":"speak","title":"重录一遍并自评","body":"按前面记录的 3 个问题重录一次，目标是同样的内容用更少的停顿说完。回听时数一数填充词（euh、ben、voilà）出现几次，第 7 天把两次录音放在一起比较。","src":"exams.html#oral","hint":"数一数填充词次数","quiz":[{"ref":"bank:speaking:A1:口语"}]}]},{"day":5,"theme":"精读 · 元音、鼻化元音与联诵","type":"read","steps":[{"type":"read","title":"精读：本周阅读材料","body":"精读任务：读发音页的音素总表与鼻化元音章节，把元音按口型分组抄成一页。 读第一遍只抓主旨，第二遍才处理细节，遇到生词先猜再查。读完先用一句话写出全文主旨，再回头处理细节，避免一开始就陷进生词里。","src":"exams.html#lecture","hint":"第一遍抓主旨，第二遍抓细节","quiz":[{"id":"q-read-a1-5003","level":"A1","skill":"reading","prompt":"「bon」与「bonne」的读音关系是？","options":["bon 鼻腔出气，bonne 不鼻化","两者读音相同","bonne 更加鼻化"],"answer":"bon 鼻腔出气，bonne 不鼻化","explain":"加一个 n 并补上 e 之后鼻化消失：bon 读 /bɔ̃/，bonne 读 /bɔn/。","source":"语音 · 鼻化元音"},{"ref":"bank:reading:A1:阅读"}]},{"type":"read","title":"长句解构：先找主干","body":"把长句按「主干 + 修饰」两栏抄写：左栏只留主谓宾，右栏按顺序列出从句与补语。拆完再合起来读一遍，语序感会明显变好。判断不出从句类型时，先整段框起来，读完上下文再回来标注。","src":"exams.html#lecture","hint":"拆 3 个长句，主干与修饰分栏","quiz":[{"ref":"bank:reading:A1:阅读"}]},{"type":"vocab","title":"阅读词汇：上下文猜词","body":"遇到生词先按词根、词尾和上下文猜一次再核对。本周词表里的 <span class=\"fr\" data-fr=\"un ami\">un ami</span>（一个男性朋友）、<span class=\"fr\" data-fr=\"une amie\">une amie</span>（一个女性朋友）如果以别的形式出现，把那一整句抄进卡片。","src":"vocab.html#t2","hint":"先猜再查，把整句抄下来","quiz":[{"ref":"bank:vocab:A1:家庭与关系"}]},{"type":"grammar","title":"语法在句子里的样子","body":"回到 phonetics.html#liaison，对照文中出现的同类结构，确认书面语和口语的差别。摘抄 3 句可以直接套进写作的句子，标注它们的连接词和语式。","src":"phonetics.html#liaison","hint":"摘 3 句能直接用的句子","quiz":[{"ref":"bank:grammar:A1:现在时"}]},{"type":"write","title":"100 词摘要","body":"不照抄原句，用 100 词概括文章并加一句自己的评价。写完统计三个数字：平均句长、连接词数量、「联诵三类规则」出现次数，看看自己的书面语是不是只会并列短句。","src":"exams.html#ecrit","hint":"改写不照抄，统计三个数字","quiz":[{"ref":"bank:writing:A1:写作"}]}]},{"day":6,"theme":"写作 · 元音、鼻化元音与联诵","type":"write","steps":[{"type":"write","title":"写作任务：本周产出","body":"写作任务：为 40 个词标读法提示，凡记不住读音的词单独列进「顽固词表」。 先列提纲再动笔，写完整篇留 5 分钟只做一遍通读检查。动笔前先确认题目要求写几段、用什么语域，避免写到一半推翻结构。","src":"exams.html#ecrit","hint":"先列提纲，再限时成文","quiz":[{"id":"q-writ-a1-5002","level":"A1","skill":"writing","prompt":"« j'aime » 中的撇号表示什么？","options":["省音（je 的 e 被省略）","所有格","缩写符号"],"answer":"省音（je 的 e 被省略）","explain":"je 在元音开头的动词前丢掉 e 写成 j'，这是省音，与所有格无关。","source":"语音 · 省音"},{"ref":"bank:writing:A1:写作"}]},{"type":"write","title":"提纲与逻辑链","body":"动笔前把提纲写成三段式：每段一个论点，每个论点配一个具体例子。检查连接词是否多样，别整段只用 et 和 mais。提纲写完后放一分钟再看一遍，如果一句话就能说清每段的作用，结构就算过关。","src":"exams.html#ecrit","hint":"三段式提纲，每段一个论点","quiz":[{"ref":"bank:writing:A1:写作"}]},{"type":"grammar","title":"写前语法自查清单","body":"打开 phonetics.html#liaison，把本周语法点做成 3 条自查项写在旁边，例如「触发词有没有用对」「变位与配合是否一致」。写完通读只检查这 3 条，其余问题留到第二稿再处理。","src":"phonetics.html#liaison","hint":"三条自查项，只查这三条","quiz":[{"ref":"bank:grammar:A1:现在时"}]},{"type":"read","title":"对照范文找可替换表达","body":"读考试页的范文，列出 10 处「我只会用简单说法、范文用了更地道说法」的对照，抄进表达本。重点看范文怎么用「联诵三类规则」和连接词，对照表按「我的说法 / 范文说法 / 适用场景」三列记录。","src":"exams.html#redaction","hint":"抄 10 组对照表达","quiz":[{"ref":"bank:reading:A1:阅读"}]},{"type":"speak","title":"把写的文章讲出来","body":"脱稿把自己写的文章讲 2 分钟，允许简化但不许背稿。讲不顺的句子说明书面结构还没内化，回到文中改写一次，再讲一遍；同时把 <span class=\"fr\" data-fr=\"un ami\">un ami</span>（一个男性朋友）用进口语版本。","src":"exams.html#oral","hint":"脱稿讲 2 分钟，不背稿","quiz":[{"ref":"bank:speaking:A1:口语"}]}]},{"day":7,"theme":"复盘 · 元音、鼻化元音与联诵","type":"review","steps":[{"type":"review","title":"本周回顾：音素系统：元音、鼻化元音与联诵","body":"这一周围绕「音素系统：元音、鼻化元音与联诵」展开：语法主线是 联诵三类规则，词汇主线是 家庭与关系。先用 3 句话口头复述本周学了什么，再打开日历页第 2 周清单逐条核对里程碑。","src":"calendar.html#wk-2","hint":"先口头复述，再核对里程碑","quiz":[{"ref":"bank:vocab:A1:家庭与关系"}]},{"type":"review","title":"语法复盘：联诵三类规则","body":"从 phonetics.html#liaison 的规则与例句里各抽 3 条：默写规则、翻译例句再对照，最后写下 2 个自己最可能犯的错。凡是默写时卡住的地方，就是下一周要带着继续练的问题。","src":"phonetics.html#liaison","hint":"默写规则与例句，各抽 3 条","quiz":[{"ref":"bank:grammar:A1:现在时"}]},{"type":"review","title":"词汇自测：家庭与关系","body":"遮住中文看 vocab.html#t2 的 6 个核心词：<span class=\"fr\" data-fr=\"un ami\">un ami</span> <span class=\"fr\" data-fr=\"une amie\">une amie</span> <span class=\"fr\" data-fr=\"la famille\">la famille</span> <span class=\"fr\" data-fr=\"le père\">le père</span> <span class=\"fr\" data-fr=\"la mère\">la mère</span> <span class=\"fr\" data-fr=\"les enfants\">les enfants</span>。能秒答的划掉，犹豫超过 3 秒的抄进错词本。本周目标是新词认词率不低于 85%。","src":"vocab.html#t2","hint":"遮中文秒答，犹豫即抄错词本","quiz":[{"id":"q-vocab-a1-5005","level":"A1","skill":"vocab","prompt":"「父亲」用法语说是？","options":["le père","le frère","le pair"],"answer":"le père","explain":"le père 是父亲；le frère 是兄弟；le pair 指同级或同辈。","source":"词汇 · 家庭"},{"id":"q-vocab-a1-5006","level":"A1","skill":"vocab","prompt":"« une amie » 表示？","options":["一位女性朋友","一位男性朋友","一位亲戚"],"answer":"一位女性朋友","explain":"amie 是 ami 的阴性形式，指女性朋友；男性朋友写 un ami。","source":"词汇 · 家庭与关系"},{"ref":"bank:vocab:A1:家庭与关系"}]},{"type":"review","title":"综合题（一）：听读理解","body":"先做下面的听读综合题，不查词、不回看材料，限时 5 分钟。做完再回材料定位每道题的证据句，把「没找到证据就选」的题目标出来——那是失分的主要来源。","src":"dialogue.html#d03","hint":"限时 5 分钟，做完回材料找证据","quiz":[{"id":"q-list-a1-5006","level":"A1","skill":"listening","prompt":"« et il » 之间应该？","options":["禁止联诵","必须联诵","可联可不联"],"answer":"禁止联诵","explain":"连词 et 与后一词之间禁止联诵，所以 et il 不读成 /etil/。","source":"语音 · 联诵"},{"id":"q-read-a1-5004","level":"A1","skill":"reading","prompt":"下列哪组词末辅音通常不发音？","options":["s, t, d, x","c, r, f, l","m, n, p"],"answer":"s, t, d, x","explain":"s、t、d、x、z 在词末通常不发音；c、r、f、l 常发音（CaReFuL）。","source":"语音 · 拼读规则"},{"ref":"bank:listening:A1:听力"}]},{"type":"review","title":"综合题（二）：语法与词汇","body":"这一组题检查 联诵三类规则 与本周词汇的调用能力。每道题都问自己：错误选项错在哪里？能说出错因才算真的会，说不出来就回到 phonetics.html#liaison 再核对一次。","src":"phonetics.html#enchainement","hint":"每题都说出错项错在哪","quiz":[{"id":"q-gram-a1-5005","level":"A1","skill":"grammar","prompt":"« C'est l'ami de mon père. » 里出现了几次省音？","options":["1 次","2 次","0 次"],"answer":"1 次","explain":"只有 l'ami 是省音（le → l'）；C'est 是 ce + est 的固定缩合写法。","source":"语音 · 省音"},{"id":"q-gram-a1-5006","level":"A1","skill":"grammar","prompt":"法语的连音（enchaînement）指的是？","options":["词末已发音的辅音与后一词元音连读","相邻两词都变音","词末辅音一律发音"],"answer":"词末已发音的辅音与后一词元音连读","explain":"连音是本来已经发音的辅音顺势接上后一词的元音，如 elle arrive；联诵是本来不发音的辅音被读出来。","source":"语音 · 连音"},{"ref":"bank:grammar:A1:现在时"}]},{"type":"review","title":"输出任务与自评表","body":"完成一段 90 秒口述或 120 词短文，内容必须同时用上本周的 2 个词和 1 个语法结构。按「任务完成 / 连贯 / 词汇 / 语法 / 拼写」五项各打 1–5 分，低于 3 分的写进下周补漏清单。","src":"exams.html#oral","hint":"五项各打 1–5 分","quiz":[{"ref":"bank:writing:A1:写作"}]}]}]},{"week":3,"level":"A1","theme":"名词的性与数、定冠词与不定冠词","days":[{"day":1,"theme":"词汇 · 房屋与居住","type":"vocab","steps":[{"type":"vocab","title":"主题词汇域：房屋与居住","body":"本周词汇主战场是房屋与居住（Le logement et la vie quotidienne）。先到 vocab.html#t5 把词表扫一遍，把 <span class=\"fr\" data-fr=\"un livre\">un livre</span>（书）、<span class=\"fr\" data-fr=\"une table\">une table</span>（桌子）、<span class=\"fr\" data-fr=\"une chaise\">une chaise</span>（椅子）抄在卡片正面。名词连着冠词一起记，动词连最常用的搭配一起记，边写边出声读。","src":"vocab.html#t5","hint":"先读后抄，每个词出声读三遍","quiz":[{"id":"q-vocab-a1-5007","level":"A1","skill":"vocab","prompt":"« une chaise » 的意思是？","options":["椅子","桌子","书架"],"answer":"椅子","explain":"chaise 是椅子（阴性）；table 是桌子；étagère 是书架。","source":"词汇 · 家居物品"},{"ref":"bank:vocab:A1:房屋与居住"}]},{"type":"vocab","title":"搭配与辨析：un stylo / une fenêtre","body":"把 <span class=\"fr\" data-fr=\"un stylo\">un stylo</span>（钢笔）和 <span class=\"fr\" data-fr=\"une fenêtre\">une fenêtre</span>（窗户）放进同一个场景里各造一句，句子要主谓宾齐全。造完再把主语换成 il / elle 说一遍，检查冠词有没有跟着名词变。","src":"vocab.html#t5","hint":"两个词各写 2 个搭配","quiz":[{"id":"q-vocab-a1-5008","level":"A1","skill":"vocab","prompt":"「钢笔」用法语说是？","options":["un stylo","une stylo","un stylot"],"answer":"un stylo","explain":"stylo 是阳性名词，用 un；拼写以 -o 结尾，不加 t。","source":"词汇 · 学习用品"},{"ref":"bank:vocab:A1:房屋与居住"}]},{"type":"listen","title":"听音辨词：房屋与居住","body":"打开 对话页的 d04 篇，先盲听一遍，只做一件事：抓出含本周新词的句子并写下关键词。第二遍再对照法文原文，检查自己漏掉的是词还是联诵。像 <span class=\"fr\" data-fr=\"des clés\">des clés</span>（几把钥匙）这样的词如果没听出来，单独标出来。","src":"dialogue.html#d04","hint":"盲听一遍再对照原文","quiz":[{"ref":"bank:listening:A1:听力"}]},{"type":"speak","title":"口头造句：6 个新词进短句","body":"用今天抄的 6 个词各说一句，主语在 je / nous / on 之间换着用。参考例句 <span class=\"fr\" data-fr=\"C'est un livre et une revue.\">C'est un livre et une revue.</span>（这是一本书和一本杂志。）。录 60 秒，回听时只挑两个问题：冠词有没有丢、动词有没有跟主语配合。","src":"exams.html#oral","hint":"录音 60 秒并回听","quiz":[{"ref":"bank:speaking:A1:口语"}]},{"type":"vocab","title":"日终自测：房屋与居住 认词","body":"遮住中文，只看法语说意思：<span class=\"fr\" data-fr=\"un livre\">un livre</span> <span class=\"fr\" data-fr=\"une table\">une table</span> <span class=\"fr\" data-fr=\"une chaise\">une chaise</span> <span class=\"fr\" data-fr=\"un stylo\">un stylo</span> <span class=\"fr\" data-fr=\"une fenêtre\">une fenêtre</span> <span class=\"fr\" data-fr=\"des clés\">des clés</span>。说不出来的词立刻回到 vocab.html#t5 重记一遍，并在卡片角上打一个星号，星号词明天先复习。","src":"vocab.html#t5","hint":"先遮中文，再遮法语，两个方向各过一遍","quiz":[{"ref":"bank:vocab:A1:房屋与居住"}]}]},{"day":2,"theme":"语法 · 冠词系统","type":"grammar","steps":[{"type":"grammar","title":"语法点：冠词系统","body":"【冠词系统】法语名词必须带限定词：定冠词 le / la / l' / les 表特指或指一类事物，不定冠词 un / une / des 表第一次提到或不确定的数量。阴阳性没有万能规律，但词尾能给出线索：-tion、-té、-ette 多为阴性，-ment、-age、-eau 多为阳性。 例句：<span class=\"fr\" data-fr=\"C'est un livre et une revue.\">C'est un livre et une revue.</span>（这是一本书和一本杂志。）；<span class=\"fr\" data-fr=\"Les enfants sont dans la classe.\">Les enfants sont dans la classe.</span>（孩子们在教室里。）。对照 grammar-a1a2.html#articles 的表格，把规则抄成自己的一句话。","src":"grammar-a1a2.html#articles","hint":"先读规则再看例句","quiz":[{"id":"q-gram-a1-5007","level":"A1","skill":"grammar","prompt":"« ___ livre » 中应填哪个冠词？","options":["un","une","des"],"answer":"un","explain":"livre 是阳性单数，用不定冠词 un；une 只给阴性名词。","source":"语法 · 不定冠词"},{"ref":"bank:grammar:A1:冠词"}]},{"type":"grammar","title":"规则拆解与常见错误","body":"先合上书，凭记忆写出 冠词系统 的规则和两个例句，再打开 grammar-a1a2.html#articles 对照补漏，用红笔标出回忆失败的地方。回忆失败比再读一遍更有价值，那正是考试时会出错的位置。","src":"grammar-a1a2.html#articles","hint":"合上书默写一遍规则","quiz":[{"id":"q-gram-a1-5008","level":"A1","skill":"grammar","prompt":"下列哪个名词是阴性？","options":["la nation","le moment","le voyage"],"answer":"la nation","explain":"以 -tion 结尾的名词绝大多数是阴性；-ment、-age 结尾的多为阳性。","source":"语法 · 名词的性"},{"ref":"bank:grammar:A1:冠词"}]},{"type":"read","title":"在短文里找冠词系统","body":"在 grammar-a1a2.html#articles 的例句和章末小测里挑 5 句，圈出所有属于「冠词系统」的成分。读的时候先判断结构再理解意思，不要一开始就在脑子里翻译成中文。","src":"grammar-a1a2.html#articles","hint":"圈出全部相关成分","quiz":[{"ref":"bank:reading:A1:阅读"}]},{"type":"write","title":"限时仿写：8 句","body":"照 <span class=\"fr\" data-fr=\"C'est un livre et une revue.\">C'est un livre et une revue.</span>（这是一本书和一本杂志。）的句型仿写 8 句，内容必须是你自己的真实信息。写完用三色笔检查：红色圈主语、蓝色圈动词、绿色圈配合成分，冠词系统 的结构至少出现两次。","src":"exams.html#ecrit","hint":"限时 12 分钟，写完自查","quiz":[{"ref":"bank:writing:A1:写作"}]},{"type":"grammar","title":"语法点巩固：名词的阴阳性","body":"今天再回 grammar-a1a2.html#noun-genre 看一遍 名词的阴阳性，把两个语法点的差别写成一行对照（触发条件 / 形式 / 常见错误各一列）。写不出来就说明还停留在「读得懂」而不是「用得出」。","src":"grammar-a1a2.html#noun-genre","hint":"把两个语法点写成对照表","quiz":[{"ref":"bank:grammar:A1:冠词"}]}]},{"day":3,"theme":"精听 · 对话页的 d04 篇","type":"listen","steps":[{"type":"listen","title":"精听（第一遍）：抓主旨","body":"打开 对话页的 d04 篇，盲听第一遍，不暂停、不看文本。只听一个问题：这段话在谈什么？用中文写一句概括，再写下 3 个听清的词。","src":"dialogue.html#d04","hint":"不暂停、不看文本","quiz":[{"id":"q-list-a1-5007","level":"A1","skill":"listening","prompt":"« des » 与 « les » 的读音差别在于？","options":["des 读 /de/，les 读 /le/","两者都读 /le/","des 读 /dɛ/，les 读 /lɛ/"],"answer":"des 读 /de/，les 读 /le/","explain":"des 读 /de/，les 读 /le/，两词辅音不同但元音都是闭口音，靠听辅音区分。","source":"语音 · 冠词读音"},{"ref":"bank:listening:A1:听力"}],"exam":"exam:listening:A2:车站广播"},{"type":"listen","title":"精听（第二遍）：听写关键句","body":"第二遍逐句暂停，听写 5 句含本周语法或新词的句子，写不出的地方标「?」。然后对照原文，把 ? 处按「词汇 / 联诵 / 语速」三类归档。本周的听力任务是：听对话页 A1 篇目，专门分辨 un / une / des 与 les 的读音差别，写下听到的每一处冠词。","src":"dialogue.html#d04","hint":"逐句听写 5 句","quiz":[{"ref":"bank:listening:A1:听力"}]},{"type":"vocab","title":"听力词汇回收","body":"把听写中出现的生词与本周词表对照：<span class=\"fr\" data-fr=\"un livre\">un livre</span>（书）、<span class=\"fr\" data-fr=\"une table\">une table</span>（桌子）、<span class=\"fr\" data-fr=\"une chaise\">une chaise</span>（椅子）。反复出现的词优先记，只出现一次又不影响理解的先放过，避免在细节里迷路。","src":"vocab.html#t5","hint":"生词与本周词表对照","quiz":[{"ref":"bank:vocab:A1:房屋与居住"}]},{"type":"speak","title":"影子跟读 3 遍","body":"同一段材料做影子跟读（shadowing）：滞后原音半句跟读，重点模仿语调、连读与联诵，不要逐字念。跟完录 45 秒复述，不回看原文，卡住就用 <span class=\"fr\" data-fr=\"c'est-à-dire\">c'est-à-dire</span> 争取时间。","src":"exams.html#oral","hint":"滞后半句跟读，录 45 秒复述","quiz":[{"ref":"bank:speaking:A1:口语"}]},{"type":"listen","title":"精听（第三遍）：闭合听力","body":"第三遍只听不看，听完用法语说出 3 个关键信息，再写一句「冠词系统 在这段里出现的位置」。仍听不懂的句子重复听 2 次，还不懂就记下来，第 7 天集中解决。","src":"dialogue.html#d04","hint":"只听不看，说出 3 个关键信息","quiz":[{"ref":"bank:listening:A1:听力"}]}]},{"day":4,"theme":"口语 · 名词的性与数、定冠词与不定冠词","type":"speak","steps":[{"type":"speak","title":"口语任务：本周主题陈述","body":"口语任务：用 20 个新词造句：C'est un… / C'est une… / Ce sont des…，冠词与名词必须一致。 开口前先想好「观点—理由—例子」三段，允许说得慢，但不许说到一半换主题。说完立刻自评一句：哪一段最流畅、哪一段最卡，卡住的地方就是下一次的训练重点。","src":"exams.html#oral","hint":"先说满 60 秒不停","quiz":[{"id":"q-speak-a1-5005","level":"A1","skill":"speaking","prompt":"「这是一些钥匙」说法正确的是？","options":["Ce sont des clés.","C'est des clés.","Ce sont les clés."],"answer":"Ce sont des clés.","explain":"复数用 Ce sont；des 是复数不定冠词；les clés 是特指，与「一些」不符。","source":"语法 · 不定冠词"},{"ref":"bank:speaking:A1:口语"}]},{"type":"speak","title":"结构与衔接：先列提纲再开口","body":"把答案录在手机里，先说满 60 秒不停。说到一半忘词就先换一种说法把意思顶过去，流利度优先于用词精确。录完不要马上回听，隔十分钟再听一遍，判断会更客观。","src":"exams.html#oral","hint":"三个关键词 + 三段衔接词","quiz":[{"ref":"bank:speaking:A1:口语"}]},{"type":"listen","title":"听范例找差距","body":"听一段同主题范例（对话页的 d04 篇），把自己的录音和范例逐项对比：语速、停顿位置、连接词的使用、冠词系统 的正确形式。只记录 3 个今天就能改的点。","src":"dialogue.html#d04","hint":"只记 3 个可立刻改进的点","quiz":[{"ref":"bank:listening:A1:听力"}]},{"type":"vocab","title":"把新词用进嘴里","body":"把 <span class=\"fr\" data-fr=\"un stylo\">un stylo</span>（钢笔）、<span class=\"fr\" data-fr=\"une fenêtre\">une fenêtre</span>（窗户）、<span class=\"fr\" data-fr=\"des clés\">des clés</span>（几把钥匙）轮流塞进刚才的答案里，每个词至少用一次。说不顺就说明这个词还没真正归属你，回到 vocab.html#t5 再看一遍例句。","src":"vocab.html#t5","hint":"每个新词至少用一次","quiz":[{"ref":"bank:vocab:A1:房屋与居住"}]},{"type":"speak","title":"重录一遍并自评","body":"按前面记录的 3 个问题重录一次，目标是同样的内容用更少的停顿说完。回听时数一数填充词（euh、ben、voilà）出现几次，第 7 天把两次录音放在一起比较。","src":"exams.html#oral","hint":"数一数填充词次数","quiz":[{"ref":"bank:speaking:A1:口语"}]}]},{"day":5,"theme":"精读 · 名词的性与数、定冠词与不定冠词","type":"read","steps":[{"type":"read","title":"精读：本周阅读材料","body":"精读任务：读语法页冠词与名词章节，把词尾规律抄成一页速查表。 读第一遍只抓主旨，第二遍才处理细节，遇到生词先猜再查。读完先用一句话写出全文主旨，再回头处理细节，避免一开始就陷进生词里。","src":"exams.html#lecture","hint":"第一遍抓主旨，第二遍抓细节","quiz":[{"id":"q-read-a1-5005","level":"A1","skill":"reading","prompt":"« les » 用在什么情况？","options":["特指或指一类事物","第一次提到","不确定的数量"],"answer":"特指或指一类事物","explain":"定冠词 les 表特指或泛指一类；第一次提到或不确定数量用 des。","source":"语法 · 定冠词"},{"ref":"bank:reading:A1:阅读"}]},{"type":"read","title":"长句解构：先找主干","body":"挑文中 3 个超过 20 词的长句，先划出主谓宾，再把从句、分词、介词短语逐层挂上去。看到「冠词系统」的结构就停下来确认触发条件。","src":"exams.html#lecture","hint":"拆 3 个长句，主干与修饰分栏","quiz":[{"ref":"bank:reading:A1:阅读"}]},{"type":"vocab","title":"阅读词汇：上下文猜词","body":"遇到生词先按词根、词尾和上下文猜一次再核对。本周词表里的 <span class=\"fr\" data-fr=\"un livre\">un livre</span>（书）、<span class=\"fr\" data-fr=\"une table\">une table</span>（桌子）如果以别的形式出现，把那一整句抄进卡片。","src":"vocab.html#t5","hint":"先猜再查，把整句抄下来","quiz":[{"ref":"bank:vocab:A1:房屋与居住"}]},{"type":"grammar","title":"语法在句子里的样子","body":"回到 grammar-a1a2.html#articles，对照文中出现的同类结构，确认书面语和口语的差别。摘抄 3 句可以直接套进写作的句子，标注它们的连接词和语式。","src":"grammar-a1a2.html#articles","hint":"摘 3 句能直接用的句子","quiz":[{"ref":"bank:grammar:A1:冠词"}]},{"type":"write","title":"100 词摘要","body":"不照抄原句，用 100 词概括文章并加一句自己的评价。写完统计三个数字：平均句长、连接词数量、「冠词系统」出现次数，看看自己的书面语是不是只会并列短句。","src":"exams.html#ecrit","hint":"改写不照抄，统计三个数字","quiz":[{"ref":"bank:writing:A1:写作"}]}]},{"day":6,"theme":"写作 · 名词的性与数、定冠词与不定冠词","type":"write","steps":[{"type":"write","title":"写作任务：本周产出","body":"写作任务：写 10 句「这是我的……」与「这是几个……」，圈出每个冠词与名词。 先列提纲再动笔，写完整篇留 5 分钟只做一遍通读检查。动笔前先确认题目要求写几段、用什么语域，避免写到一半推翻结构。","src":"exams.html#ecrit","hint":"先列提纲，再限时成文","quiz":[{"id":"q-writ-a1-5003","level":"A1","skill":"writing","prompt":"「几把钥匙」的正确写法是？","options":["des clés","des clé","de clés"],"answer":"des clés","explain":"clé 是阴性名词，复数加 -s；只有否定句中 des 才变成 de。","source":"语法 · 名词复数"},{"ref":"bank:writing:A1:写作"}]},{"type":"write","title":"提纲与逻辑链","body":"先写中文要点，再逐条译成法语，但译完必须回头改：把中文语序的句子打散重写，让动词和它的补语各就各位。改完把最生硬的 3 句抄到一边，作为下一稿的重点对象。","src":"exams.html#ecrit","hint":"三段式提纲，每段一个论点","quiz":[{"ref":"bank:writing:A1:写作"}]},{"type":"grammar","title":"写前语法自查清单","body":"打开 grammar-a1a2.html#articles，把本周语法点做成 3 条自查项写在旁边，例如「触发词有没有用对」「变位与配合是否一致」。写完通读只检查这 3 条，其余问题留到第二稿再处理。","src":"grammar-a1a2.html#articles","hint":"三条自查项，只查这三条","quiz":[{"ref":"bank:grammar:A1:冠词"}]},{"type":"read","title":"对照范文找可替换表达","body":"读考试页的范文，列出 10 处「我只会用简单说法、范文用了更地道说法」的对照，抄进表达本。重点看范文怎么用「冠词系统」和连接词，对照表按「我的说法 / 范文说法 / 适用场景」三列记录。","src":"exams.html#redaction","hint":"抄 10 组对照表达","quiz":[{"ref":"bank:reading:A1:阅读"}]},{"type":"speak","title":"把写的文章讲出来","body":"脱稿把自己写的文章讲 2 分钟，允许简化但不许背稿。讲不顺的句子说明书面结构还没内化，回到文中改写一次，再讲一遍；同时把 <span class=\"fr\" data-fr=\"un livre\">un livre</span>（书）用进口语版本。","src":"exams.html#oral","hint":"脱稿讲 2 分钟，不背稿","quiz":[{"ref":"bank:speaking:A1:口语"}]}]},{"day":7,"theme":"复盘 · 名词的性与数、定冠词与不定冠词","type":"review","steps":[{"type":"review","title":"本周回顾：名词的性与数、定冠词与不定冠词","body":"这一周围绕「名词的性与数、定冠词与不定冠词」展开：语法主线是 冠词系统，词汇主线是 房屋与居住。先用 3 句话口头复述本周学了什么，再打开日历页第 3 周清单逐条核对里程碑。","src":"calendar.html#wk-3","hint":"先口头复述，再核对里程碑","quiz":[{"ref":"bank:vocab:A1:房屋与居住"}]},{"type":"review","title":"语法复盘：冠词系统","body":"从 grammar-a1a2.html#articles 的规则与例句里各抽 3 条：默写规则、翻译例句再对照，最后写下 2 个自己最可能犯的错。凡是默写时卡住的地方，就是下一周要带着继续练的问题。","src":"grammar-a1a2.html#articles","hint":"默写规则与例句，各抽 3 条","quiz":[{"ref":"bank:grammar:A1:冠词"}]},{"type":"review","title":"词汇自测：房屋与居住","body":"遮住中文看 vocab.html#t5 的 6 个核心词：<span class=\"fr\" data-fr=\"un livre\">un livre</span> <span class=\"fr\" data-fr=\"une table\">une table</span> <span class=\"fr\" data-fr=\"une chaise\">une chaise</span> <span class=\"fr\" data-fr=\"un stylo\">un stylo</span> <span class=\"fr\" data-fr=\"une fenêtre\">une fenêtre</span> <span class=\"fr\" data-fr=\"des clés\">des clés</span>。能秒答的划掉，犹豫超过 3 秒的抄进错词本。本周目标是新词认词率不低于 85%。","src":"vocab.html#t5","hint":"遮中文秒答，犹豫即抄错词本","quiz":[{"id":"q-vocab-a1-5009","level":"A1","skill":"vocab","prompt":"« une fenêtre » 的意思是？","options":["窗户","门","墙"],"answer":"窗户","explain":"fenêtre 是窗户（阴性）；porte 是门；mur 是墙。","source":"词汇 · 家居物品"},{"id":"q-vocab-a1-5010","level":"A1","skill":"vocab","prompt":"「桌子」用法语说是？","options":["une table","un table","un tableau"],"answer":"une table","explain":"table 是阴性名词，用 une；tableau 是黑板或画，阳性，写作 un tableau。","source":"词汇 · 家居物品"},{"ref":"bank:vocab:A1:房屋与居住"}]},{"type":"review","title":"综合题（一）：听读理解","body":"先做下面的听读综合题，不查词、不回看材料，限时 5 分钟。做完再回材料定位每道题的证据句，把「没找到证据就选」的题目标出来——那是失分的主要来源。","src":"dialogue.html#d04","hint":"限时 5 分钟，做完回材料找证据","quiz":[{"id":"q-list-a1-5008","level":"A1","skill":"listening","prompt":"听到 /yn tabl/ 时最可能是？","options":["une table","un tableau","les tables"],"answer":"une table","explain":"/yn/ 表明冠词是阴性单数的 une，名词以 /l/ 收尾，对应 une table。","source":"语音 · 冠词读音"},{"id":"q-read-a1-5006","level":"A1","skill":"reading","prompt":"「教室」用法语说是？","options":["la salle de classe","le salle de classe","la classe de salle"],"answer":"la salle de classe","explain":"salle 与 classe 都是阴性，用 la；语序是「房间 + de + 用途」。","source":"词汇 · 学校"},{"ref":"bank:listening:A1:听力"}]},{"type":"review","title":"综合题（二）：语法与词汇","body":"这一组题检查 冠词系统 与本周词汇的调用能力。每道题都问自己：错误选项错在哪里？能说出错因才算真的会，说不出来就回到 grammar-a1a2.html#articles 再核对一次。","src":"grammar-a1a2.html#noun-genre","hint":"每题都说出错项错在哪","quiz":[{"id":"q-gram-a1-5009","level":"A1","skill":"grammar","prompt":"« ___ école » 中应填哪个冠词？","options":["l'","le","la"],"answer":"l'","explain":"école 以元音开头，单数定冠词 le / la 都要省音写成 l'。","source":"语法 · 省音与冠词"},{"id":"q-gram-a1-5010","level":"A1","skill":"grammar","prompt":"下列哪个名词是阳性？","options":["le voyage","la nation","la beauté"],"answer":"le voyage","explain":"-age 结尾的名词多数是阳性；-tion、-té 结尾的多数是阴性。","source":"语法 · 名词的性"},{"ref":"bank:grammar:A1:冠词"}]},{"type":"review","title":"输出任务与自评表","body":"完成一段 90 秒口述或 120 词短文，内容必须同时用上本周的 2 个词和 1 个语法结构。按「任务完成 / 连贯 / 词汇 / 语法 / 拼写」五项各打 1–5 分，低于 3 分的写进下周补漏清单。","src":"exams.html#oral","hint":"五项各打 1–5 分","quiz":[{"ref":"bank:writing:A1:写作"}]}]}]},{"week":4,"level":"A1","theme":"主语人称代词与 être / avoir","days":[{"day":1,"theme":"词汇 · 人与身份","type":"vocab","steps":[{"type":"vocab","title":"主题词汇域：人与身份","body":"人与身份（L'être humain et l'identité）是这一周要反复见面的主题域。打开 vocab.html#t1，先看词表怎么分组，再把 <span class=\"fr\" data-fr=\"être\">être</span>（是（系动词））、<span class=\"fr\" data-fr=\"avoir\">avoir</span>（有）、<span class=\"fr\" data-fr=\"un étudiant\">un étudiant</span>（男学生）读三遍，然后遮住中文说意思。记不住的词单独建一张「顽固词表」。","src":"vocab.html#t1","hint":"先读后抄，每个词出声读三遍","quiz":[{"id":"q-vocab-a1-5011","level":"A1","skill":"vocab","prompt":"« un métier » 的意思是？","options":["职业","地址","国籍"],"answer":"职业","explain":"métier 指职业、行当；adresse 是地址；nationalité 是国籍。","source":"词汇 · 职业"},{"ref":"bank:vocab:A1:人与身份"}]},{"type":"vocab","title":"搭配与辨析：une étudiante / un métier","body":"<span class=\"fr\" data-fr=\"une étudiante\">une étudiante</span>（女学生）与 <span class=\"fr\" data-fr=\"un métier\">un métier</span>（职业）是本组最容易混的两个词。为每个词写 2 个搭配（一个名词搭配、一个动词搭配），读出来判断哪个更自然，拿不准的留到第 7 天复盘。","src":"vocab.html#t1","hint":"两个词各写 2 个搭配","quiz":[{"id":"q-vocab-a1-5012","level":"A1","skill":"vocab","prompt":"「女学生」用法语说是？","options":["une étudiante","un étudiant","une étudient"],"answer":"une étudiante","explain":"étudiant 的阴性形式是 étudiante，加 -e 后鼻化元音也要拆开读。","source":"词汇 · 人与身份"},{"ref":"bank:vocab:A1:人与身份"}]},{"type":"listen","title":"听音辨词：人与身份","body":"打开 对话页的 d01、d10 篇，先盲听一遍，只做一件事：抓出含本周新词的句子并写下关键词。第二遍再对照法文原文，检查自己漏掉的是词还是联诵。像 <span class=\"fr\" data-fr=\"un ami français\">un ami français</span>（一位法国朋友）这样的词如果没听出来，单独标出来。","src":"dialogue.html#d01","hint":"盲听一遍再对照原文","quiz":[{"ref":"bank:listening:A1:听力"}]},{"type":"speak","title":"口头造句：6 个新词进短句","body":"用今天抄的 6 个词各说一句，主语在 je / nous / on 之间换着用。参考例句 <span class=\"fr\" data-fr=\"Je suis chinois et j'ai vingt ans.\">Je suis chinois et j'ai vingt ans.</span>（我是中国人，二十岁。）。录 60 秒，回听时只挑两个问题：冠词有没有丢、动词有没有跟主语配合。","src":"exams.html#oral","hint":"录音 60 秒并回听","quiz":[{"ref":"bank:speaking:A1:口语"}]},{"type":"vocab","title":"日终自测：人与身份 认词","body":"遮住中文，只看法语说意思：<span class=\"fr\" data-fr=\"être\">être</span> <span class=\"fr\" data-fr=\"avoir\">avoir</span> <span class=\"fr\" data-fr=\"un étudiant\">un étudiant</span> <span class=\"fr\" data-fr=\"une étudiante\">une étudiante</span> <span class=\"fr\" data-fr=\"un métier\">un métier</span> <span class=\"fr\" data-fr=\"un ami français\">un ami français</span>。说不出来的词立刻回到 vocab.html#t1 重记一遍，并在卡片角上打一个星号，星号词明天先复习。","src":"vocab.html#t1","hint":"先遮中文，再遮法语，两个方向各过一遍","quiz":[{"ref":"bank:vocab:A1:人与身份"}]}]},{"day":2,"theme":"语法 · 主语人称代词","type":"grammar","steps":[{"type":"grammar","title":"语法点：主语人称代词","body":"【主语人称代词】主语人称代词 je / tu / il / elle / nous / vous / ils / elles 不能省略；être 的现在时是 suis, es, est, sommes, êtes, sont，avoir 是 ai, as, a, avons, avez, ont。表达年龄必须用 avoir：J'ai vingt ans。 例句：<span class=\"fr\" data-fr=\"Je suis chinois et j'ai vingt ans.\">Je suis chinois et j'ai vingt ans.</span>（我是中国人，二十岁。）；<span class=\"fr\" data-fr=\"Ils sont étudiants à Paris.\">Ils sont étudiants à Paris.</span>（他们在巴黎上学。）。对照 grammar-a1a2.html#pro-subj 的表格，把规则抄成自己的一句话。","src":"grammar-a1a2.html#pro-subj","hint":"先读规则再看例句","quiz":[{"id":"q-gram-a1-5011","level":"A1","skill":"grammar","prompt":"Je ___ français.（être）","options":["suis","es","est"],"answer":"suis","explain":"je 对应 suis；es 只给 tu，est 只给 il / elle / on。","source":"语法 · être 现在时"},{"ref":"bank:grammar:A1:être"}]},{"type":"grammar","title":"规则拆解与常见错误","body":"对着 grammar-a1a2.html#pro-subj 自查三件事：① 触发条件是什么；② 变位或配合落在哪个词尾；③ 有哪些例外要单独记。然后把 <span class=\"fr\" data-fr=\"Je suis chinois et j'ai vingt ans.\">Je suis chinois et j'ai vingt ans.</span>（我是中国人，二十岁。）拆到词，逐一说明每个成分为什么用这个形式。","src":"grammar-a1a2.html#pro-subj","hint":"合上书默写一遍规则","quiz":[{"id":"q-gram-a1-5012","level":"A1","skill":"grammar","prompt":"Nous ___ vingt ans.（avoir）","options":["avons","avez","ont"],"answer":"avons","explain":"nous 对应 avons；avez 给 vous，ont 给 ils / elles。","source":"语法 · avoir 现在时"},{"ref":"bank:grammar:A1:être"}]},{"type":"read","title":"在短文里找主语人称代词","body":"在 grammar-a1a2.html#pro-subj 的例句和章末小测里挑 5 句，圈出所有属于「主语人称代词」的成分。读的时候先判断结构再理解意思，不要一开始就在脑子里翻译成中文。","src":"grammar-a1a2.html#pro-subj","hint":"圈出全部相关成分","quiz":[{"ref":"bank:reading:A1:阅读"}]},{"type":"write","title":"限时仿写：8 句","body":"照 <span class=\"fr\" data-fr=\"Je suis chinois et j'ai vingt ans.\">Je suis chinois et j'ai vingt ans.</span>（我是中国人，二十岁。）的句型仿写 8 句，内容必须是你自己的真实信息。写完用三色笔检查：红色圈主语、蓝色圈动词、绿色圈配合成分，主语人称代词 的结构至少出现两次。","src":"exams.html#ecrit","hint":"限时 12 分钟，写完自查","quiz":[{"ref":"bank:writing:A1:写作"}]},{"type":"grammar","title":"语法点巩固：常用不规则动词变位表","body":"今天再回 grammar-a1a2.html#pres-irreg 看一遍 常用不规则动词变位表，把两个语法点的差别写成一行对照（触发条件 / 形式 / 常见错误各一列）。写不出来就说明还停留在「读得懂」而不是「用得出」。","src":"grammar-a1a2.html#pres-irreg","hint":"把两个语法点写成对照表","quiz":[{"ref":"bank:grammar:A1:être"}]}]},{"day":3,"theme":"精听 · 对话页的 d01、d10 篇","type":"listen","steps":[{"type":"listen","title":"精听（第一遍）：抓主旨","body":"第一遍听的时候不要追求每个词都懂。对话页的 d01、d10 篇 的材料先听三分钟，抓住说话人、场景和态度，其余细节留到第二遍。听之前先用 10 秒预测这段话会出现哪些本周词汇，带着预测去听，抓取效率会明显提高。","src":"dialogue.html#d01","hint":"不暂停、不看文本","quiz":[{"id":"q-list-a1-5009","level":"A1","skill":"listening","prompt":"听到 /ilsɔ̃tetydjɑ̃/ 时最可能是？","options":["Ils sont étudiants.","Il est étudiant.","Elles sont étudiantes."],"answer":"Ils sont étudiants.","explain":"ils 与辅音开头的 sont 之间不联诵，读 /il sɔ̃/；sont 与元音开头的 étudiants 之间联诵，t 读出来，所以是 /ilsɔ̃tetydjɑ̃/。","source":"语音 · 联诵与主语"},{"ref":"bank:listening:A1:听力"}],"exam":"exam:listening:A2:车站广播"},{"type":"listen","title":"精听（第二遍）：听写关键句","body":"第二遍逐句暂停，听写 5 句含本周语法或新词的句子，写不出的地方标「?」。然后对照原文，把 ? 处按「词汇 / 联诵 / 语速」三类归档。本周的听力任务是：听自我介绍类音频，听写 10 句 Je suis… / J'ai…，注意联诵与年龄表达。","src":"dialogue.html#d01","hint":"逐句听写 5 句","quiz":[{"ref":"bank:listening:A1:听力"}]},{"type":"vocab","title":"听力词汇回收","body":"把听写中出现的生词与本周词表对照：<span class=\"fr\" data-fr=\"être\">être</span>（是（系动词））、<span class=\"fr\" data-fr=\"avoir\">avoir</span>（有）、<span class=\"fr\" data-fr=\"un étudiant\">un étudiant</span>（男学生）。反复出现的词优先记，只出现一次又不影响理解的先放过，避免在细节里迷路。","src":"vocab.html#t1","hint":"生词与本周词表对照","quiz":[{"ref":"bank:vocab:A1:人与身份"}]},{"type":"speak","title":"影子跟读 3 遍","body":"同一段材料做影子跟读（shadowing）：滞后原音半句跟读，重点模仿语调、连读与联诵，不要逐字念。跟完录 45 秒复述，不回看原文，卡住就用 <span class=\"fr\" data-fr=\"c'est-à-dire\">c'est-à-dire</span> 争取时间。","src":"exams.html#oral","hint":"滞后半句跟读，录 45 秒复述","quiz":[{"ref":"bank:speaking:A1:口语"}]},{"type":"listen","title":"精听（第三遍）：闭合听力","body":"第三遍只听不看，听完用法语说出 3 个关键信息，再写一句「主语人称代词 在这段里出现的位置」。仍听不懂的句子重复听 2 次，还不懂就记下来，第 7 天集中解决。","src":"dialogue.html#d01","hint":"只听不看，说出 3 个关键信息","quiz":[{"ref":"bank:listening:A1:听力"}]}]},{"day":4,"theme":"口语 · 主语人称代词与 être / avoir","type":"speak","steps":[{"type":"speak","title":"口语任务：本周主题陈述","body":"口语任务：做 60 秒自我介绍（姓名、国籍、职业、年龄、住址），录音后回听，检查年龄有没有误用 être。 开口前先想好「观点—理由—例子」三段，允许说得慢，但不许说到一半换主题。说完立刻自评一句：哪一段最流畅、哪一段最卡，卡住的地方就是下一次的训练重点。","src":"exams.html#oral","hint":"先说满 60 秒不停","quiz":[{"id":"q-speak-a1-5006","level":"A1","skill":"speaking","prompt":"自我介绍年龄时，正确说法是？","options":["J'ai vingt ans.","Je suis vingt ans.","Je ai vingt ans."],"answer":"J'ai vingt ans.","explain":"法语年龄用 avoir：J'ai vingt ans；je ai 必须省音写成 j'ai。","source":"语法 · 年龄表达"},{"ref":"bank:speaking:A1:口语"}]},{"type":"speak","title":"结构与衔接：先列提纲再开口","body":"用 30 秒写 3 个关键词当提纲，再用 <span class=\"fr\" data-fr=\"d'abord\">d'abord</span> / <span class=\"fr\" data-fr=\"ensuite\">ensuite</span> / <span class=\"fr\" data-fr=\"enfin\">enfin</span> 把三段串起来。卡壳时用 <span class=\"fr\" data-fr=\"c'est-à-dire\">c'est-à-dire</span> 或 <span class=\"fr\" data-fr=\"disons que…\">disons que…</span> 争取时间，不要用中文思考再翻译。","src":"exams.html#oral","hint":"三个关键词 + 三段衔接词","quiz":[{"ref":"bank:speaking:A1:口语"}]},{"type":"listen","title":"听范例找差距","body":"听一段同主题范例（对话页的 d01、d10 篇），把自己的录音和范例逐项对比：语速、停顿位置、连接词的使用、主语人称代词 的正确形式。只记录 3 个今天就能改的点。","src":"dialogue.html#d01","hint":"只记 3 个可立刻改进的点","quiz":[{"ref":"bank:listening:A1:听力"}]},{"type":"vocab","title":"把新词用进嘴里","body":"把 <span class=\"fr\" data-fr=\"une étudiante\">une étudiante</span>（女学生）、<span class=\"fr\" data-fr=\"un métier\">un métier</span>（职业）、<span class=\"fr\" data-fr=\"un ami français\">un ami français</span>（一位法国朋友）轮流塞进刚才的答案里，每个词至少用一次。说不顺就说明这个词还没真正归属你，回到 vocab.html#t1 再看一遍例句。","src":"vocab.html#t1","hint":"每个新词至少用一次","quiz":[{"ref":"bank:vocab:A1:人与身份"}]},{"type":"speak","title":"重录一遍并自评","body":"按前面记录的 3 个问题重录一次，目标是同样的内容用更少的停顿说完。回听时数一数填充词（euh、ben、voilà）出现几次，第 7 天把两次录音放在一起比较。","src":"exams.html#oral","hint":"数一数填充词次数","quiz":[{"ref":"bank:speaking:A1:口语"}]}]},{"day":5,"theme":"精读 · 主语人称代词与 être / avoir","type":"read","steps":[{"type":"read","title":"精读：本周阅读材料","body":"精读任务：读语法页 être / avoir 变位表，抄写 3 遍到能默写。 读第一遍只抓主旨，第二遍才处理细节，遇到生词先猜再查。读完先用一句话写出全文主旨，再回头处理细节，避免一开始就陷进生词里。","src":"exams.html#lecture","hint":"第一遍抓主旨，第二遍抓细节","quiz":[{"id":"q-read-a1-5007","level":"A1","skill":"reading","prompt":"« Vous êtes… » 中 vous 对应的 être 形式是？","options":["êtes","sommes","sont"],"answer":"êtes","explain":"vous 对应 êtes；sommes 给 nous，sont 给 ils / elles。","source":"语法 · être 现在时"},{"ref":"bank:reading:A1:阅读"}]},{"type":"read","title":"长句解构：先找主干","body":"把长句按「主干 + 修饰」两栏抄写：左栏只留主谓宾，右栏按顺序列出从句与补语。拆完再合起来读一遍，语序感会明显变好。判断不出从句类型时，先整段框起来，读完上下文再回来标注。","src":"exams.html#lecture","hint":"拆 3 个长句，主干与修饰分栏","quiz":[{"ref":"bank:reading:A1:阅读"}]},{"type":"vocab","title":"阅读词汇：上下文猜词","body":"遇到生词先按词根、词尾和上下文猜一次再核对。本周词表里的 <span class=\"fr\" data-fr=\"être\">être</span>（是（系动词））、<span class=\"fr\" data-fr=\"avoir\">avoir</span>（有）如果以别的形式出现，把那一整句抄进卡片。","src":"vocab.html#t1","hint":"先猜再查，把整句抄下来","quiz":[{"ref":"bank:vocab:A1:人与身份"}]},{"type":"grammar","title":"语法在句子里的样子","body":"回到 grammar-a1a2.html#pro-subj，对照文中出现的同类结构，确认书面语和口语的差别。摘抄 3 句可以直接套进写作的句子，标注它们的连接词和语式。","src":"grammar-a1a2.html#pro-subj","hint":"摘 3 句能直接用的句子","quiz":[{"ref":"bank:grammar:A1:être"}]},{"type":"write","title":"100 词摘要","body":"不照抄原句，用 100 词概括文章并加一句自己的评价。写完统计三个数字：平均句长、连接词数量、「主语人称代词」出现次数，看看自己的书面语是不是只会并列短句。","src":"exams.html#ecrit","hint":"改写不照抄，统计三个数字","quiz":[{"ref":"bank:writing:A1:写作"}]}]},{"day":6,"theme":"写作 · 主语人称代词与 être / avoir","type":"write","steps":[{"type":"write","title":"写作任务：本周产出","body":"写作任务：用 être 与 avoir 各写 8 句真实信息，句句都要有主语代词。 先列提纲再动笔，写完整篇留 5 分钟只做一遍通读检查。动笔前先确认题目要求写几段、用什么语域，避免写到一半推翻结构。","src":"exams.html#ecrit","hint":"先列提纲，再限时成文","quiz":[{"id":"q-writ-a1-5004","level":"A1","skill":"writing","prompt":"「她是老师」的正确写法是？","options":["Elle est professeur.","Elle es professeur.","Elle a professeur."],"answer":"Elle est professeur.","explain":"elle 对应 est；es 只给 tu；professeur 表身份，用 être 不用 avoir。","source":"语法 · être 现在时"},{"ref":"bank:writing:A1:写作"}]},{"type":"write","title":"提纲与逻辑链","body":"动笔前把提纲写成三段式：每段一个论点，每个论点配一个具体例子。检查连接词是否多样，别整段只用 et 和 mais。提纲写完后放一分钟再看一遍，如果一句话就能说清每段的作用，结构就算过关。","src":"exams.html#ecrit","hint":"三段式提纲，每段一个论点","quiz":[{"ref":"bank:writing:A1:写作"}]},{"type":"grammar","title":"写前语法自查清单","body":"打开 grammar-a1a2.html#pro-subj，把本周语法点做成 3 条自查项写在旁边，例如「触发词有没有用对」「变位与配合是否一致」。写完通读只检查这 3 条，其余问题留到第二稿再处理。","src":"grammar-a1a2.html#pro-subj","hint":"三条自查项，只查这三条","quiz":[{"ref":"bank:grammar:A1:être"}]},{"type":"read","title":"对照范文找可替换表达","body":"读考试页的范文，列出 10 处「我只会用简单说法、范文用了更地道说法」的对照，抄进表达本。重点看范文怎么用「主语人称代词」和连接词，对照表按「我的说法 / 范文说法 / 适用场景」三列记录。","src":"exams.html#redaction","hint":"抄 10 组对照表达","quiz":[{"ref":"bank:reading:A1:阅读"}]},{"type":"speak","title":"把写的文章讲出来","body":"脱稿把自己写的文章讲 2 分钟，允许简化但不许背稿。讲不顺的句子说明书面结构还没内化，回到文中改写一次，再讲一遍；同时把 <span class=\"fr\" data-fr=\"être\">être</span>（是（系动词））用进口语版本。","src":"exams.html#oral","hint":"脱稿讲 2 分钟，不背稿","quiz":[{"ref":"bank:speaking:A1:口语"}]}]},{"day":7,"theme":"复盘 · 主语人称代词与 être / avoir","type":"review","steps":[{"type":"review","title":"本周回顾：主语人称代词与 être / avoir","body":"这一周围绕「主语人称代词与 être / avoir」展开：语法主线是 主语人称代词，词汇主线是 人与身份。先用 3 句话口头复述本周学了什么，再打开日历页第 4 周清单逐条核对里程碑。","src":"calendar.html#wk-4","hint":"先口头复述，再核对里程碑","quiz":[{"ref":"bank:vocab:A1:人与身份"}]},{"type":"review","title":"语法复盘：主语人称代词","body":"从 grammar-a1a2.html#pro-subj 的规则与例句里各抽 3 条：默写规则、翻译例句再对照，最后写下 2 个自己最可能犯的错。凡是默写时卡住的地方，就是下一周要带着继续练的问题。","src":"grammar-a1a2.html#pro-subj","hint":"默写规则与例句，各抽 3 条","quiz":[{"ref":"bank:grammar:A1:être"}]},{"type":"review","title":"词汇自测：人与身份","body":"遮住中文看 vocab.html#t1 的 6 个核心词：<span class=\"fr\" data-fr=\"être\">être</span> <span class=\"fr\" data-fr=\"avoir\">avoir</span> <span class=\"fr\" data-fr=\"un étudiant\">un étudiant</span> <span class=\"fr\" data-fr=\"une étudiante\">une étudiante</span> <span class=\"fr\" data-fr=\"un métier\">un métier</span> <span class=\"fr\" data-fr=\"un ami français\">un ami français</span>。能秒答的划掉，犹豫超过 3 秒的抄进错词本。本周目标是新词认词率不低于 85%。","src":"vocab.html#t1","hint":"遮中文秒答，犹豫即抄错词本","quiz":[{"id":"q-vocab-a1-5013","level":"A1","skill":"vocab","prompt":"« une adresse » 的意思是？","options":["地址","年龄","国籍"],"answer":"地址","explain":"adresse 是地址（阴性）；âge 是年龄；nationalité 是国籍。","source":"词汇 · 人与身份"},{"id":"q-vocab-a1-5014","level":"A1","skill":"vocab","prompt":"「医生」用法语说是？","options":["un médecin","un métier","un medicin"],"answer":"un médecin","explain":"médecin 是医生，注意拼写带 é；métier 是职业的总称。","source":"词汇 · 职业"},{"ref":"bank:vocab:A1:人与身份"}]},{"type":"review","title":"综合题（一）：听读理解","body":"先做下面的听读综合题，不查词、不回看材料，限时 5 分钟。做完再回材料定位每道题的证据句，把「没找到证据就选」的题目标出来——那是失分的主要来源。","src":"dialogue.html#d01","hint":"限时 5 分钟，做完回材料找证据","quiz":[{"id":"q-list-a1-5010","level":"A1","skill":"listening","prompt":"« J'ai… » 在快速口语里听起来像？","options":["/ʒe/","/ʒə e/","/ʒɛ/"],"answer":"/ʒe/","explain":"je ai 省音为 j'ai，读 /ʒe/，与 je 的 /ʒə/ 明显不同。","source":"语音 · 省音"},{"id":"q-read-a1-5008","level":"A1","skill":"reading","prompt":"« Elles ont… » 中主语对应的 avoir 形式是？","options":["ont","sont","avez"],"answer":"ont","explain":"elles 对应 ont；sont 是 être 的形式，不能混用。","source":"语法 · avoir 现在时"},{"ref":"bank:listening:A1:听力"}]},{"type":"review","title":"综合题（二）：语法与词汇","body":"这一组题检查 主语人称代词 与本周词汇的调用能力。每道题都问自己：错误选项错在哪里？能说出错因才算真的会，说不出来就回到 grammar-a1a2.html#pro-subj 再核对一次。","src":"grammar-a1a2.html#pres-irreg","hint":"每题都说出错项错在哪","quiz":[{"id":"q-gram-a1-5013","level":"A1","skill":"grammar","prompt":"« Tu ___ étudiant ? »（être）","options":["es","est","suis"],"answer":"es","explain":"tu 对应 es；疑问句用语调式时主语和动词顺序不变。","source":"语法 · être 现在时"},{"id":"q-gram-a1-5014","level":"A1","skill":"grammar","prompt":"下列哪句是错的？","options":["Je suis vingt ans.","J'ai vingt ans.","Il a vingt ans."],"answer":"Je suis vingt ans.","explain":"年龄一律用 avoir；être 加数字年岁是典型的中式错误。","source":"语法 · 年龄表达"},{"ref":"bank:grammar:A1:être"}]},{"type":"review","title":"输出任务与自评表","body":"完成一段 90 秒口述或 120 词短文，内容必须同时用上本周的 2 个词和 1 个语法结构。按「任务完成 / 连贯 / 词汇 / 语法 / 拼写」五项各打 1–5 分，低于 3 分的写进下周补漏清单。","src":"exams.html#oral","hint":"五项各打 1–5 分","quiz":[{"ref":"bank:writing:A1:写作"}]}]}]},{"week":5,"level":"A1","theme":"第一组动词 -er 现在时与否定","days":[{"day":1,"theme":"词汇 · 高频动词与万能表达","type":"vocab","steps":[{"type":"vocab","title":"主题词汇域：高频动词与万能表达","body":"本周词汇主战场是高频动词与万能表达（Les verbes fréquents et les expressions utiles）。先到 vocab.html#t25 把词表扫一遍，把 <span class=\"fr\" data-fr=\"parler\">parler</span>（说，讲）、<span class=\"fr\" data-fr=\"habiter\">habiter</span>（居住）、<span class=\"fr\" data-fr=\"travailler\">travailler</span>（工作）抄在卡片正面。名词连着冠词一起记，动词连最常用的搭配一起记，边写边出声读。","src":"vocab.html#t25","hint":"先读后抄，每个词出声读三遍","quiz":[{"id":"q-vocab-a1-5015","level":"A1","skill":"vocab","prompt":"« travailler » 的意思是？","options":["工作","旅行","说话"],"answer":"工作","explain":"travailler 是工作；voyager 是旅行；parler 是说话。","source":"词汇 · 高频动词"},{"ref":"bank:vocab:A2:高频动词与万能表达"}]},{"type":"vocab","title":"搭配与辨析：aimer / étudier","body":"把 <span class=\"fr\" data-fr=\"aimer\">aimer</span>（喜欢）和 <span class=\"fr\" data-fr=\"étudier\">étudier</span>（学习）放进同一个场景里各造一句，句子要主谓宾齐全。造完再把主语换成 il / elle 说一遍，检查冠词有没有跟着名词变。","src":"vocab.html#t25","hint":"两个词各写 2 个搭配","quiz":[{"id":"q-vocab-a1-5016","level":"A1","skill":"vocab","prompt":"« manger » 的 nous 形式是？","options":["nous mangeons","nous mangons","nous mangions"],"answer":"nous mangeons","explain":"manger 为了保持 /ʒ/ 的音，nous 形式保留 e 写作 nous mangeons。","source":"语法 · -er 动词"},{"ref":"bank:vocab:A2:高频动词与万能表达"}]},{"type":"listen","title":"听音辨词：高频动词与万能表达","body":"打开 对话页的 d05 篇，先盲听一遍，只做一件事：抓出含本周新词的句子并写下关键词。第二遍再对照法文原文，检查自己漏掉的是词还是联诵。像 <span class=\"fr\" data-fr=\"manger\">manger</span>（吃）这样的词如果没听出来，单独标出来。","src":"dialogue.html#d05","hint":"盲听一遍再对照原文","quiz":[{"ref":"bank:listening:A1:听力"}]},{"type":"speak","title":"口头造句：6 个新词进短句","body":"用今天抄的 6 个词各说一句，主语在 je / nous / on 之间换着用。参考例句 <span class=\"fr\" data-fr=\"Je parle français et j'habite à Lyon.\">Je parle français et j'habite à Lyon.</span>（我说法语，我住在里昂。）。录 60 秒，回听时只挑两个问题：冠词有没有丢、动词有没有跟主语配合。","src":"exams.html#oral","hint":"录音 60 秒并回听","quiz":[{"ref":"bank:speaking:A1:口语"}]},{"type":"vocab","title":"日终自测：高频动词与万能表达 认词","body":"遮住中文，只看法语说意思：<span class=\"fr\" data-fr=\"parler\">parler</span> <span class=\"fr\" data-fr=\"habiter\">habiter</span> <span class=\"fr\" data-fr=\"travailler\">travailler</span> <span class=\"fr\" data-fr=\"aimer\">aimer</span> <span class=\"fr\" data-fr=\"étudier\">étudier</span> <span class=\"fr\" data-fr=\"manger\">manger</span>。说不出来的词立刻回到 vocab.html#t25 重记一遍，并在卡片角上打一个星号，星号词明天先复习。","src":"vocab.html#t25","hint":"先遮中文，再遮法语，两个方向各过一遍","quiz":[{"ref":"bank:vocab:A2:高频动词与万能表达"}]}]},{"day":2,"theme":"语法 · 第一组动词现在时","type":"grammar","steps":[{"type":"grammar","title":"语法点：第一组动词现在时","body":"【第一组动词现在时】-er 动词现在时的词尾是 -e, -es, -e, -ons, -ez, -ent，其中第三人称复数的 -ent 完全不发音。否定把 ne 放在动词前、pas 放在动词后；口语中常省掉 ne，写成 Je sais pas，但书面语必须写全。 例句：<span class=\"fr\" data-fr=\"Je parle français et j'habite à Lyon.\">Je parle français et j'habite à Lyon.</span>（我说法语，我住在里昂。）；<span class=\"fr\" data-fr=\"Il ne travaille pas le samedi.\">Il ne travaille pas le samedi.</span>（他周六不工作。）。对照 grammar-a1a2.html#pres-er 的表格，把规则抄成自己的一句话。","src":"grammar-a1a2.html#pres-er","hint":"先读规则再看例句","quiz":[{"id":"q-gram-a1-5015","level":"A1","skill":"grammar","prompt":"Ils ___ le français.（parler）","options":["parlent","parlons","parlez"],"answer":"parlent","explain":"ils 对应词尾 -ent，而且 -ent 不发音，读音与 il parle 相同。","source":"语法 · -er 动词"},{"ref":"bank:grammar:A1:现在时"}]},{"type":"grammar","title":"规则拆解与常见错误","body":"先合上书，凭记忆写出 第一组动词现在时 的规则和两个例句，再打开 grammar-a1a2.html#pres-er 对照补漏，用红笔标出回忆失败的地方。回忆失败比再读一遍更有价值，那正是考试时会出错的位置。","src":"grammar-a1a2.html#pres-er","hint":"合上书默写一遍规则","quiz":[{"id":"q-gram-a1-5016","level":"A1","skill":"grammar","prompt":"「我不喜欢」的正确说法是？","options":["Je n'aime pas.","Je aime pas.","Je ne aime pas."],"answer":"Je n'aime pas.","explain":"ne 在元音前省音成 n'，所以写成 Je n'aime pas。","source":"语法 · 否定"},{"ref":"bank:grammar:A1:现在时"}]},{"type":"read","title":"在短文里找第一组动词现在时","body":"在 grammar-a1a2.html#pres-er 的例句和章末小测里挑 5 句，圈出所有属于「第一组动词现在时」的成分。读的时候先判断结构再理解意思，不要一开始就在脑子里翻译成中文。","src":"grammar-a1a2.html#pres-er","hint":"圈出全部相关成分","quiz":[{"ref":"bank:reading:A1:阅读"}]},{"type":"write","title":"限时仿写：8 句","body":"照 <span class=\"fr\" data-fr=\"Je parle français et j'habite à Lyon.\">Je parle français et j'habite à Lyon.</span>（我说法语，我住在里昂。）的句型仿写 8 句，内容必须是你自己的真实信息。写完用三色笔检查：红色圈主语、蓝色圈动词、绿色圈配合成分，第一组动词现在时 的结构至少出现两次。","src":"exams.html#ecrit","hint":"限时 12 分钟，写完自查","quiz":[{"ref":"bank:writing:A1:写作"}]},{"type":"grammar","title":"语法点巩固：否定 ne…pas","body":"今天再回 grammar-a1a2.html#negation 看一遍 否定 ne…pas，把两个语法点的差别写成一行对照（触发条件 / 形式 / 常见错误各一列）。写不出来就说明还停留在「读得懂」而不是「用得出」。","src":"grammar-a1a2.html#negation","hint":"把两个语法点写成对照表","quiz":[{"ref":"bank:grammar:A1:现在时"}]}]},{"day":3,"theme":"精听 · 对话页的 d05 篇","type":"listen","steps":[{"type":"listen","title":"精听（第一遍）：抓主旨","body":"打开 对话页的 d05 篇，盲听第一遍，不暂停、不看文本。只听一个问题：这段话在谈什么？用中文写一句概括，再写下 3 个听清的词。","src":"dialogue.html#d05","hint":"不暂停、不看文本","quiz":[{"id":"q-list-a1-5011","level":"A1","skill":"listening","prompt":"口语中 « Je sais pas. » 省略了什么？","options":["ne","pas","主语"],"answer":"ne","explain":"口语常省略 ne，只留 pas；书写时仍应写成 Je ne sais pas。","source":"语法 · 否定的口语形式"},{"ref":"bank:listening:A1:听力"}],"exam":"exam:listening:A2:车站广播"},{"type":"listen","title":"精听（第二遍）：听写关键句","body":"第二遍逐句暂停，听写 5 句含本周语法或新词的句子，写不出的地方标「?」。然后对照原文，把 ? 处按「词汇 / 联诵 / 语速」三类归档。本周的听力任务是：听含否定的对话，标出所有 ne…pas，并注意口语里常只剩 pas 的情况。","src":"dialogue.html#d05","hint":"逐句听写 5 句","quiz":[{"ref":"bank:listening:A1:听力"}]},{"type":"vocab","title":"听力词汇回收","body":"把听写中出现的生词与本周词表对照：<span class=\"fr\" data-fr=\"parler\">parler</span>（说，讲）、<span class=\"fr\" data-fr=\"habiter\">habiter</span>（居住）、<span class=\"fr\" data-fr=\"travailler\">travailler</span>（工作）。反复出现的词优先记，只出现一次又不影响理解的先放过，避免在细节里迷路。","src":"vocab.html#t25","hint":"生词与本周词表对照","quiz":[{"ref":"bank:vocab:A2:高频动词与万能表达"}]},{"type":"speak","title":"影子跟读 3 遍","body":"同一段材料做影子跟读（shadowing）：滞后原音半句跟读，重点模仿语调、连读与联诵，不要逐字念。跟完录 45 秒复述，不回看原文，卡住就用 <span class=\"fr\" data-fr=\"c'est-à-dire\">c'est-à-dire</span> 争取时间。","src":"exams.html#oral","hint":"滞后半句跟读，录 45 秒复述","quiz":[{"ref":"bank:speaking:A1:口语"}]},{"type":"listen","title":"精听（第三遍）：闭合听力","body":"第三遍只听不看，听完用法语说出 3 个关键信息，再写一句「第一组动词现在时 在这段里出现的位置」。仍听不懂的句子重复听 2 次，还不懂就记下来，第 7 天集中解决。","src":"dialogue.html#d05","hint":"只听不看，说出 3 个关键信息","quiz":[{"ref":"bank:listening:A1:听力"}]}]},{"day":4,"theme":"口语 · 第一组动词 -er 现在时与否定","type":"speak","steps":[{"type":"speak","title":"口语任务：本周主题陈述","body":"口语任务：用 10 个 -er 动词造肯定句，再逐句口头改成否定，要求 3 秒内完成切换。 开口前先想好「观点—理由—例子」三段，允许说得慢，但不许说到一半换主题。说完立刻自评一句：哪一段最流畅、哪一段最卡，卡住的地方就是下一次的训练重点。","src":"exams.html#oral","hint":"先说满 60 秒不停","quiz":[{"id":"q-speak-a1-5007","level":"A1","skill":"speaking","prompt":"把 « Je travaille. » 改成否定句？","options":["Je ne travaille pas.","Je travaille ne pas.","Je pas travaille."],"answer":"Je ne travaille pas.","explain":"否定结构是 ne + 动词 + pas，ne 在前、pas 在后，位置固定。","source":"语法 · 否定"},{"ref":"bank:speaking:A1:口语"}]},{"type":"speak","title":"结构与衔接：先列提纲再开口","body":"把答案录在手机里，先说满 60 秒不停。说到一半忘词就先换一种说法把意思顶过去，流利度优先于用词精确。录完不要马上回听，隔十分钟再听一遍，判断会更客观。","src":"exams.html#oral","hint":"三个关键词 + 三段衔接词","quiz":[{"ref":"bank:speaking:A1:口语"}]},{"type":"listen","title":"听范例找差距","body":"听一段同主题范例（对话页的 d05 篇），把自己的录音和范例逐项对比：语速、停顿位置、连接词的使用、第一组动词现在时 的正确形式。只记录 3 个今天就能改的点。","src":"dialogue.html#d05","hint":"只记 3 个可立刻改进的点","quiz":[{"ref":"bank:listening:A1:听力"}]},{"type":"vocab","title":"把新词用进嘴里","body":"把 <span class=\"fr\" data-fr=\"aimer\">aimer</span>（喜欢）、<span class=\"fr\" data-fr=\"étudier\">étudier</span>（学习）、<span class=\"fr\" data-fr=\"manger\">manger</span>（吃）轮流塞进刚才的答案里，每个词至少用一次。说不顺就说明这个词还没真正归属你，回到 vocab.html#t25 再看一遍例句。","src":"vocab.html#t25","hint":"每个新词至少用一次","quiz":[{"ref":"bank:vocab:A2:高频动词与万能表达"}]},{"type":"speak","title":"重录一遍并自评","body":"按前面记录的 3 个问题重录一次，目标是同样的内容用更少的停顿说完。回听时数一数填充词（euh、ben、voilà）出现几次，第 7 天把两次录音放在一起比较。","src":"exams.html#oral","hint":"数一数填充词次数","quiz":[{"ref":"bank:speaking:A1:口语"}]}]},{"day":5,"theme":"精读 · 第一组动词 -er 现在时与否定","type":"read","steps":[{"type":"read","title":"精读：本周阅读材料","body":"精读任务：读语法页第一组动词与否定章节，把 -er 词尾抄成一行口诀。 读第一遍只抓主旨，第二遍才处理细节，遇到生词先猜再查。读完先用一句话写出全文主旨，再回头处理细节，避免一开始就陷进生词里。","src":"exams.html#lecture","hint":"第一遍抓主旨，第二遍抓细节","quiz":[{"id":"q-read-a1-5009","level":"A1","skill":"reading","prompt":"下列哪句中的否定词表示「不再」？","options":["Il ne fume plus.","Il ne fume pas.","Il ne fume jamais."],"answer":"Il ne fume plus.","explain":"ne…plus 表示不再；ne…pas 是一般否定；ne…jamais 是从不。","source":"语法 · 否定扩展"},{"ref":"bank:reading:A1:阅读"}]},{"type":"read","title":"长句解构：先找主干","body":"挑文中 3 个超过 20 词的长句，先划出主谓宾，再把从句、分词、介词短语逐层挂上去。看到「第一组动词现在时」的结构就停下来确认触发条件。","src":"exams.html#lecture","hint":"拆 3 个长句，主干与修饰分栏","quiz":[{"ref":"bank:reading:A1:阅读"}]},{"type":"vocab","title":"阅读词汇：上下文猜词","body":"遇到生词先按词根、词尾和上下文猜一次再核对。本周词表里的 <span class=\"fr\" data-fr=\"parler\">parler</span>（说，讲）、<span class=\"fr\" data-fr=\"habiter\">habiter</span>（居住）如果以别的形式出现，把那一整句抄进卡片。","src":"vocab.html#t25","hint":"先猜再查，把整句抄下来","quiz":[{"ref":"bank:vocab:A2:高频动词与万能表达"}]},{"type":"grammar","title":"语法在句子里的样子","body":"回到 grammar-a1a2.html#pres-er，对照文中出现的同类结构，确认书面语和口语的差别。摘抄 3 句可以直接套进写作的句子，标注它们的连接词和语式。","src":"grammar-a1a2.html#pres-er","hint":"摘 3 句能直接用的句子","quiz":[{"ref":"bank:grammar:A1:现在时"}]},{"type":"write","title":"100 词摘要","body":"不照抄原句，用 100 词概括文章并加一句自己的评价。写完统计三个数字：平均句长、连接词数量、「第一组动词现在时」出现次数，看看自己的书面语是不是只会并列短句。","src":"exams.html#ecrit","hint":"改写不照抄，统计三个数字","quiz":[{"ref":"bank:writing:A1:写作"}]}]},{"day":6,"theme":"写作 · 第一组动词 -er 现在时与否定","type":"write","steps":[{"type":"write","title":"写作任务：本周产出","body":"写作任务：写「我的一天」10 句，全用 -er 动词现在时，其中 3 句是否定句。 先列提纲再动笔，写完整篇留 5 分钟只做一遍通读检查。动笔前先确认题目要求写几段、用什么语域，避免写到一半推翻结构。","src":"exams.html#ecrit","hint":"先列提纲，再限时成文","quiz":[{"id":"q-writ-a1-5005","level":"A1","skill":"writing","prompt":"« Nous ___ à Paris. »（habiter）","options":["habitons","habitez","habitent"],"answer":"habitons","explain":"nous 对应 -ons：nous habitons；-ez 给 vous，-ent 给 ils / elles。","source":"语法 · -er 动词"},{"ref":"bank:writing:A1:写作"}]},{"type":"write","title":"提纲与逻辑链","body":"先写中文要点，再逐条译成法语，但译完必须回头改：把中文语序的句子打散重写，让动词和它的补语各就各位。改完把最生硬的 3 句抄到一边，作为下一稿的重点对象。","src":"exams.html#ecrit","hint":"三段式提纲，每段一个论点","quiz":[{"ref":"bank:writing:A1:写作"}]},{"type":"grammar","title":"写前语法自查清单","body":"打开 grammar-a1a2.html#pres-er，把本周语法点做成 3 条自查项写在旁边，例如「触发词有没有用对」「变位与配合是否一致」。写完通读只检查这 3 条，其余问题留到第二稿再处理。","src":"grammar-a1a2.html#pres-er","hint":"三条自查项，只查这三条","quiz":[{"ref":"bank:grammar:A1:现在时"}]},{"type":"read","title":"对照范文找可替换表达","body":"读考试页的范文，列出 10 处「我只会用简单说法、范文用了更地道说法」的对照，抄进表达本。重点看范文怎么用「第一组动词现在时」和连接词，对照表按「我的说法 / 范文说法 / 适用场景」三列记录。","src":"exams.html#redaction","hint":"抄 10 组对照表达","quiz":[{"ref":"bank:reading:A1:阅读"}]},{"type":"speak","title":"把写的文章讲出来","body":"脱稿把自己写的文章讲 2 分钟，允许简化但不许背稿。讲不顺的句子说明书面结构还没内化，回到文中改写一次，再讲一遍；同时把 <span class=\"fr\" data-fr=\"parler\">parler</span>（说，讲）用进口语版本。","src":"exams.html#oral","hint":"脱稿讲 2 分钟，不背稿","quiz":[{"ref":"bank:speaking:A1:口语"}]}]},{"day":7,"theme":"复盘 · 第一组动词 -er 现在时与否定","type":"review","steps":[{"type":"review","title":"本周回顾：第一组动词 -er 现在时与否定","body":"这一周围绕「第一组动词 -er 现在时与否定」展开：语法主线是 第一组动词现在时，词汇主线是 高频动词与万能表达。先用 3 句话口头复述本周学了什么，再打开日历页第 5 周清单逐条核对里程碑。","src":"calendar.html#wk-5","hint":"先口头复述，再核对里程碑","quiz":[{"ref":"bank:vocab:A2:高频动词与万能表达"}]},{"type":"review","title":"语法复盘：第一组动词现在时","body":"从 grammar-a1a2.html#pres-er 的规则与例句里各抽 3 条：默写规则、翻译例句再对照，最后写下 2 个自己最可能犯的错。凡是默写时卡住的地方，就是下一周要带着继续练的问题。","src":"grammar-a1a2.html#pres-er","hint":"默写规则与例句，各抽 3 条","quiz":[{"ref":"bank:grammar:A1:现在时"}]},{"type":"review","title":"词汇自测：高频动词与万能表达","body":"遮住中文看 vocab.html#t25 的 6 个核心词：<span class=\"fr\" data-fr=\"parler\">parler</span> <span class=\"fr\" data-fr=\"habiter\">habiter</span> <span class=\"fr\" data-fr=\"travailler\">travailler</span> <span class=\"fr\" data-fr=\"aimer\">aimer</span> <span class=\"fr\" data-fr=\"étudier\">étudier</span> <span class=\"fr\" data-fr=\"manger\">manger</span>。能秒答的划掉，犹豫超过 3 秒的抄进错词本。本周目标是新词认词率不低于 85%。","src":"vocab.html#t25","hint":"遮中文秒答，犹豫即抄错词本","quiz":[{"id":"q-vocab-a1-5017","level":"A1","skill":"vocab","prompt":"« aimer » 的意思是？","options":["喜欢","居住","吃饭"],"answer":"喜欢","explain":"aimer 是喜欢、爱；habiter 是居住；manger 是吃。","source":"词汇 · 高频动词"},{"id":"q-vocab-a1-5018","level":"A1","skill":"vocab","prompt":"「学习」用法语说是？","options":["étudier","habiter","parler"],"answer":"étudier","explain":"étudier 是学习；habiter 是居住；parler 是说话。","source":"词汇 · 高频动词"},{"ref":"bank:vocab:A2:高频动词与万能表达"}]},{"type":"review","title":"综合题（一）：听读理解","body":"先做下面的听读综合题，不查词、不回看材料，限时 5 分钟。做完再回材料定位每道题的证据句，把「没找到证据就选」的题目标出来——那是失分的主要来源。","src":"dialogue.html#d05","hint":"限时 5 分钟，做完回材料找证据","quiz":[{"id":"q-list-a1-5012","level":"A1","skill":"listening","prompt":"« Nous parlons » 中词尾 -ons 的读音是？","options":["/ɔ̃/","/ɔn/","/ons/"],"answer":"/ɔ̃/","explain":"parlons 的词尾 -ons 读鼻化元音 /ɔ̃/，词末的 s 不发音；写成 /ɔn/ 是把鼻化元音拆开了。","source":"语音 · -er 动词读音"},{"id":"q-read-a1-5010","level":"A1","skill":"reading","prompt":"« Elles aiment… » 中词尾 -ent 的读音是？","options":["不发音","/ɑ̃/","/ɛnt/"],"answer":"不发音","explain":"-er 动词第三人称复数的 -ent 完全不发音，aiment 读 /ɛm/。","source":"语法 · -er 动词"},{"ref":"bank:listening:A1:听力"}]},{"type":"review","title":"综合题（二）：语法与词汇","body":"这一组题检查 第一组动词现在时 与本周词汇的调用能力。每道题都问自己：错误选项错在哪里？能说出错因才算真的会，说不出来就回到 grammar-a1a2.html#pres-er 再核对一次。","src":"grammar-a1a2.html#negation","hint":"每题都说出错项错在哪","quiz":[{"id":"q-gram-a1-5017","level":"A1","skill":"grammar","prompt":"« Tu ___ le cinéma ? »（aimer）","options":["aimes","aime","aimez"],"answer":"aimes","explain":"tu 对应 -es：tu aimes；-e 给 il / elle，-ez 给 vous。","source":"语法 · -er 动词"},{"id":"q-gram-a1-5018","level":"A1","skill":"grammar","prompt":"下列哪句是对的？","options":["Je ne parle pas anglais.","Je ne parle anglais pas.","Je parle ne pas anglais."],"answer":"Je ne parle pas anglais.","explain":"ne 必须在动词前、pas 在动词后，中间不能被宾语隔开。","source":"语法 · 否定"},{"ref":"bank:grammar:A1:现在时"}]},{"type":"review","title":"输出任务与自评表","body":"完成一段 90 秒口述或 120 词短文，内容必须同时用上本周的 2 个词和 1 个语法结构。按「任务完成 / 连贯 / 词汇 / 语法 / 拼写」五项各打 1–5 分，低于 3 分的写进下周补漏清单。","src":"exams.html#oral","hint":"五项各打 1–5 分","quiz":[{"ref":"bank:writing:A1:写作"}]}]}]},{"week":6,"level":"A1","theme":"形容词性数配合与位置","days":[{"day":1,"theme":"词汇 · 外貌与性格","type":"vocab","steps":[{"type":"vocab","title":"主题词汇域：外貌与性格","body":"外貌与性格（L'apparence et le caractère）是这一周要反复见面的主题域。打开 vocab.html#t4，先看词表怎么分组，再把 <span class=\"fr\" data-fr=\"grand\">grand</span>（高大的（阳性））、<span class=\"fr\" data-fr=\"petit\">petit</span>（矮小的（阳性））、<span class=\"fr\" data-fr=\"beau\">beau</span>（漂亮的（阳性））读三遍，然后遮住中文说意思。记不住的词单独建一张「顽固词表」。","src":"vocab.html#t4","hint":"先读后抄，每个词出声读三遍","quiz":[{"id":"q-vocab-a1-5019","level":"A1","skill":"vocab","prompt":"« sympathique » 的意思是？","options":["友好的","聪明的","漂亮的"],"answer":"友好的","explain":"sympathique 指友善、讨人喜欢；intelligent 是聪明；beau 是漂亮。","source":"词汇 · 性格"},{"ref":"bank:vocab:A1:外貌与性格"}]},{"type":"vocab","title":"搭配与辨析：intelligent / sympathique","body":"<span class=\"fr\" data-fr=\"intelligent\">intelligent</span>（聪明的（阳性））与 <span class=\"fr\" data-fr=\"sympathique\">sympathique</span>（友好的）是本组最容易混的两个词。为每个词写 2 个搭配（一个名词搭配、一个动词搭配），读出来判断哪个更自然，拿不准的留到第 7 天复盘。","src":"vocab.html#t4","hint":"两个词各写 2 个搭配","quiz":[{"id":"q-vocab-a1-5020","level":"A1","skill":"vocab","prompt":"「短发」用法语说是？","options":["les cheveux courts","les cheveux court","le cheveu court"],"answer":"les cheveux courts","explain":"cheveux 是复数名词，形容词也要用阳性复数 courts。","source":"语法 · 形容词配合"},{"ref":"bank:vocab:A1:外貌与性格"}]},{"type":"listen","title":"听音辨词：外貌与性格","body":"打开 对话页的 d10 篇，先盲听一遍，只做一件事：抓出含本周新词的句子并写下关键词。第二遍再对照法文原文，检查自己漏掉的是词还是联诵。像 <span class=\"fr\" data-fr=\"les cheveux courts\">les cheveux courts</span>（短发）这样的词如果没听出来，单独标出来。","src":"dialogue.html#d10","hint":"盲听一遍再对照原文","quiz":[{"ref":"bank:listening:A1:听力"}]},{"type":"speak","title":"口头造句：6 个新词进短句","body":"用今天抄的 6 个词各说一句，主语在 je / nous / on 之间换着用。参考例句 <span class=\"fr\" data-fr=\"C'est une belle maison et un beau jardin.\">C'est une belle maison et un beau jardin.</span>（这是一栋漂亮的房子和一个漂亮的花园。）。录 60 秒，回听时只挑两个问题：冠词有没有丢、动词有没有跟主语配合。","src":"exams.html#oral","hint":"录音 60 秒并回听","quiz":[{"ref":"bank:speaking:A1:口语"}]},{"type":"vocab","title":"日终自测：外貌与性格 认词","body":"遮住中文，只看法语说意思：<span class=\"fr\" data-fr=\"grand\">grand</span> <span class=\"fr\" data-fr=\"petit\">petit</span> <span class=\"fr\" data-fr=\"beau\">beau</span> <span class=\"fr\" data-fr=\"intelligent\">intelligent</span> <span class=\"fr\" data-fr=\"sympathique\">sympathique</span> <span class=\"fr\" data-fr=\"les cheveux courts\">les cheveux courts</span>。说不出来的词立刻回到 vocab.html#t4 重记一遍，并在卡片角上打一个星号，星号词明天先复习。","src":"vocab.html#t4","hint":"先遮中文，再遮法语，两个方向各过一遍","quiz":[{"ref":"bank:vocab:A1:外貌与性格"}]}]},{"day":2,"theme":"语法 · 形容词性数配合","type":"grammar","steps":[{"type":"grammar","title":"语法点：形容词性数配合","body":"【形容词性数配合】形容词要与名词的性和数一致：grand / grande / grands / grandes。多数形容词后置，表示美丑、年龄、好坏、大小的短形容词（BAGS）前置，前置时 beau / nouveau / vieux 在元音或哑音 h 前要变成 bel / nouvel / vieil。 例句：<span class=\"fr\" data-fr=\"C'est une belle maison et un beau jardin.\">C'est une belle maison et un beau jardin.</span>（这是一栋漂亮的房子和一个漂亮的花园。）；<span class=\"fr\" data-fr=\"Il a les cheveux courts et les yeux bleus.\">Il a les cheveux courts et les yeux bleus.</span>（他留着短发，有一双蓝眼睛。）。对照 grammar-a1a2.html#adj-accord 的表格，把规则抄成自己的一句话。","src":"grammar-a1a2.html#adj-accord","hint":"先读规则再看例句","quiz":[{"id":"q-gram-a1-5019","level":"A1","skill":"grammar","prompt":"une ___ maison（beau）","options":["belle","beau","bel"],"answer":"belle","explain":"maison 是阴性单数，beau 的阴性形式是 belle。","source":"语法 · 形容词配合"},{"ref":"bank:grammar:A1:形容词"}]},{"type":"grammar","title":"规则拆解与常见错误","body":"对着 grammar-a1a2.html#adj-accord 自查三件事：① 触发条件是什么；② 变位或配合落在哪个词尾；③ 有哪些例外要单独记。然后把 <span class=\"fr\" data-fr=\"C'est une belle maison et un beau jardin.\">C'est une belle maison et un beau jardin.</span>（这是一栋漂亮的房子和一个漂亮的花园。）拆到词，逐一说明每个成分为什么用这个形式。","src":"grammar-a1a2.html#adj-accord","hint":"合上书默写一遍规则","quiz":[{"id":"q-gram-a1-5020","level":"A1","skill":"grammar","prompt":"下列哪一组形容词通常前置？","options":["un grand homme","un livre intéressant","une voiture rouge"],"answer":"un grand homme","explain":"表示大小、美丑、年龄、好坏的短形容词前置；颜色与国籍类一律后置。","source":"语法 · 形容词位置"},{"ref":"bank:grammar:A1:形容词"}]},{"type":"read","title":"在短文里找形容词性数配合","body":"在 grammar-a1a2.html#adj-accord 的例句和章末小测里挑 5 句，圈出所有属于「形容词性数配合」的成分。读的时候先判断结构再理解意思，不要一开始就在脑子里翻译成中文。","src":"grammar-a1a2.html#adj-accord","hint":"圈出全部相关成分","quiz":[{"ref":"bank:reading:A1:阅读"}]},{"type":"write","title":"限时仿写：8 句","body":"照 <span class=\"fr\" data-fr=\"C'est une belle maison et un beau jardin.\">C'est une belle maison et un beau jardin.</span>（这是一栋漂亮的房子和一个漂亮的花园。）的句型仿写 8 句，内容必须是你自己的真实信息。写完用三色笔检查：红色圈主语、蓝色圈动词、绿色圈配合成分，形容词性数配合 的结构至少出现两次。","src":"exams.html#ecrit","hint":"限时 12 分钟，写完自查","quiz":[{"ref":"bank:writing:A1:写作"}]},{"type":"grammar","title":"语法点巩固：形容词的位置","body":"今天再回 grammar-a1a2.html#adj-place 看一遍 形容词的位置，把两个语法点的差别写成一行对照（触发条件 / 形式 / 常见错误各一列）。写不出来就说明还停留在「读得懂」而不是「用得出」。","src":"grammar-a1a2.html#adj-place","hint":"把两个语法点写成对照表","quiz":[{"ref":"bank:grammar:A1:形容词"}]}]},{"day":3,"theme":"精听 · 对话页的 d10 篇","type":"listen","steps":[{"type":"listen","title":"精听（第一遍）：抓主旨","body":"第一遍听的时候不要追求每个词都懂。对话页的 d10 篇 的材料先听三分钟，抓住说话人、场景和态度，其余细节留到第二遍。听之前先用 10 秒预测这段话会出现哪些本周词汇，带着预测去听，抓取效率会明显提高。","src":"dialogue.html#d10","hint":"不暂停、不看文本","quiz":[{"id":"q-list-a1-5013","level":"A1","skill":"listening","prompt":"听到 /yn bɛl fam/ 时对应的写法是？","options":["une belle femme","un bel homme","une beau femme"],"answer":"une belle femme","explain":"femme 是阴性单数，用 belle；bel 只用于元音或哑音 h 开头的阳性名词前。","source":"语法 · 形容词配合"},{"ref":"bank:listening:A1:听力"}],"exam":"exam:listening:A2:车站广播"},{"type":"listen","title":"精听（第二遍）：听写关键句","body":"第二遍逐句暂停，听写 5 句含本周语法或新词的句子，写不出的地方标「?」。然后对照原文，把 ? 处按「词汇 / 联诵 / 语速」三类归档。本周的听力任务是：听描述人物的音频，听写 10 组「形容词 + 名词」，标出听到的性数变化。","src":"dialogue.html#d10","hint":"逐句听写 5 句","quiz":[{"ref":"bank:listening:A1:听力"}]},{"type":"vocab","title":"听力词汇回收","body":"把听写中出现的生词与本周词表对照：<span class=\"fr\" data-fr=\"grand\">grand</span>（高大的（阳性））、<span class=\"fr\" data-fr=\"petit\">petit</span>（矮小的（阳性））、<span class=\"fr\" data-fr=\"beau\">beau</span>（漂亮的（阳性））。反复出现的词优先记，只出现一次又不影响理解的先放过，避免在细节里迷路。","src":"vocab.html#t4","hint":"生词与本周词表对照","quiz":[{"ref":"bank:vocab:A1:外貌与性格"}]},{"type":"speak","title":"影子跟读 3 遍","body":"同一段材料做影子跟读（shadowing）：滞后原音半句跟读，重点模仿语调、连读与联诵，不要逐字念。跟完录 45 秒复述，不回看原文，卡住就用 <span class=\"fr\" data-fr=\"c'est-à-dire\">c'est-à-dire</span> 争取时间。","src":"exams.html#oral","hint":"滞后半句跟读，录 45 秒复述","quiz":[{"ref":"bank:speaking:A1:口语"}]},{"type":"listen","title":"精听（第三遍）：闭合听力","body":"第三遍只听不看，听完用法语说出 3 个关键信息，再写一句「形容词性数配合 在这段里出现的位置」。仍听不懂的句子重复听 2 次，还不懂就记下来，第 7 天集中解决。","src":"dialogue.html#d10","hint":"只听不看，说出 3 个关键信息","quiz":[{"ref":"bank:listening:A1:听力"}]}]},{"day":4,"theme":"口语 · 形容词性数配合与位置","type":"speak","steps":[{"type":"speak","title":"口语任务：本周主题陈述","body":"口语任务：描述 3 个人（家人、朋友、自己）各 4 句，形容词必须与名词配合。 开口前先想好「观点—理由—例子」三段，允许说得慢，但不许说到一半换主题。说完立刻自评一句：哪一段最流畅、哪一段最卡，卡住的地方就是下一次的训练重点。","src":"exams.html#oral","hint":"先说满 60 秒不停","quiz":[{"id":"q-speak-a1-5008","level":"A1","skill":"speaking","prompt":"「他很聪明」说法正确的是？","options":["Il est intelligent.","Il est intelligente.","Il est intelligents."],"answer":"Il est intelligent.","explain":"主语 il 是阳性单数，形容词用阳性单数形式，不加 -e 也不加 -s。","source":"语法 · 形容词配合"},{"ref":"bank:speaking:A1:口语"}]},{"type":"speak","title":"结构与衔接：先列提纲再开口","body":"用 30 秒写 3 个关键词当提纲，再用 <span class=\"fr\" data-fr=\"d'abord\">d'abord</span> / <span class=\"fr\" data-fr=\"ensuite\">ensuite</span> / <span class=\"fr\" data-fr=\"enfin\">enfin</span> 把三段串起来。卡壳时用 <span class=\"fr\" data-fr=\"c'est-à-dire\">c'est-à-dire</span> 或 <span class=\"fr\" data-fr=\"disons que…\">disons que…</span> 争取时间，不要用中文思考再翻译。","src":"exams.html#oral","hint":"三个关键词 + 三段衔接词","quiz":[{"ref":"bank:speaking:A1:口语"}]},{"type":"listen","title":"听范例找差距","body":"听一段同主题范例（对话页的 d10 篇），把自己的录音和范例逐项对比：语速、停顿位置、连接词的使用、形容词性数配合 的正确形式。只记录 3 个今天就能改的点。","src":"dialogue.html#d10","hint":"只记 3 个可立刻改进的点","quiz":[{"ref":"bank:listening:A1:听力"}]},{"type":"vocab","title":"把新词用进嘴里","body":"把 <span class=\"fr\" data-fr=\"intelligent\">intelligent</span>（聪明的（阳性））、<span class=\"fr\" data-fr=\"sympathique\">sympathique</span>（友好的）、<span class=\"fr\" data-fr=\"les cheveux courts\">les cheveux courts</span>（短发）轮流塞进刚才的答案里，每个词至少用一次。说不顺就说明这个词还没真正归属你，回到 vocab.html#t4 再看一遍例句。","src":"vocab.html#t4","hint":"每个新词至少用一次","quiz":[{"ref":"bank:vocab:A1:外貌与性格"}]},{"type":"speak","title":"重录一遍并自评","body":"按前面记录的 3 个问题重录一次，目标是同样的内容用更少的停顿说完。回听时数一数填充词（euh、ben、voilà）出现几次，第 7 天把两次录音放在一起比较。","src":"exams.html#oral","hint":"数一数填充词次数","quiz":[{"ref":"bank:speaking:A1:口语"}]}]},{"day":5,"theme":"精读 · 形容词性数配合与位置","type":"read","steps":[{"type":"read","title":"精读：本周阅读材料","body":"精读任务：读语法页形容词章节与特殊形容词表，把 BAGS 抄在卡片上。 读第一遍只抓主旨，第二遍才处理细节，遇到生词先猜再查。读完先用一句话写出全文主旨，再回头处理细节，避免一开始就陷进生词里。","src":"exams.html#lecture","hint":"第一遍抓主旨，第二遍抓细节","quiz":[{"id":"q-read-a1-5011","level":"A1","skill":"reading","prompt":"« un vieil arbre » 中为什么用 vieil？","options":["arbre 以元音开头","arbre 是阴性","arbre 是复数"],"answer":"arbre 以元音开头","explain":"vieux 在元音或哑音 h 开头的阳性单数名词前变成 vieil。","source":"语法 · 特殊形容词"},{"ref":"bank:reading:A1:阅读"}]},{"type":"read","title":"长句解构：先找主干","body":"把长句按「主干 + 修饰」两栏抄写：左栏只留主谓宾，右栏按顺序列出从句与补语。拆完再合起来读一遍，语序感会明显变好。判断不出从句类型时，先整段框起来，读完上下文再回来标注。","src":"exams.html#lecture","hint":"拆 3 个长句，主干与修饰分栏","quiz":[{"ref":"bank:reading:A1:阅读"}]},{"type":"vocab","title":"阅读词汇：上下文猜词","body":"遇到生词先按词根、词尾和上下文猜一次再核对。本周词表里的 <span class=\"fr\" data-fr=\"grand\">grand</span>（高大的（阳性））、<span class=\"fr\" data-fr=\"petit\">petit</span>（矮小的（阳性））如果以别的形式出现，把那一整句抄进卡片。","src":"vocab.html#t4","hint":"先猜再查，把整句抄下来","quiz":[{"ref":"bank:vocab:A1:外貌与性格"}]},{"type":"grammar","title":"语法在句子里的样子","body":"回到 grammar-a1a2.html#adj-accord，对照文中出现的同类结构，确认书面语和口语的差别。摘抄 3 句可以直接套进写作的句子，标注它们的连接词和语式。","src":"grammar-a1a2.html#adj-accord","hint":"摘 3 句能直接用的句子","quiz":[{"ref":"bank:grammar:A1:形容词"}]},{"type":"write","title":"100 词摘要","body":"不照抄原句，用 100 词概括文章并加一句自己的评价。写完统计三个数字：平均句长、连接词数量、「形容词性数配合」出现次数，看看自己的书面语是不是只会并列短句。","src":"exams.html#ecrit","hint":"改写不照抄，统计三个数字","quiz":[{"ref":"bank:writing:A1:写作"}]}]},{"day":6,"theme":"写作 · 形容词性数配合与位置","type":"write","steps":[{"type":"write","title":"写作任务：本周产出","body":"写作任务：写两段人物描写，每段 6 句，圈出所有形容词与名词的性数对应。 先列提纲再动笔，写完整篇留 5 分钟只做一遍通读检查。动笔前先确认题目要求写几段、用什么语域，避免写到一半推翻结构。","src":"exams.html#ecrit","hint":"先列提纲，再限时成文","quiz":[{"id":"q-writ-a1-5006","level":"A1","skill":"writing","prompt":"「两个漂亮的女孩」正确写法是？","options":["deux belles filles","deux belle filles","deux beaux filles"],"answer":"deux belles filles","explain":"filles 是阴性复数，beau 的阴性复数形式是 belles。","source":"语法 · 形容词配合"},{"ref":"bank:writing:A1:写作"}]},{"type":"write","title":"提纲与逻辑链","body":"动笔前把提纲写成三段式：每段一个论点，每个论点配一个具体例子。检查连接词是否多样，别整段只用 et 和 mais。提纲写完后放一分钟再看一遍，如果一句话就能说清每段的作用，结构就算过关。","src":"exams.html#ecrit","hint":"三段式提纲，每段一个论点","quiz":[{"ref":"bank:writing:A1:写作"}]},{"type":"grammar","title":"写前语法自查清单","body":"打开 grammar-a1a2.html#adj-accord，把本周语法点做成 3 条自查项写在旁边，例如「触发词有没有用对」「变位与配合是否一致」。写完通读只检查这 3 条，其余问题留到第二稿再处理。","src":"grammar-a1a2.html#adj-accord","hint":"三条自查项，只查这三条","quiz":[{"ref":"bank:grammar:A1:形容词"}]},{"type":"read","title":"对照范文找可替换表达","body":"读考试页的范文，列出 10 处「我只会用简单说法、范文用了更地道说法」的对照，抄进表达本。重点看范文怎么用「形容词性数配合」和连接词，对照表按「我的说法 / 范文说法 / 适用场景」三列记录。","src":"exams.html#redaction","hint":"抄 10 组对照表达","quiz":[{"ref":"bank:reading:A1:阅读"}]},{"type":"speak","title":"把写的文章讲出来","body":"脱稿把自己写的文章讲 2 分钟，允许简化但不许背稿。讲不顺的句子说明书面结构还没内化，回到文中改写一次，再讲一遍；同时把 <span class=\"fr\" data-fr=\"grand\">grand</span>（高大的（阳性））用进口语版本。","src":"exams.html#oral","hint":"脱稿讲 2 分钟，不背稿","quiz":[{"ref":"bank:speaking:A1:口语"}]}]},{"day":7,"theme":"复盘 · 形容词性数配合与位置","type":"review","steps":[{"type":"review","title":"本周回顾：形容词性数配合与位置","body":"这一周围绕「形容词性数配合与位置」展开：语法主线是 形容词性数配合，词汇主线是 外貌与性格。先用 3 句话口头复述本周学了什么，再打开日历页第 6 周清单逐条核对里程碑。","src":"calendar.html#wk-6","hint":"先口头复述，再核对里程碑","quiz":[{"ref":"bank:vocab:A1:外貌与性格"}]},{"type":"review","title":"语法复盘：形容词性数配合","body":"从 grammar-a1a2.html#adj-accord 的规则与例句里各抽 3 条：默写规则、翻译例句再对照，最后写下 2 个自己最可能犯的错。凡是默写时卡住的地方，就是下一周要带着继续练的问题。","src":"grammar-a1a2.html#adj-accord","hint":"默写规则与例句，各抽 3 条","quiz":[{"ref":"bank:grammar:A1:形容词"}]},{"type":"review","title":"词汇自测：外貌与性格","body":"遮住中文看 vocab.html#t4 的 6 个核心词：<span class=\"fr\" data-fr=\"grand\">grand</span> <span class=\"fr\" data-fr=\"petit\">petit</span> <span class=\"fr\" data-fr=\"beau\">beau</span> <span class=\"fr\" data-fr=\"intelligent\">intelligent</span> <span class=\"fr\" data-fr=\"sympathique\">sympathique</span> <span class=\"fr\" data-fr=\"les cheveux courts\">les cheveux courts</span>。能秒答的划掉，犹豫超过 3 秒的抄进错词本。本周目标是新词认词率不低于 85%。","src":"vocab.html#t4","hint":"遮中文秒答，犹豫即抄错词本","quiz":[{"id":"q-vocab-a1-5021","level":"A1","skill":"vocab","prompt":"« petit » 的阴性形式是？","options":["petite","petit","petits"],"answer":"petite","explain":"petit 的阴性加 -e 变 petite；petits 是阳性复数。","source":"语法 · 形容词配合"},{"id":"q-vocab-a1-5022","level":"A1","skill":"vocab","prompt":"「眼睛」的复数形式是？","options":["les yeux","les oeils","les œil"],"answer":"les yeux","explain":"œil 的复数是 yeux，属于不规则复数，必须单独记。","source":"词汇 · 身体"},{"ref":"bank:vocab:A1:外貌与性格"}]},{"type":"review","title":"综合题（一）：听读理解","body":"先做下面的听读综合题，不查词、不回看材料，限时 5 分钟。做完再回材料定位每道题的证据句，把「没找到证据就选」的题目标出来——那是失分的主要来源。","src":"dialogue.html#d10","hint":"限时 5 分钟，做完回材料找证据","quiz":[{"id":"q-list-a1-5014","level":"A1","skill":"listening","prompt":"听到 /le ʒœn ʒɑ̃/ 时最可能是？","options":["les jeunes gens","le jeune homme","les gens jeunes"],"answer":"les jeunes gens","explain":"gens 是复数名词，jeunes 要配合成复数；le jeune homme 会用单数冠词。","source":"语法 · 形容词配合"},{"id":"q-read-a1-5012","level":"A1","skill":"reading","prompt":"« une voiture rouge » 中 rouge 为什么在后？","options":["颜色形容词通常后置","rouge 是例外","表示大小"],"answer":"颜色形容词通常后置","explain":"法语中颜色、国籍、形状类形容词一律后置，只有 BAGS 类短形容词前置。","source":"语法 · 形容词位置"},{"ref":"bank:listening:A1:听力"}]},{"type":"review","title":"综合题（二）：语法与词汇","body":"这一组题检查 形容词性数配合 与本周词汇的调用能力。每道题都问自己：错误选项错在哪里？能说出错因才算真的会，说不出来就回到 grammar-a1a2.html#adj-accord 再核对一次。","src":"grammar-a1a2.html#adj-place","hint":"每题都说出错项错在哪","quiz":[{"id":"q-gram-a1-5021","level":"A1","skill":"grammar","prompt":"« un ___ vélo »（nouveau）","options":["nouveau","nouvel","nouvelle"],"answer":"nouveau","explain":"vélo 以辅音开头、阳性单数，用 nouveau；nouvel 只用于元音或哑音 h 前。","source":"语法 · 特殊形容词"},{"id":"q-gram-a1-5022","level":"A1","skill":"grammar","prompt":"下列哪句配合正确？","options":["Elles sont grandes.","Elles sont grand.","Elles sont grands."],"answer":"Elles sont grandes.","explain":"主语 elles 是阴性复数，形容词要用 grandes。","source":"语法 · 形容词配合"},{"ref":"bank:grammar:A1:形容词"}]},{"type":"review","title":"输出任务与自评表","body":"完成一段 90 秒口述或 120 词短文，内容必须同时用上本周的 2 个词和 1 个语法结构。按「任务完成 / 连贯 / 词汇 / 语法 / 拼写」五项各打 1–5 分，低于 3 分的写进下周补漏清单。","src":"exams.html#oral","hint":"五项各打 1–5 分","quiz":[{"ref":"bank:writing:A1:写作"}]}]}]},{"week":7,"level":"A1","theme":"疑问句三式与疑问词","days":[{"day":1,"theme":"词汇 · 城市与交通","type":"vocab","steps":[{"type":"vocab","title":"主题词汇域：城市与交通","body":"本周词汇主战场是城市与交通（La ville et les transports）。先到 vocab.html#t9 把词表扫一遍，把 <span class=\"fr\" data-fr=\"où\">où</span>（哪里）、<span class=\"fr\" data-fr=\"quand\">quand</span>（什么时候）、<span class=\"fr\" data-fr=\"comment\">comment</span>（怎么）抄在卡片正面。名词连着冠词一起记，动词连最常用的搭配一起记，边写边出声读。","src":"vocab.html#t9","hint":"先读后抄，每个词出声读三遍","quiz":[{"id":"q-vocab-a1-5023","level":"A1","skill":"vocab","prompt":"« la gare » 的意思是？","options":["火车站","地铁站","机场"],"answer":"火车站","explain":"gare 是火车站；station de métro 是地铁站；aéroport 是机场。","source":"词汇 · 城市与交通"},{"ref":"bank:vocab:A1:城市与交通"}]},{"type":"vocab","title":"搭配与辨析：pourquoi / la gare","body":"把 <span class=\"fr\" data-fr=\"pourquoi\">pourquoi</span>（为什么）和 <span class=\"fr\" data-fr=\"la gare\">la gare</span>（火车站）放进同一个场景里各造一句，句子要主谓宾齐全。造完再把主语换成 il / elle 说一遍，检查冠词有没有跟着名词变。","src":"vocab.html#t9","hint":"两个词各写 2 个搭配","quiz":[{"id":"q-vocab-a1-5024","level":"A1","skill":"vocab","prompt":"「什么时候」用法语说是？","options":["quand","comment","pourquoi"],"answer":"quand","explain":"quand 问时间；comment 问方式；pourquoi 问原因。","source":"词汇 · 疑问词"},{"ref":"bank:vocab:A1:城市与交通"}]},{"type":"listen","title":"听音辨词：城市与交通","body":"打开 对话页的 d03、d05 篇，先盲听一遍，只做一件事：抓出含本周新词的句子并写下关键词。第二遍再对照法文原文，检查自己漏掉的是词还是联诵。像 <span class=\"fr\" data-fr=\"la station de métro\">la station de métro</span>（地铁站）这样的词如果没听出来，单独标出来。","src":"dialogue.html#d03","hint":"盲听一遍再对照原文","quiz":[{"ref":"bank:listening:A1:听力"}]},{"type":"speak","title":"口头造句：6 个新词进短句","body":"用今天抄的 6 个词各说一句，主语在 je / nous / on 之间换着用。参考例句 <span class=\"fr\" data-fr=\"Est-ce que vous habitez près de la gare ?\">Est-ce que vous habitez près de la gare ?</span>（您住在火车站附近吗？）。录 60 秒，回听时只挑两个问题：冠词有没有丢、动词有没有跟主语配合。","src":"exams.html#oral","hint":"录音 60 秒并回听","quiz":[{"ref":"bank:speaking:A1:口语"}]},{"type":"vocab","title":"日终自测：城市与交通 认词","body":"遮住中文，只看法语说意思：<span class=\"fr\" data-fr=\"où\">où</span> <span class=\"fr\" data-fr=\"quand\">quand</span> <span class=\"fr\" data-fr=\"comment\">comment</span> <span class=\"fr\" data-fr=\"pourquoi\">pourquoi</span> <span class=\"fr\" data-fr=\"la gare\">la gare</span> <span class=\"fr\" data-fr=\"la station de métro\">la station de métro</span>。说不出来的词立刻回到 vocab.html#t9 重记一遍，并在卡片角上打一个星号，星号词明天先复习。","src":"vocab.html#t9","hint":"先遮中文，再遮法语，两个方向各过一遍","quiz":[{"ref":"bank:vocab:A1:城市与交通"}]}]},{"day":2,"theme":"语法 · 疑问句三式","type":"grammar","steps":[{"type":"grammar","title":"语法点：疑问句三式","body":"【疑问句三式】疑问有三式：语调提问（Tu viens ?）、est-ce que 提问（Est-ce que tu viens ?）、倒装（Viens-tu ?）。问地点用 où，问时间用 quand，问方式用 comment，问原因用 pourquoi，问数量与价格用 combien。 例句：<span class=\"fr\" data-fr=\"Est-ce que vous habitez près de la gare ?\">Est-ce que vous habitez près de la gare ?</span>（您住在火车站附近吗？）；<span class=\"fr\" data-fr=\"Où est la station de métro, s'il vous plaît ?\">Où est la station de métro, s'il vous plaît ?</span>（请问地铁站在哪里？）。对照 grammar-a1a2.html#interrogation 的表格，把规则抄成自己的一句话。","src":"grammar-a1a2.html#interrogation","hint":"先读规则再看例句","quiz":[{"id":"q-gram-a1-5023","level":"A1","skill":"grammar","prompt":"« ___ est la banque ? »（问地点）","options":["Où","Quand","Comment"],"answer":"Où","explain":"问地点用 où；quand 问时间，comment 问方式。","source":"语法 · 疑问词"},{"ref":"bank:grammar:A1:疑问"}]},{"type":"grammar","title":"规则拆解与常见错误","body":"先合上书，凭记忆写出 疑问句三式 的规则和两个例句，再打开 grammar-a1a2.html#interrogation 对照补漏，用红笔标出回忆失败的地方。回忆失败比再读一遍更有价值，那正是考试时会出错的位置。","src":"grammar-a1a2.html#interrogation","hint":"合上书默写一遍规则","quiz":[{"id":"q-gram-a1-5024","level":"A1","skill":"grammar","prompt":"倒装式疑问 « Viens-tu ? » 的语域是？","options":["正式书面","口语随意","错误说法"],"answer":"正式书面","explain":"倒装式为正式语域；日常口语更常用语调式或 est-ce que 式。","source":"语法 · 疑问三式"},{"ref":"bank:grammar:A1:疑问"}]},{"type":"read","title":"在短文里找疑问句三式","body":"在 grammar-a1a2.html#interrogation 的例句和章末小测里挑 5 句，圈出所有属于「疑问句三式」的成分。读的时候先判断结构再理解意思，不要一开始就在脑子里翻译成中文。","src":"grammar-a1a2.html#interrogation","hint":"圈出全部相关成分","quiz":[{"ref":"bank:reading:A1:阅读"}]},{"type":"write","title":"限时仿写：8 句","body":"照 <span class=\"fr\" data-fr=\"Est-ce que vous habitez près de la gare ?\">Est-ce que vous habitez près de la gare ?</span>（您住在火车站附近吗？）的句型仿写 8 句，内容必须是你自己的真实信息。写完用三色笔检查：红色圈主语、蓝色圈动词、绿色圈配合成分，疑问句三式 的结构至少出现两次。","src":"exams.html#ecrit","hint":"限时 12 分钟，写完自查","quiz":[{"ref":"bank:writing:A1:写作"}]},{"type":"grammar","title":"语法点巩固：地点介词","body":"今天再回 grammar-a1a2.html#prep-lieu 看一遍 地点介词，把两个语法点的差别写成一行对照（触发条件 / 形式 / 常见错误各一列）。写不出来就说明还停留在「读得懂」而不是「用得出」。","src":"grammar-a1a2.html#prep-lieu","hint":"把两个语法点写成对照表","quiz":[{"ref":"bank:grammar:A1:疑问"}]}]},{"day":3,"theme":"精听 · 对话页的 d03、d05 篇","type":"listen","steps":[{"type":"listen","title":"精听（第一遍）：抓主旨","body":"打开 对话页的 d03、d05 篇，盲听第一遍，不暂停、不看文本。只听一个问题：这段话在谈什么？用中文写一句概括，再写下 3 个听清的词。","src":"dialogue.html#d03","hint":"不暂停、不看文本","quiz":[{"id":"q-list-a1-5015","level":"A1","skill":"listening","prompt":"听到 /ɛskə vu venez/ 对应哪一种疑问式？","options":["est-ce que 式","语调式","倒装式"],"answer":"est-ce que 式","explain":"/ɛskə/ 就是 est-ce que 的连读，其后保持陈述语序。","source":"语法 · 疑问三式"},{"ref":"bank:listening:A1:听力"}],"exam":"exam:listening:A2:车站广播"},{"type":"listen","title":"精听（第二遍）：听写关键句","body":"第二遍逐句暂停，听写 5 句含本周语法或新词的句子，写不出的地方标「?」。然后对照原文，把 ? 处按「词汇 / 联诵 / 语速」三类归档。本周的听力任务是：听对话页问路与约时间两篇，把听到的疑问句逐句写下来并标出用的是哪一式。","src":"dialogue.html#d03","hint":"逐句听写 5 句","quiz":[{"ref":"bank:listening:A1:听力"}]},{"type":"vocab","title":"听力词汇回收","body":"把听写中出现的生词与本周词表对照：<span class=\"fr\" data-fr=\"où\">où</span>（哪里）、<span class=\"fr\" data-fr=\"quand\">quand</span>（什么时候）、<span class=\"fr\" data-fr=\"comment\">comment</span>（怎么）。反复出现的词优先记，只出现一次又不影响理解的先放过，避免在细节里迷路。","src":"vocab.html#t9","hint":"生词与本周词表对照","quiz":[{"ref":"bank:vocab:A1:城市与交通"}]},{"type":"speak","title":"影子跟读 3 遍","body":"同一段材料做影子跟读（shadowing）：滞后原音半句跟读，重点模仿语调、连读与联诵，不要逐字念。跟完录 45 秒复述，不回看原文，卡住就用 <span class=\"fr\" data-fr=\"c'est-à-dire\">c'est-à-dire</span> 争取时间。","src":"exams.html#oral","hint":"滞后半句跟读，录 45 秒复述","quiz":[{"ref":"bank:speaking:A1:口语"}]},{"type":"listen","title":"精听（第三遍）：闭合听力","body":"第三遍只听不看，听完用法语说出 3 个关键信息，再写一句「疑问句三式 在这段里出现的位置」。仍听不懂的句子重复听 2 次，还不懂就记下来，第 7 天集中解决。","src":"dialogue.html#d03","hint":"只听不看，说出 3 个关键信息","quiz":[{"ref":"bank:listening:A1:听力"}]}]},{"day":4,"theme":"口语 · 疑问句三式与疑问词","type":"speak","steps":[{"type":"speak","title":"口语任务：本周主题陈述","body":"口语任务：就每个疑问词各问 3 个问题并自己回答，练到不用想句式就能开口。 开口前先想好「观点—理由—例子」三段，允许说得慢，但不许说到一半换主题。说完立刻自评一句：哪一段最流畅、哪一段最卡，卡住的地方就是下一次的训练重点。","src":"exams.html#oral","hint":"先说满 60 秒不停","quiz":[{"id":"q-speak-a1-5009","level":"A1","skill":"speaking","prompt":"「你住在哪里？」最常用的口语说法是？","options":["Tu habites où ?","Où habites-tu tu ?","Où tu habites est-ce ?"],"answer":"Tu habites où ?","explain":"口语里疑问词常留在句末，语序不变，句末读升调。","source":"语法 · 疑问三式"},{"ref":"bank:speaking:A1:口语"}]},{"type":"speak","title":"结构与衔接：先列提纲再开口","body":"把答案录在手机里，先说满 60 秒不停。说到一半忘词就先换一种说法把意思顶过去，流利度优先于用词精确。录完不要马上回听，隔十分钟再听一遍，判断会更客观。","src":"exams.html#oral","hint":"三个关键词 + 三段衔接词","quiz":[{"ref":"bank:speaking:A1:口语"}]},{"type":"listen","title":"听范例找差距","body":"听一段同主题范例（对话页的 d03、d05 篇），把自己的录音和范例逐项对比：语速、停顿位置、连接词的使用、疑问句三式 的正确形式。只记录 3 个今天就能改的点。","src":"dialogue.html#d03","hint":"只记 3 个可立刻改进的点","quiz":[{"ref":"bank:listening:A1:听力"}]},{"type":"vocab","title":"把新词用进嘴里","body":"把 <span class=\"fr\" data-fr=\"pourquoi\">pourquoi</span>（为什么）、<span class=\"fr\" data-fr=\"la gare\">la gare</span>（火车站）、<span class=\"fr\" data-fr=\"la station de métro\">la station de métro</span>（地铁站）轮流塞进刚才的答案里，每个词至少用一次。说不顺就说明这个词还没真正归属你，回到 vocab.html#t9 再看一遍例句。","src":"vocab.html#t9","hint":"每个新词至少用一次","quiz":[{"ref":"bank:vocab:A1:城市与交通"}]},{"type":"speak","title":"重录一遍并自评","body":"按前面记录的 3 个问题重录一次，目标是同样的内容用更少的停顿说完。回听时数一数填充词（euh、ben、voilà）出现几次，第 7 天把两次录音放在一起比较。","src":"exams.html#oral","hint":"数一数填充词次数","quiz":[{"ref":"bank:speaking:A1:口语"}]}]},{"day":5,"theme":"精读 · 疑问句三式与疑问词","type":"read","steps":[{"type":"read","title":"精读：本周阅读材料","body":"精读任务：读语法页疑问章节，区分口语的语调式与正式的倒装式的语域差别。 读第一遍只抓主旨，第二遍才处理细节，遇到生词先猜再查。读完先用一句话写出全文主旨，再回头处理细节，避免一开始就陷进生词里。","src":"exams.html#lecture","hint":"第一遍抓主旨，第二遍抓细节","quiz":[{"id":"q-read-a1-5013","level":"A1","skill":"reading","prompt":"« Combien coûte ce billet ? » 问的是？","options":["价格","时间","地点"],"answer":"价格","explain":"combien 问数量或价格，coûter 表示值多少钱。","source":"词汇 · 购物"},{"ref":"bank:reading:A1:阅读"}]},{"type":"read","title":"长句解构：先找主干","body":"挑文中 3 个超过 20 词的长句，先划出主谓宾，再把从句、分词、介词短语逐层挂上去。看到「疑问句三式」的结构就停下来确认触发条件。","src":"exams.html#lecture","hint":"拆 3 个长句，主干与修饰分栏","quiz":[{"ref":"bank:reading:A1:阅读"}]},{"type":"vocab","title":"阅读词汇：上下文猜词","body":"遇到生词先按词根、词尾和上下文猜一次再核对。本周词表里的 <span class=\"fr\" data-fr=\"où\">où</span>（哪里）、<span class=\"fr\" data-fr=\"quand\">quand</span>（什么时候）如果以别的形式出现，把那一整句抄进卡片。","src":"vocab.html#t9","hint":"先猜再查，把整句抄下来","quiz":[{"ref":"bank:vocab:A1:城市与交通"}]},{"type":"grammar","title":"语法在句子里的样子","body":"回到 grammar-a1a2.html#interrogation，对照文中出现的同类结构，确认书面语和口语的差别。摘抄 3 句可以直接套进写作的句子，标注它们的连接词和语式。","src":"grammar-a1a2.html#interrogation","hint":"摘 3 句能直接用的句子","quiz":[{"ref":"bank:grammar:A1:疑问"}]},{"type":"write","title":"100 词摘要","body":"不照抄原句，用 100 词概括文章并加一句自己的评价。写完统计三个数字：平均句长、连接词数量、「疑问句三式」出现次数，看看自己的书面语是不是只会并列短句。","src":"exams.html#ecrit","hint":"改写不照抄，统计三个数字","quiz":[{"ref":"bank:writing:A1:写作"}]}]},{"day":6,"theme":"写作 · 疑问句三式与疑问词","type":"write","steps":[{"type":"write","title":"写作任务：本周产出","body":"写作任务：为一段对话写 10 个问题，三种句式各用 3 次以上。 先列提纲再动笔，写完整篇留 5 分钟只做一遍通读检查。动笔前先确认题目要求写几段、用什么语域，避免写到一半推翻结构。","src":"exams.html#ecrit","hint":"先列提纲，再限时成文","quiz":[{"id":"q-writ-a1-5007","level":"A1","skill":"writing","prompt":"「为什么你不来？」正确写法是？","options":["Pourquoi tu ne viens pas ?","Pourquoi tu ne viens ?","Pourquoi pas tu viens ?"],"answer":"Pourquoi tu ne viens pas ?","explain":"pourquoi + 主语 + ne + 动词 + pas，否定词必须成对出现。","source":"语法 · 疑问与否定"},{"ref":"bank:writing:A1:写作"}]},{"type":"write","title":"提纲与逻辑链","body":"先写中文要点，再逐条译成法语，但译完必须回头改：把中文语序的句子打散重写，让动词和它的补语各就各位。改完把最生硬的 3 句抄到一边，作为下一稿的重点对象。","src":"exams.html#ecrit","hint":"三段式提纲，每段一个论点","quiz":[{"ref":"bank:writing:A1:写作"}]},{"type":"grammar","title":"写前语法自查清单","body":"打开 grammar-a1a2.html#interrogation，把本周语法点做成 3 条自查项写在旁边，例如「触发词有没有用对」「变位与配合是否一致」。写完通读只检查这 3 条，其余问题留到第二稿再处理。","src":"grammar-a1a2.html#interrogation","hint":"三条自查项，只查这三条","quiz":[{"ref":"bank:grammar:A1:疑问"}]},{"type":"read","title":"对照范文找可替换表达","body":"读考试页的范文，列出 10 处「我只会用简单说法、范文用了更地道说法」的对照，抄进表达本。重点看范文怎么用「疑问句三式」和连接词，对照表按「我的说法 / 范文说法 / 适用场景」三列记录。","src":"exams.html#redaction","hint":"抄 10 组对照表达","quiz":[{"ref":"bank:reading:A1:阅读"}]},{"type":"speak","title":"把写的文章讲出来","body":"脱稿把自己写的文章讲 2 分钟，允许简化但不许背稿。讲不顺的句子说明书面结构还没内化，回到文中改写一次，再讲一遍；同时把 <span class=\"fr\" data-fr=\"où\">où</span>（哪里）用进口语版本。","src":"exams.html#oral","hint":"脱稿讲 2 分钟，不背稿","quiz":[{"ref":"bank:speaking:A1:口语"}]}]},{"day":7,"theme":"复盘 · 疑问句三式与疑问词","type":"review","steps":[{"type":"review","title":"本周回顾：疑问句三式与疑问词","body":"这一周围绕「疑问句三式与疑问词」展开：语法主线是 疑问句三式，词汇主线是 城市与交通。先用 3 句话口头复述本周学了什么，再打开日历页第 7 周清单逐条核对里程碑。","src":"calendar.html#wk-7","hint":"先口头复述，再核对里程碑","quiz":[{"ref":"bank:vocab:A1:城市与交通"}]},{"type":"review","title":"语法复盘：疑问句三式","body":"从 grammar-a1a2.html#interrogation 的规则与例句里各抽 3 条：默写规则、翻译例句再对照，最后写下 2 个自己最可能犯的错。凡是默写时卡住的地方，就是下一周要带着继续练的问题。","src":"grammar-a1a2.html#interrogation","hint":"默写规则与例句，各抽 3 条","quiz":[{"ref":"bank:grammar:A1:疑问"}]},{"type":"review","title":"词汇自测：城市与交通","body":"遮住中文看 vocab.html#t9 的 6 个核心词：<span class=\"fr\" data-fr=\"où\">où</span> <span class=\"fr\" data-fr=\"quand\">quand</span> <span class=\"fr\" data-fr=\"comment\">comment</span> <span class=\"fr\" data-fr=\"pourquoi\">pourquoi</span> <span class=\"fr\" data-fr=\"la gare\">la gare</span> <span class=\"fr\" data-fr=\"la station de métro\">la station de métro</span>。能秒答的划掉，犹豫超过 3 秒的抄进错词本。本周目标是新词认词率不低于 85%。","src":"vocab.html#t9","hint":"遮中文秒答，犹豫即抄错词本","quiz":[{"id":"q-vocab-a1-5025","level":"A1","skill":"vocab","prompt":"« près de » 的意思是？","options":["在……附近","在……对面","在……后面"],"answer":"在……附近","explain":"près de 表示靠近；en face de 是对面；derrière 是后面。","source":"词汇 · 地点"},{"id":"q-vocab-a1-5026","level":"A1","skill":"vocab","prompt":"「地铁站」用法语说是？","options":["la station de métro","la gare de métro","le métro gare"],"answer":"la station de métro","explain":"地铁站是 la station de métro；la gare 一般指火车站。","source":"词汇 · 城市与交通"},{"ref":"bank:vocab:A1:城市与交通"}]},{"type":"review","title":"综合题（一）：听读理解","body":"先做下面的听读综合题，不查词、不回看材料，限时 5 分钟。做完再回材料定位每道题的证据句，把「没找到证据就选」的题目标出来——那是失分的主要来源。","src":"dialogue.html#d03","hint":"限时 5 分钟，做完回材料找证据","quiz":[{"id":"q-list-a1-5016","level":"A1","skill":"listening","prompt":"听到句末升调的 « Tu viens ? » 表示？","options":["疑问","命令","陈述"],"answer":"疑问","explain":"陈述句语序加句末升调，就是口语里的语调式疑问。","source":"语音 · 语调"},{"id":"q-read-a1-5014","level":"A1","skill":"reading","prompt":"« Quand part le train ? » 中 quand 问的是？","options":["时间","方式","原因"],"answer":"时间","explain":"quand 问时间；comment 问方式；pourquoi 问原因。","source":"词汇 · 疑问词"},{"ref":"bank:listening:A1:听力"}]},{"type":"review","title":"综合题（二）：语法与词汇","body":"这一组题检查 疑问句三式 与本周词汇的调用能力。每道题都问自己：错误选项错在哪里？能说出错因才算真的会，说不出来就回到 grammar-a1a2.html#interrogation 再核对一次。","src":"grammar-a1a2.html#prep-lieu","hint":"每题都说出错项错在哪","quiz":[{"id":"q-gram-a1-5025","level":"A1","skill":"grammar","prompt":"« Est-ce que tu as un plan ? » 属于哪一式？","options":["est-ce que 式","倒装式","语调式"],"answer":"est-ce que 式","explain":"句首出现 est-ce que 就是第二式，其后保持陈述语序。","source":"语法 · 疑问三式"},{"id":"q-gram-a1-5026","level":"A1","skill":"grammar","prompt":"« ___ allez-vous ? »（问方式）","options":["Comment","Quand","Où"],"answer":"Comment","explain":"问方式用 comment；倒装形式写作 comment allez-vous。","source":"语法 · 疑问词"},{"ref":"bank:grammar:A1:疑问"}]},{"type":"review","title":"输出任务与自评表","body":"完成一段 90 秒口述或 120 词短文，内容必须同时用上本周的 2 个词和 1 个语法结构。按「任务完成 / 连贯 / 词汇 / 语法 / 拼写」五项各打 1–5 分，低于 3 分的写进下周补漏清单。","src":"exams.html#oral","hint":"五项各打 1–5 分","quiz":[{"ref":"bank:writing:A1:写作"}]}]}]},{"week":8,"level":"A1","theme":"高频不规则动词与数字时间","days":[{"day":1,"theme":"词汇 · 数字、时间与度量","type":"vocab","steps":[{"type":"vocab","title":"主题词汇域：数字、时间与度量","body":"数字、时间与度量（Les nombres, le temps et les mesures）是这一周要反复见面的主题域。打开 vocab.html#t13，先看词表怎么分组，再把 <span class=\"fr\" data-fr=\"aller\">aller</span>（去）、<span class=\"fr\" data-fr=\"faire\">faire</span>（做）、<span class=\"fr\" data-fr=\"prendre\">prendre</span>（拿；乘坐）读三遍，然后遮住中文说意思。记不住的词单独建一张「顽固词表」。","src":"vocab.html#t13","hint":"先读后抄，每个词出声读三遍","quiz":[{"id":"q-vocab-a1-5027","level":"A1","skill":"vocab","prompt":"« prendre » 的意思是？","options":["拿；乘坐","来","想要"],"answer":"拿；乘坐","explain":"prendre 是拿、取，也用于 prendre le train（坐火车）；venir 是来；vouloir 是想要。","source":"词汇 · 高频动词"},{"ref":"bank:vocab:A1:数字、时间与度量"}]},{"type":"vocab","title":"搭配与辨析：venir / pouvoir","body":"<span class=\"fr\" data-fr=\"venir\">venir</span>（来）与 <span class=\"fr\" data-fr=\"pouvoir\">pouvoir</span>（能够）是本组最容易混的两个词。为每个词写 2 个搭配（一个名词搭配、一个动词搭配），读出来判断哪个更自然，拿不准的留到第 7 天复盘。","src":"vocab.html#t13","hint":"两个词各写 2 个搭配","quiz":[{"id":"q-vocab-a1-5028","level":"A1","skill":"vocab","prompt":"80 的法语写法是？","options":["quatre-vingts","quatre-vingt","huitante"],"answer":"quatre-vingts","explain":"80 写作 quatre-vingts，单独使用时 vingt 加 -s；后接其他数词时不加，如 quatre-vingt-un。","source":"词汇 · 数字"},{"ref":"bank:vocab:A1:数字、时间与度量"}]},{"type":"listen","title":"听音辨词：数字、时间与度量","body":"打开 对话页的 d11 篇，先盲听一遍，只做一件事：抓出含本周新词的句子并写下关键词。第二遍再对照法文原文，检查自己漏掉的是词还是联诵。像 <span class=\"fr\" data-fr=\"vouloir\">vouloir</span>（想要）这样的词如果没听出来，单独标出来。","src":"dialogue.html#d11","hint":"盲听一遍再对照原文","quiz":[{"ref":"bank:listening:A1:听力"}]},{"type":"speak","title":"口头造句：6 个新词进短句","body":"用今天抄的 6 个词各说一句，主语在 je / nous / on 之间换着用。参考例句 <span class=\"fr\" data-fr=\"Je vais au travail à huit heures.\">Je vais au travail à huit heures.</span>（我八点去上班。）。录 60 秒，回听时只挑两个问题：冠词有没有丢、动词有没有跟主语配合。","src":"exams.html#oral","hint":"录音 60 秒并回听","quiz":[{"ref":"bank:speaking:A1:口语"}]},{"type":"vocab","title":"日终自测：数字、时间与度量 认词","body":"遮住中文，只看法语说意思：<span class=\"fr\" data-fr=\"aller\">aller</span> <span class=\"fr\" data-fr=\"faire\">faire</span> <span class=\"fr\" data-fr=\"prendre\">prendre</span> <span class=\"fr\" data-fr=\"venir\">venir</span> <span class=\"fr\" data-fr=\"pouvoir\">pouvoir</span> <span class=\"fr\" data-fr=\"vouloir\">vouloir</span>。说不出来的词立刻回到 vocab.html#t13 重记一遍，并在卡片角上打一个星号，星号词明天先复习。","src":"vocab.html#t13","hint":"先遮中文，再遮法语，两个方向各过一遍","quiz":[{"ref":"bank:vocab:A1:数字、时间与度量"}]}]},{"day":2,"theme":"语法 · 常用不规则动词变位表","type":"grammar","steps":[{"type":"grammar","title":"语法点：常用不规则动词变位表","body":"【常用不规则动词变位表】aller, faire, prendre, venir, pouvoir, vouloir, devoir 是日常出现频率最高的不规则动词，现在时变位必须整体背下来。数字方面，70 读 soixante-dix、80 读 quatre-vingts、90 读 quatre-vingt-dix，是听写最容易出错的地方。 例句：<span class=\"fr\" data-fr=\"Je vais au travail à huit heures.\">Je vais au travail à huit heures.</span>（我八点去上班。）；<span class=\"fr\" data-fr=\"Nous prenons le train à soixante-dix euros.\">Nous prenons le train à soixante-dix euros.</span>（我们坐七十欧元的火车。）。对照 grammar-a1a2.html#pres-irreg 的表格，把规则抄成自己的一句话。","src":"grammar-a1a2.html#pres-irreg","hint":"先读规则再看例句","quiz":[{"id":"q-gram-a1-5027","level":"A1","skill":"grammar","prompt":"Nous ___ au cinéma ce soir.（aller）","options":["allons","allez","vont"],"answer":"allons","explain":"nous 对应 allons；allez 给 vous，vont 给 ils / elles。","source":"语法 · aller 现在时"},{"ref":"bank:grammar:A1:不规则"}]},{"type":"grammar","title":"规则拆解与常见错误","body":"对着 grammar-a1a2.html#pres-irreg 自查三件事：① 触发条件是什么；② 变位或配合落在哪个词尾；③ 有哪些例外要单独记。然后把 <span class=\"fr\" data-fr=\"Je vais au travail à huit heures.\">Je vais au travail à huit heures.</span>（我八点去上班。）拆到词，逐一说明每个成分为什么用这个形式。","src":"grammar-a1a2.html#pres-irreg","hint":"合上书默写一遍规则","quiz":[{"id":"q-gram-a1-5028","level":"A1","skill":"grammar","prompt":"Ils ___ le train.（prendre）","options":["prennent","prendons","prenez"],"answer":"prennent","explain":"ils 对应 prennent，词干双写 n 加 -ent；nous prenons 才是我们的形式。","source":"语法 · 不规则动词"},{"ref":"bank:grammar:A1:不规则"}]},{"type":"read","title":"在短文里找常用不规则动词变位表","body":"在 grammar-a1a2.html#pres-irreg 的例句和章末小测里挑 5 句，圈出所有属于「常用不规则动词变位表」的成分。读的时候先判断结构再理解意思，不要一开始就在脑子里翻译成中文。","src":"grammar-a1a2.html#pres-irreg","hint":"圈出全部相关成分","quiz":[{"ref":"bank:reading:A1:阅读"}]},{"type":"write","title":"限时仿写：8 句","body":"照 <span class=\"fr\" data-fr=\"Je vais au travail à huit heures.\">Je vais au travail à huit heures.</span>（我八点去上班。）的句型仿写 8 句，内容必须是你自己的真实信息。写完用三色笔检查：红色圈主语、蓝色圈动词、绿色圈配合成分，常用不规则动词变位表 的结构至少出现两次。","src":"exams.html#ecrit","hint":"限时 12 分钟，写完自查","quiz":[{"ref":"bank:writing:A1:写作"}]},{"type":"grammar","title":"语法点巩固：基数词 0–1000+","body":"今天再回 grammar-a1a2.html#num-card 看一遍 基数词 0–1000+，把两个语法点的差别写成一行对照（触发条件 / 形式 / 常见错误各一列）。写不出来就说明还停留在「读得懂」而不是「用得出」。","src":"grammar-a1a2.html#num-card","hint":"把两个语法点写成对照表","quiz":[{"ref":"bank:grammar:A1:不规则"}]}]},{"day":3,"theme":"精听 · 对话页的 d11 篇","type":"listen","steps":[{"type":"listen","title":"精听（第一遍）：抓主旨","body":"第一遍听的时候不要追求每个词都懂。对话页的 d11 篇 的材料先听三分钟，抓住说话人、场景和态度，其余细节留到第二遍。听之前先用 10 秒预测这段话会出现哪些本周词汇，带着预测去听，抓取效率会明显提高。","src":"dialogue.html#d11","hint":"不暂停、不看文本","quiz":[{"id":"q-list-a1-5017","level":"A1","skill":"listening","prompt":"听到 /swasɑ̃tdis/ 对应的数字是？","options":["70","60","77"],"answer":"70","explain":"soixante-dix 是 70；60 是 soixante；77 是 soixante-dix-sept。","source":"词汇 · 数字"},{"ref":"bank:listening:A1:听力"}],"exam":"exam:listening:A2:车站广播"},{"type":"listen","title":"精听（第二遍）：听写关键句","body":"第二遍逐句暂停，听写 5 句含本周语法或新词的句子，写不出的地方标「?」。然后对照原文，把 ? 处按「词汇 / 联诵 / 语速」三类归档。本周的听力任务是：听数字与价格的音频，做 20 组听写，重点抓 60 / 70 / 80 / 90 的读法差异。","src":"dialogue.html#d11","hint":"逐句听写 5 句","quiz":[{"ref":"bank:listening:A1:听力"}]},{"type":"vocab","title":"听力词汇回收","body":"把听写中出现的生词与本周词表对照：<span class=\"fr\" data-fr=\"aller\">aller</span>（去）、<span class=\"fr\" data-fr=\"faire\">faire</span>（做）、<span class=\"fr\" data-fr=\"prendre\">prendre</span>（拿；乘坐）。反复出现的词优先记，只出现一次又不影响理解的先放过，避免在细节里迷路。","src":"vocab.html#t13","hint":"生词与本周词表对照","quiz":[{"ref":"bank:vocab:A1:数字、时间与度量"}]},{"type":"speak","title":"影子跟读 3 遍","body":"同一段材料做影子跟读（shadowing）：滞后原音半句跟读，重点模仿语调、连读与联诵，不要逐字念。跟完录 45 秒复述，不回看原文，卡住就用 <span class=\"fr\" data-fr=\"c'est-à-dire\">c'est-à-dire</span> 争取时间。","src":"exams.html#oral","hint":"滞后半句跟读，录 45 秒复述","quiz":[{"ref":"bank:speaking:A1:口语"}]},{"type":"listen","title":"精听（第三遍）：闭合听力","body":"第三遍只听不看，听完用法语说出 3 个关键信息，再写一句「常用不规则动词变位表 在这段里出现的位置」。仍听不懂的句子重复听 2 次，还不懂就记下来，第 7 天集中解决。","src":"dialogue.html#d11","hint":"只听不看，说出 3 个关键信息","quiz":[{"ref":"bank:listening:A1:听力"}]}]},{"day":4,"theme":"口语 · 高频不规则动词与数字时间","type":"speak","steps":[{"type":"speak","title":"口语任务：本周主题陈述","body":"口语任务：说出现在时间、约定的见面时间、三个商品价格，数字不能含混。 开口前先想好「观点—理由—例子」三段，允许说得慢，但不许说到一半换主题。说完立刻自评一句：哪一段最流畅、哪一段最卡，卡住的地方就是下一次的训练重点。","src":"exams.html#oral","hint":"先说满 60 秒不停","quiz":[{"id":"q-speak-a1-5010","level":"A1","skill":"speaking","prompt":"「我想要一杯咖啡」最得体的说法是？","options":["Je voudrais un café.","Je voulons un café.","Je veux un café voulons."],"answer":"Je voudrais un café.","explain":"点单用条件式 Je voudrais，比 Je veux 更礼貌；vouloir 的 nous 形式是 voulons，与 je 不搭。","source":"语法 · 礼貌表达"},{"ref":"bank:speaking:A1:口语"}]},{"type":"speak","title":"结构与衔接：先列提纲再开口","body":"用 30 秒写 3 个关键词当提纲，再用 <span class=\"fr\" data-fr=\"d'abord\">d'abord</span> / <span class=\"fr\" data-fr=\"ensuite\">ensuite</span> / <span class=\"fr\" data-fr=\"enfin\">enfin</span> 把三段串起来。卡壳时用 <span class=\"fr\" data-fr=\"c'est-à-dire\">c'est-à-dire</span> 或 <span class=\"fr\" data-fr=\"disons que…\">disons que…</span> 争取时间，不要用中文思考再翻译。","src":"exams.html#oral","hint":"三个关键词 + 三段衔接词","quiz":[{"ref":"bank:speaking:A1:口语"}]},{"type":"listen","title":"听范例找差距","body":"听一段同主题范例（对话页的 d11 篇），把自己的录音和范例逐项对比：语速、停顿位置、连接词的使用、常用不规则动词变位表 的正确形式。只记录 3 个今天就能改的点。","src":"dialogue.html#d11","hint":"只记 3 个可立刻改进的点","quiz":[{"ref":"bank:listening:A1:听力"}]},{"type":"vocab","title":"把新词用进嘴里","body":"把 <span class=\"fr\" data-fr=\"venir\">venir</span>（来）、<span class=\"fr\" data-fr=\"pouvoir\">pouvoir</span>（能够）、<span class=\"fr\" data-fr=\"vouloir\">vouloir</span>（想要）轮流塞进刚才的答案里，每个词至少用一次。说不顺就说明这个词还没真正归属你，回到 vocab.html#t13 再看一遍例句。","src":"vocab.html#t13","hint":"每个新词至少用一次","quiz":[{"ref":"bank:vocab:A1:数字、时间与度量"}]},{"type":"speak","title":"重录一遍并自评","body":"按前面记录的 3 个问题重录一次，目标是同样的内容用更少的停顿说完。回听时数一数填充词（euh、ben、voilà）出现几次，第 7 天把两次录音放在一起比较。","src":"exams.html#oral","hint":"数一数填充词次数","quiz":[{"ref":"bank:speaking:A1:口语"}]}]},{"day":5,"theme":"精读 · 高频不规则动词与数字时间","type":"read","steps":[{"type":"read","title":"精读：本周阅读材料","body":"精读任务：读语法页不规则动词变位表，把 7 个动词按词干分组。 读第一遍只抓主旨，第二遍才处理细节，遇到生词先猜再查。读完先用一句话写出全文主旨，再回头处理细节，避免一开始就陷进生词里。","src":"exams.html#lecture","hint":"第一遍抓主旨，第二遍抓细节","quiz":[{"id":"q-read-a1-5015","level":"A1","skill":"reading","prompt":"« Je peux venir demain. » 中 peux 的原形是？","options":["pouvoir","prendre","devoir"],"answer":"pouvoir","explain":"peux 是 pouvoir 的第一人称单数形式；devoir 的对应形式是 dois。","source":"语法 · 不规则动词"},{"ref":"bank:reading:A1:阅读"}]},{"type":"read","title":"长句解构：先找主干","body":"把长句按「主干 + 修饰」两栏抄写：左栏只留主谓宾，右栏按顺序列出从句与补语。拆完再合起来读一遍，语序感会明显变好。判断不出从句类型时，先整段框起来，读完上下文再回来标注。","src":"exams.html#lecture","hint":"拆 3 个长句，主干与修饰分栏","quiz":[{"ref":"bank:reading:A1:阅读"}]},{"type":"vocab","title":"阅读词汇：上下文猜词","body":"遇到生词先按词根、词尾和上下文猜一次再核对。本周词表里的 <span class=\"fr\" data-fr=\"aller\">aller</span>（去）、<span class=\"fr\" data-fr=\"faire\">faire</span>（做）如果以别的形式出现，把那一整句抄进卡片。","src":"vocab.html#t13","hint":"先猜再查，把整句抄下来","quiz":[{"ref":"bank:vocab:A1:数字、时间与度量"}]},{"type":"grammar","title":"语法在句子里的样子","body":"回到 grammar-a1a2.html#pres-irreg，对照文中出现的同类结构，确认书面语和口语的差别。摘抄 3 句可以直接套进写作的句子，标注它们的连接词和语式。","src":"grammar-a1a2.html#pres-irreg","hint":"摘 3 句能直接用的句子","quiz":[{"ref":"bank:grammar:A1:不规则"}]},{"type":"write","title":"100 词摘要","body":"不照抄原句，用 100 词概括文章并加一句自己的评价。写完统计三个数字：平均句长、连接词数量、「常用不规则动词变位表」出现次数，看看自己的书面语是不是只会并列短句。","src":"exams.html#ecrit","hint":"改写不照抄，统计三个数字","quiz":[{"ref":"bank:writing:A1:写作"}]}]},{"day":6,"theme":"写作 · 高频不规则动词与数字时间","type":"write","steps":[{"type":"write","title":"写作任务：本周产出","body":"写作任务：限时 10 分钟默写 7 个不规则动词的现在时变位，写完立刻对照修改。 先列提纲再动笔，写完整篇留 5 分钟只做一遍通读检查。动笔前先确认题目要求写几段、用什么语域，避免写到一半推翻结构。","src":"exams.html#ecrit","hint":"先列提纲，再限时成文","quiz":[{"id":"q-writ-a1-5008","level":"A1","skill":"writing","prompt":"「我八点去上班」的正确写法是？","options":["Je vais au travail à huit heures.","Je vais à travail au huit heures.","Je va au travail à huit heure."],"answer":"Je vais au travail à huit heures.","explain":"à + le 缩合成 au；je 对应 vais；数字后 heure 要变复数 heures。","source":"语法 · 缩合冠词与变位"},{"ref":"bank:writing:A1:写作"}]},{"type":"write","title":"提纲与逻辑链","body":"动笔前把提纲写成三段式：每段一个论点，每个论点配一个具体例子。检查连接词是否多样，别整段只用 et 和 mais。提纲写完后放一分钟再看一遍，如果一句话就能说清每段的作用，结构就算过关。","src":"exams.html#ecrit","hint":"三段式提纲，每段一个论点","quiz":[{"ref":"bank:writing:A1:写作"}]},{"type":"grammar","title":"写前语法自查清单","body":"打开 grammar-a1a2.html#pres-irreg，把本周语法点做成 3 条自查项写在旁边，例如「触发词有没有用对」「变位与配合是否一致」。写完通读只检查这 3 条，其余问题留到第二稿再处理。","src":"grammar-a1a2.html#pres-irreg","hint":"三条自查项，只查这三条","quiz":[{"ref":"bank:grammar:A1:不规则"}]},{"type":"read","title":"对照范文找可替换表达","body":"读考试页的范文，列出 10 处「我只会用简单说法、范文用了更地道说法」的对照，抄进表达本。重点看范文怎么用「常用不规则动词变位表」和连接词，对照表按「我的说法 / 范文说法 / 适用场景」三列记录。","src":"exams.html#redaction","hint":"抄 10 组对照表达","quiz":[{"ref":"bank:reading:A1:阅读"}]},{"type":"speak","title":"把写的文章讲出来","body":"脱稿把自己写的文章讲 2 分钟，允许简化但不许背稿。讲不顺的句子说明书面结构还没内化，回到文中改写一次，再讲一遍；同时把 <span class=\"fr\" data-fr=\"aller\">aller</span>（去）用进口语版本。","src":"exams.html#oral","hint":"脱稿讲 2 分钟，不背稿","quiz":[{"ref":"bank:speaking:A1:口语"}]}]},{"day":7,"theme":"复盘 · 高频不规则动词与数字时间","type":"review","steps":[{"type":"review","title":"本周回顾：高频不规则动词与数字时间","body":"这一周围绕「高频不规则动词与数字时间」展开：语法主线是 常用不规则动词变位表，词汇主线是 数字、时间与度量。先用 3 句话口头复述本周学了什么，再打开日历页第 8 周清单逐条核对里程碑。","src":"calendar.html#wk-8","hint":"先口头复述，再核对里程碑","quiz":[{"ref":"bank:vocab:A1:数字、时间与度量"}]},{"type":"review","title":"语法复盘：常用不规则动词变位表","body":"从 grammar-a1a2.html#pres-irreg 的规则与例句里各抽 3 条：默写规则、翻译例句再对照，最后写下 2 个自己最可能犯的错。凡是默写时卡住的地方，就是下一周要带着继续练的问题。","src":"grammar-a1a2.html#pres-irreg","hint":"默写规则与例句，各抽 3 条","quiz":[{"ref":"bank:grammar:A1:不规则"}]},{"type":"review","title":"词汇自测：数字、时间与度量","body":"遮住中文看 vocab.html#t13 的 6 个核心词：<span class=\"fr\" data-fr=\"aller\">aller</span> <span class=\"fr\" data-fr=\"faire\">faire</span> <span class=\"fr\" data-fr=\"prendre\">prendre</span> <span class=\"fr\" data-fr=\"venir\">venir</span> <span class=\"fr\" data-fr=\"pouvoir\">pouvoir</span> <span class=\"fr\" data-fr=\"vouloir\">vouloir</span>。能秒答的划掉，犹豫超过 3 秒的抄进错词本。本周目标是新词认词率不低于 85%。","src":"vocab.html#t13","hint":"遮中文秒答，犹豫即抄错词本","quiz":[{"id":"q-vocab-a1-5029","level":"A1","skill":"vocab","prompt":"« devoir » 的意思是？","options":["应该；必须","能够","想要"],"answer":"应该；必须","explain":"devoir 表示应该、必须（je dois）；pouvoir 是能够；vouloir 是想要。","source":"词汇 · 高频动词"},{"id":"q-vocab-a1-5030","level":"A1","skill":"vocab","prompt":"90 的法语写法是？","options":["quatre-vingt-dix","nonante","quatre-vingts-dix"],"answer":"quatre-vingt-dix","explain":"90 是 quatre-vingt-dix，中间的 vingt 不加 -s；nonante 是比利时与瑞士用法。","source":"词汇 · 数字"},{"ref":"bank:vocab:A1:数字、时间与度量"}]},{"type":"review","title":"综合题（一）：听读理解","body":"先做下面的听读综合题，不查词、不回看材料，限时 5 分钟。做完再回材料定位每道题的证据句，把「没找到证据就选」的题目标出来——那是失分的主要来源。","src":"dialogue.html#d11","hint":"限时 5 分钟，做完回材料找证据","quiz":[{"id":"q-list-a1-5018","level":"A1","skill":"listening","prompt":"听到 /ilvjɛ̃/ 时最可能是？","options":["Il vient.","Ils viennent.","Il va venir."],"answer":"Il vient.","explain":"单数 il vient 读 /ilvjɛ̃/，词末是鼻化元音；ils viennent 读 /ilvjɛn/，鼻化消失，这是分辨关键。","source":"语音 · 不规则动词读音"},{"id":"q-read-a1-5016","level":"A1","skill":"reading","prompt":"« Nous faisons nos devoirs. » 中 faisons 的原形是？","options":["faire","finir","falloir"],"answer":"faire","explain":"faisons 是 faire 的 nous 形式，读 /fəzɔ̃/；falloir 只有 il faut 一种形式。","source":"语法 · 不规则动词"},{"ref":"bank:listening:A1:听力"}]},{"type":"review","title":"综合题（二）：语法与词汇","body":"这一组题检查 常用不规则动词变位表 与本周词汇的调用能力。每道题都问自己：错误选项错在哪里？能说出错因才算真的会，说不出来就回到 grammar-a1a2.html#pres-irreg 再核对一次。","src":"grammar-a1a2.html#num-card","hint":"每题都说出错项错在哪","quiz":[{"id":"q-gram-a1-5029","level":"A1","skill":"grammar","prompt":"« Vous ___ partir maintenant ? »（pouvoir）","options":["pouvez","pouve","peuvent"],"answer":"pouvez","explain":"vous 对应 pouvez；peuvent 给 ils / elles；pouve 不是合法形式。","source":"语法 · 不规则动词"},{"id":"q-gram-a1-5030","level":"A1","skill":"grammar","prompt":"« Elles ___ de Paris. »（venir）","options":["viennent","viens","venons"],"answer":"viennent","explain":"elles 对应 viennent，词干 vienn- 加 -ent；viens 给 tu 和 je。","source":"语法 · 不规则动词"},{"ref":"bank:grammar:A1:不规则"}]},{"type":"review","title":"输出任务与自评表","body":"完成一段 90 秒口述或 120 词短文，内容必须同时用上本周的 2 个词和 1 个语法结构。按「任务完成 / 连贯 / 词汇 / 语法 / 拼写」五项各打 1–5 分，低于 3 分的写进下周补漏清单。","src":"exams.html#oral","hint":"五项各打 1–5 分","quiz":[{"ref":"bank:writing:A1:写作"}]}]}]},{"week":9,"level":"A1","theme":"部分冠词、食物与点单场景","days":[{"day":1,"theme":"词汇 · 食物与餐饮","type":"vocab","steps":[{"type":"vocab","title":"主题词汇域：食物与餐饮","body":"本周词汇主战场是食物与餐饮（Les aliments et la restauration）。先到 vocab.html#t6 把词表扫一遍，把 <span class=\"fr\" data-fr=\"le pain\">le pain</span>（面包）、<span class=\"fr\" data-fr=\"l'eau\">l'eau</span>（水）、<span class=\"fr\" data-fr=\"le fromage\">le fromage</span>（奶酪）抄在卡片正面。名词连着冠词一起记，动词连最常用的搭配一起记，边写边出声读。","src":"vocab.html#t6","hint":"先读后抄，每个词出声读三遍","quiz":[{"id":"q-vocab-a1-5031","level":"A1","skill":"vocab","prompt":"« l'addition » 的意思是？","options":["账单","菜单","小费"],"answer":"账单","explain":"l'addition 是账单，买单时说 L'addition, s'il vous plaît；la carte 才是菜单。","source":"词汇 · 餐饮"},{"ref":"bank:vocab:A1:食物与餐饮"}]},{"type":"vocab","title":"搭配与辨析：la viande / une bouteille de vin","body":"把 <span class=\"fr\" data-fr=\"la viande\">la viande</span>（肉）和 <span class=\"fr\" data-fr=\"une bouteille de vin\">une bouteille de vin</span>（一瓶葡萄酒）放进同一个场景里各造一句，句子要主谓宾齐全。造完再把主语换成 il / elle 说一遍，检查冠词有没有跟着名词变。","src":"vocab.html#t6","hint":"两个词各写 2 个搭配","quiz":[{"id":"q-vocab-a1-5032","level":"A1","skill":"vocab","prompt":"「奶酪」用法语说是？","options":["le fromage","le poisson","le gâteau"],"answer":"le fromage","explain":"fromage 是奶酪；poisson 是鱼；gâteau 是蛋糕。","source":"词汇 · 食物"},{"ref":"bank:vocab:A1:食物与餐饮"}]},{"type":"listen","title":"听音辨词：食物与餐饮","body":"打开 对话页的 d06、d04 篇，先盲听一遍，只做一件事：抓出含本周新词的句子并写下关键词。第二遍再对照法文原文，检查自己漏掉的是词还是联诵。像 <span class=\"fr\" data-fr=\"l'addition\">l'addition</span>（账单）这样的词如果没听出来，单独标出来。","src":"dialogue.html#d06","hint":"盲听一遍再对照原文","quiz":[{"ref":"bank:listening:A1:听力"}]},{"type":"speak","title":"口头造句：6 个新词进短句","body":"用今天抄的 6 个词各说一句，主语在 je / nous / on 之间换着用。参考例句 <span class=\"fr\" data-fr=\"Je voudrais du pain et de l'eau, s'il vous plaît.\">Je voudrais du pain et de l'eau, s'il vous plaît.</span>（我想要一些面包和水，谢谢。）。录 60 秒，回听时只挑两个问题：冠词有没有丢、动词有没有跟主语配合。","src":"exams.html#oral","hint":"录音 60 秒并回听","quiz":[{"ref":"bank:speaking:A1:口语"}]},{"type":"vocab","title":"日终自测：食物与餐饮 认词","body":"遮住中文，只看法语说意思：<span class=\"fr\" data-fr=\"le pain\">le pain</span> <span class=\"fr\" data-fr=\"l'eau\">l'eau</span> <span class=\"fr\" data-fr=\"le fromage\">le fromage</span> <span class=\"fr\" data-fr=\"la viande\">la viande</span> <span class=\"fr\" data-fr=\"une bouteille de vin\">une bouteille de vin</span> <span class=\"fr\" data-fr=\"l'addition\">l'addition</span>。说不出来的词立刻回到 vocab.html#t6 重记一遍，并在卡片角上打一个星号，星号词明天先复习。","src":"vocab.html#t6","hint":"先遮中文，再遮法语，两个方向各过一遍","quiz":[{"ref":"bank:vocab:A1:食物与餐饮"}]}]},{"day":2,"theme":"语法 · 部分冠词","type":"grammar","steps":[{"type":"grammar","title":"语法点：部分冠词","body":"【部分冠词】部分冠词 du / de la / de l' / des 表示不确定的一部分，多用于吃喝与不可数名词；否定句中一律变成 de：Je bois du café 变成 Je ne bois pas de café。量词结构用 un kilo de、une bouteille de，de 后面不加冠词。 例句：<span class=\"fr\" data-fr=\"Je voudrais du pain et de l'eau, s'il vous plaît.\">Je voudrais du pain et de l'eau, s'il vous plaît.</span>（我想要一些面包和水，谢谢。）；<span class=\"fr\" data-fr=\"Il n'y a plus de lait dans le frigo.\">Il n'y a plus de lait dans le frigo.</span>（冰箱里没有牛奶了。）。对照 grammar-a1a2.html#art-part 的表格，把规则抄成自己的一句话。","src":"grammar-a1a2.html#art-part","hint":"先读规则再看例句","quiz":[{"id":"q-gram-a1-5031","level":"A1","skill":"grammar","prompt":"Je voudrais ___ café, s'il vous plaît.","options":["du","le","un"],"answer":"du","explain":"不可数的 café 用部分冠词 du；un café 指「一杯咖啡」，与「来点咖啡」的语境不同。","source":"语法 · 部分冠词"},{"ref":"bank:grammar:A1:部分冠词"}]},{"type":"grammar","title":"规则拆解与常见错误","body":"先合上书，凭记忆写出 部分冠词 的规则和两个例句，再打开 grammar-a1a2.html#art-part 对照补漏，用红笔标出回忆失败的地方。回忆失败比再读一遍更有价值，那正是考试时会出错的位置。","src":"grammar-a1a2.html#art-part","hint":"合上书默写一遍规则","quiz":[{"id":"q-gram-a1-5032","level":"A1","skill":"grammar","prompt":"否定句 « Je ne bois pas ___ café. » 应填？","options":["de","du","le"],"answer":"de","explain":"部分冠词在否定句中一律变成 de：pas de café。","source":"语法 · 部分冠词与否定"},{"ref":"bank:grammar:A1:部分冠词"}]},{"type":"read","title":"在短文里找部分冠词","body":"在 grammar-a1a2.html#art-part 的例句和章末小测里挑 5 句，圈出所有属于「部分冠词」的成分。读的时候先判断结构再理解意思，不要一开始就在脑子里翻译成中文。","src":"grammar-a1a2.html#art-part","hint":"圈出全部相关成分","quiz":[{"ref":"bank:reading:A1:阅读"}]},{"type":"write","title":"限时仿写：8 句","body":"照 <span class=\"fr\" data-fr=\"Je voudrais du pain et de l'eau, s'il vous plaît.\">Je voudrais du pain et de l'eau, s'il vous plaît.</span>（我想要一些面包和水，谢谢。）的句型仿写 8 句，内容必须是你自己的真实信息。写完用三色笔检查：红色圈主语、蓝色圈动词、绿色圈配合成分，部分冠词 的结构至少出现两次。","src":"exams.html#ecrit","hint":"限时 12 分钟，写完自查","quiz":[{"ref":"bank:writing:A1:写作"}]},{"type":"grammar","title":"语法点巩固：数量副词与 de","body":"今天再回 grammar-a1a2.html#quant-adv 看一遍 数量副词与 de，把两个语法点的差别写成一行对照（触发条件 / 形式 / 常见错误各一列）。写不出来就说明还停留在「读得懂」而不是「用得出」。","src":"grammar-a1a2.html#quant-adv","hint":"把两个语法点写成对照表","quiz":[{"ref":"bank:grammar:A1:部分冠词"}]}]},{"day":3,"theme":"精听 · 对话页的 d06、d04 篇","type":"listen","steps":[{"type":"listen","title":"精听（第一遍）：抓主旨","body":"打开 对话页的 d06、d04 篇，盲听第一遍，不暂停、不看文本。只听一个问题：这段话在谈什么？用中文写一句概括，再写下 3 个听清的词。","src":"dialogue.html#d06","hint":"不暂停、不看文本","quiz":[{"id":"q-list-a1-5019","level":"A1","skill":"listening","prompt":"餐厅里 « L'addition, s'il vous plaît. » 的意思是？","options":["请结账","请点菜","请加水"],"answer":"请结账","explain":"l'addition 是账单，这句话是结账的标准说法。","source":"词汇 · 餐饮"},{"ref":"bank:listening:A1:听力"}],"exam":"exam:listening:A2:车站广播"},{"type":"listen","title":"精听（第二遍）：听写关键句","body":"第二遍逐句暂停，听写 5 句含本周语法或新词的句子，写不出的地方标「?」。然后对照原文，把 ? 处按「词汇 / 联诵 / 语速」三类归档。本周的听力任务是：听餐厅点单对话，写下点单句型与出现的部分冠词。","src":"dialogue.html#d06","hint":"逐句听写 5 句","quiz":[{"ref":"bank:listening:A1:听力"}]},{"type":"vocab","title":"听力词汇回收","body":"把听写中出现的生词与本周词表对照：<span class=\"fr\" data-fr=\"le pain\">le pain</span>（面包）、<span class=\"fr\" data-fr=\"l'eau\">l'eau</span>（水）、<span class=\"fr\" data-fr=\"le fromage\">le fromage</span>（奶酪）。反复出现的词优先记，只出现一次又不影响理解的先放过，避免在细节里迷路。","src":"vocab.html#t6","hint":"生词与本周词表对照","quiz":[{"ref":"bank:vocab:A1:食物与餐饮"}]},{"type":"speak","title":"影子跟读 3 遍","body":"同一段材料做影子跟读（shadowing）：滞后原音半句跟读，重点模仿语调、连读与联诵，不要逐字念。跟完录 45 秒复述，不回看原文，卡住就用 <span class=\"fr\" data-fr=\"c'est-à-dire\">c'est-à-dire</span> 争取时间。","src":"exams.html#oral","hint":"滞后半句跟读，录 45 秒复述","quiz":[{"ref":"bank:speaking:A1:口语"}]},{"type":"listen","title":"精听（第三遍）：闭合听力","body":"第三遍只听不看，听完用法语说出 3 个关键信息，再写一句「部分冠词 在这段里出现的位置」。仍听不懂的句子重复听 2 次，还不懂就记下来，第 7 天集中解决。","src":"dialogue.html#d06","hint":"只听不看，说出 3 个关键信息","quiz":[{"ref":"bank:listening:A1:听力"}]}]},{"day":4,"theme":"口语 · 部分冠词、食物与点单场景","type":"speak","steps":[{"type":"speak","title":"口语任务：本周主题陈述","body":"口语任务：角色扮演「两人在餐厅点菜」，从入座到买单走完整流程，必须用上 du / de la / de l'。 开口前先想好「观点—理由—例子」三段，允许说得慢，但不许说到一半换主题。说完立刻自评一句：哪一段最流畅、哪一段最卡，卡住的地方就是下一次的训练重点。","src":"exams.html#oral","hint":"先说满 60 秒不停","quiz":[{"id":"q-speak-a1-5011","level":"A1","skill":"speaking","prompt":"点一份牛排时最得体的说法是？","options":["Je voudrais un steak, s'il vous plaît.","Je veux steak.","Donne-moi un steak."],"answer":"Je voudrais un steak, s'il vous plaît.","explain":"Je voudrais 加 s'il vous plaît 是最常用的礼貌点单结构；命令式 Donne-moi 显得生硬。","source":"语法 · 礼貌表达"},{"ref":"bank:speaking:A1:口语"}]},{"type":"speak","title":"结构与衔接：先列提纲再开口","body":"把答案录在手机里，先说满 60 秒不停。说到一半忘词就先换一种说法把意思顶过去，流利度优先于用词精确。录完不要马上回听，隔十分钟再听一遍，判断会更客观。","src":"exams.html#oral","hint":"三个关键词 + 三段衔接词","quiz":[{"ref":"bank:speaking:A1:口语"}]},{"type":"listen","title":"听范例找差距","body":"听一段同主题范例（对话页的 d06、d04 篇），把自己的录音和范例逐项对比：语速、停顿位置、连接词的使用、部分冠词 的正确形式。只记录 3 个今天就能改的点。","src":"dialogue.html#d06","hint":"只记 3 个可立刻改进的点","quiz":[{"ref":"bank:listening:A1:听力"}]},{"type":"vocab","title":"把新词用进嘴里","body":"把 <span class=\"fr\" data-fr=\"la viande\">la viande</span>（肉）、<span class=\"fr\" data-fr=\"une bouteille de vin\">une bouteille de vin</span>（一瓶葡萄酒）、<span class=\"fr\" data-fr=\"l'addition\">l'addition</span>（账单）轮流塞进刚才的答案里，每个词至少用一次。说不顺就说明这个词还没真正归属你，回到 vocab.html#t6 再看一遍例句。","src":"vocab.html#t6","hint":"每个新词至少用一次","quiz":[{"ref":"bank:vocab:A1:食物与餐饮"}]},{"type":"speak","title":"重录一遍并自评","body":"按前面记录的 3 个问题重录一次，目标是同样的内容用更少的停顿说完。回听时数一数填充词（euh、ben、voilà）出现几次，第 7 天把两次录音放在一起比较。","src":"exams.html#oral","hint":"数一数填充词次数","quiz":[{"ref":"bank:speaking:A1:口语"}]}]},{"day":5,"theme":"精读 · 部分冠词、食物与点单场景","type":"read","steps":[{"type":"read","title":"精读：本周阅读材料","body":"精读任务：读对话页 A1 餐厅与食品购物篇，圈出所有部分冠词。 读第一遍只抓主旨，第二遍才处理细节，遇到生词先猜再查。读完先用一句话写出全文主旨，再回头处理细节，避免一开始就陷进生词里。","src":"exams.html#lecture","hint":"第一遍抓主旨，第二遍抓细节","quiz":[{"id":"q-read-a1-5017","level":"A1","skill":"reading","prompt":"« un kilo de tomates » 中 de 后面为什么没有冠词？","options":["量词后直接接名词","tomates 不可数","这是固定错误"],"answer":"量词后直接接名词","explain":"数量词（kilo、bouteille、verre 等）+ de + 名词，名词前不加冠词。","source":"语法 · 数量表达"},{"ref":"bank:reading:A1:阅读"}]},{"type":"read","title":"长句解构：先找主干","body":"挑文中 3 个超过 20 词的长句，先划出主谓宾，再把从句、分词、介词短语逐层挂上去。看到「部分冠词」的结构就停下来确认触发条件。","src":"exams.html#lecture","hint":"拆 3 个长句，主干与修饰分栏","quiz":[{"ref":"bank:reading:A1:阅读"}]},{"type":"vocab","title":"阅读词汇：上下文猜词","body":"遇到生词先按词根、词尾和上下文猜一次再核对。本周词表里的 <span class=\"fr\" data-fr=\"le pain\">le pain</span>（面包）、<span class=\"fr\" data-fr=\"l'eau\">l'eau</span>（水）如果以别的形式出现，把那一整句抄进卡片。","src":"vocab.html#t6","hint":"先猜再查，把整句抄下来","quiz":[{"ref":"bank:vocab:A1:食物与餐饮"}]},{"type":"grammar","title":"语法在句子里的样子","body":"回到 grammar-a1a2.html#art-part，对照文中出现的同类结构，确认书面语和口语的差别。摘抄 3 句可以直接套进写作的句子，标注它们的连接词和语式。","src":"grammar-a1a2.html#art-part","hint":"摘 3 句能直接用的句子","quiz":[{"ref":"bank:grammar:A1:部分冠词"}]},{"type":"write","title":"100 词摘要","body":"不照抄原句，用 100 词概括文章并加一句自己的评价。写完统计三个数字：平均句长、连接词数量、「部分冠词」出现次数，看看自己的书面语是不是只会并列短句。","src":"exams.html#ecrit","hint":"改写不照抄，统计三个数字","quiz":[{"ref":"bank:writing:A1:写作"}]}]},{"day":6,"theme":"写作 · 部分冠词、食物与点单场景","type":"write","steps":[{"type":"write","title":"写作任务：本周产出","body":"写作任务：写一份 20 项的购物清单（含数量）和一段点菜记录，注意量词后的 de。 先列提纲再动笔，写完整篇留 5 分钟只做一遍通读检查。动笔前先确认题目要求写几段、用什么语域，避免写到一半推翻结构。","src":"exams.html#ecrit","hint":"先列提纲，再限时成文","quiz":[{"id":"q-writ-a1-5009","level":"A1","skill":"writing","prompt":"「一瓶葡萄酒」正确写法是？","options":["une bouteille de vin","une bouteille du vin","une bouteille le vin"],"answer":"une bouteille de vin","explain":"量词 une bouteille 后用 de + 名词，不加冠词。","source":"语法 · 数量表达"},{"ref":"bank:writing:A1:写作"}]},{"type":"write","title":"提纲与逻辑链","body":"先写中文要点，再逐条译成法语，但译完必须回头改：把中文语序的句子打散重写，让动词和它的补语各就各位。改完把最生硬的 3 句抄到一边，作为下一稿的重点对象。","src":"exams.html#ecrit","hint":"三段式提纲，每段一个论点","quiz":[{"ref":"bank:writing:A1:写作"}]},{"type":"grammar","title":"写前语法自查清单","body":"打开 grammar-a1a2.html#art-part，把本周语法点做成 3 条自查项写在旁边，例如「触发词有没有用对」「变位与配合是否一致」。写完通读只检查这 3 条，其余问题留到第二稿再处理。","src":"grammar-a1a2.html#art-part","hint":"三条自查项，只查这三条","quiz":[{"ref":"bank:grammar:A1:部分冠词"}]},{"type":"read","title":"对照范文找可替换表达","body":"读考试页的范文，列出 10 处「我只会用简单说法、范文用了更地道说法」的对照，抄进表达本。重点看范文怎么用「部分冠词」和连接词，对照表按「我的说法 / 范文说法 / 适用场景」三列记录。","src":"exams.html#redaction","hint":"抄 10 组对照表达","quiz":[{"ref":"bank:reading:A1:阅读"}]},{"type":"speak","title":"把写的文章讲出来","body":"脱稿把自己写的文章讲 2 分钟，允许简化但不许背稿。讲不顺的句子说明书面结构还没内化，回到文中改写一次，再讲一遍；同时把 <span class=\"fr\" data-fr=\"le pain\">le pain</span>（面包）用进口语版本。","src":"exams.html#oral","hint":"脱稿讲 2 分钟，不背稿","quiz":[{"ref":"bank:speaking:A1:口语"}]}]},{"day":7,"theme":"复盘 · 部分冠词、食物与点单场景","type":"review","steps":[{"type":"review","title":"本周回顾：部分冠词、食物与点单场景","body":"这一周围绕「部分冠词、食物与点单场景」展开：语法主线是 部分冠词，词汇主线是 食物与餐饮。先用 3 句话口头复述本周学了什么，再打开日历页第 9 周清单逐条核对里程碑。","src":"calendar.html#wk-9","hint":"先口头复述，再核对里程碑","quiz":[{"ref":"bank:vocab:A1:食物与餐饮"}]},{"type":"review","title":"语法复盘：部分冠词","body":"从 grammar-a1a2.html#art-part 的规则与例句里各抽 3 条：默写规则、翻译例句再对照，最后写下 2 个自己最可能犯的错。凡是默写时卡住的地方，就是下一周要带着继续练的问题。","src":"grammar-a1a2.html#art-part","hint":"默写规则与例句，各抽 3 条","quiz":[{"ref":"bank:grammar:A1:部分冠词"}]},{"type":"review","title":"词汇自测：食物与餐饮","body":"遮住中文看 vocab.html#t6 的 6 个核心词：<span class=\"fr\" data-fr=\"le pain\">le pain</span> <span class=\"fr\" data-fr=\"l'eau\">l'eau</span> <span class=\"fr\" data-fr=\"le fromage\">le fromage</span> <span class=\"fr\" data-fr=\"la viande\">la viande</span> <span class=\"fr\" data-fr=\"une bouteille de vin\">une bouteille de vin</span> <span class=\"fr\" data-fr=\"l'addition\">l'addition</span>。能秒答的划掉，犹豫超过 3 秒的抄进错词本。本周目标是新词认词率不低于 85%。","src":"vocab.html#t6","hint":"遮中文秒答，犹豫即抄错词本","quiz":[{"id":"q-vocab-a1-5033","level":"A1","skill":"vocab","prompt":"« la viande » 的意思是？","options":["肉","蔬菜","水果"],"answer":"肉","explain":"viande 是肉；légume 是蔬菜；fruit 是水果。","source":"词汇 · 食物"},{"id":"q-vocab-a1-5034","level":"A1","skill":"vocab","prompt":"「水」用法语说是？","options":["l'eau","le lait","le jus"],"answer":"l'eau","explain":"eau 以元音开头，定冠词省音写成 l'eau；lait 是牛奶，jus 是果汁。","source":"词汇 · 食物"},{"ref":"bank:vocab:A1:食物与餐饮"}]},{"type":"review","title":"综合题（一）：听读理解","body":"先做下面的听读综合题，不查词、不回看材料，限时 5 分钟。做完再回材料定位每道题的证据句，把「没找到证据就选」的题目标出来——那是失分的主要来源。","src":"dialogue.html#d06","hint":"限时 5 分钟，做完回材料找证据","quiz":[{"id":"q-list-a1-5020","level":"A1","skill":"listening","prompt":"« Je prends du poisson. » 中的 du 表示？","options":["不确定的一部分","特指那条鱼","一条整鱼"],"answer":"不确定的一部分","explain":"du 是部分冠词，表示「一些」；特指用 le poisson。","source":"语法 · 部分冠词"},{"id":"q-read-a1-5018","level":"A1","skill":"reading","prompt":"« des légumes » 中的 des 是？","options":["不定冠词复数或部分冠词","定冠词","缩合冠词"],"answer":"不定冠词复数或部分冠词","explain":"des 既可作复数不定冠词，也可作复数部分冠词，取决于名词是否可数。","source":"语法 · 部分冠词"},{"ref":"bank:listening:A1:听力"}]},{"type":"review","title":"综合题（二）：语法与词汇","body":"这一组题检查 部分冠词 与本周词汇的调用能力。每道题都问自己：错误选项错在哪里？能说出错因才算真的会，说不出来就回到 grammar-a1a2.html#art-part 再核对一次。","src":"grammar-a1a2.html#quant-adv","hint":"每题都说出错项错在哪","quiz":[{"id":"q-gram-a1-5033","level":"A1","skill":"grammar","prompt":"« Il y a ___ fromage dans le frigo. »（肯定句）","options":["du","de","de la"],"answer":"du","explain":"fromage 是阳性不可数名词，肯定句用部分冠词 du；de la 只给阴性名词。","source":"语法 · 部分冠词"},{"id":"q-gram-a1-5034","level":"A1","skill":"grammar","prompt":"「一些苹果」法语说法是？","options":["des pommes","de pommes","du pommes"],"answer":"des pommes","explain":"可数名词复数用 des；du 只用于阳性单数不可数名词。","source":"语法 · 冠词"},{"ref":"bank:grammar:A1:部分冠词"}]},{"type":"review","title":"输出任务与自评表","body":"完成一段 90 秒口述或 120 词短文，内容必须同时用上本周的 2 个词和 1 个语法结构。按「任务完成 / 连贯 / 词汇 / 语法 / 拼写」五项各打 1–5 分，低于 3 分的写进下周补漏清单。","src":"exams.html#oral","hint":"五项各打 1–5 分","quiz":[{"ref":"bank:writing:A1:写作"}]}]}]}];
